/* 統測小翻譯（中譯英）題庫：B1/B2 200 題（T001–T200），加上 A2 入門 25 題（T201–T225）、C1 挑戰 75 題（T226–T250、T276–T325）和 C2 頂尖 75 題（T251–T275、T326–T375）。zh 題目、en 參考答案、alt 其他正確寫法、keys 關鍵字、point 文法重點。 */
window.TRANSLATION_ITEMS = [{"id": "T001", "zh": "我們班上的同學每天早上都要輪流打掃教室。", "en": "Students in our class have to take turns cleaning the classroom every morning.", "alt": ["Every morning, the students in our class have to take turns to clean the classroom."], "keys": [{"en": "take turns", "zh": "輪流"}, {"en": "clean", "zh": "打掃"}], "point": "「take turns + V-ing / to V」表示輪流做某事；描述每天的例行習慣用現在簡單式。", "topic": "classroom duties", "level": "B1"}, {"id": "T002", "zh": "這次期中考太難了，大部分的學生都無法在時間內寫完。", "en": "This midterm exam was too difficult for most students to finish in time.", "alt": ["This midterm exam was so difficult that most students couldn't finish it within the time limit."], "keys": [{"en": "midterm exam", "zh": "期中考"}, {"en": "finish", "zh": "完成；寫完"}], "point": "「too + adj. + for + 人 + to V」表示太…以致於某人無法…，句中不可再用 not。", "topic": "exams", "level": "B1"}, {"id": "T003", "zh": "如果你明天上課再遲到，老師就會打電話給你的父母。", "en": "If you are late for class again tomorrow, the teacher will call your parents.", "alt": ["Your teacher will call your parents if you're late for class again tomorrow."], "keys": [{"en": "be late for", "zh": "（上課、上班等）遲到"}, {"en": "call", "zh": "打電話給"}], "point": "表未來可能情況的條件句：「If + 現在式, S + will + V」，if 子句不用 will；上課遲到為 be late for class。", "topic": "school rules", "level": "B1"}, {"id": "T004", "zh": "我以前每天放學後都會去圖書館讀書，但現在我比較喜歡在家讀。", "en": "I used to study in the library every day after school, but now I prefer to study at home.", "alt": ["I used to go to the library to study every day after school, but now I prefer studying at home."], "keys": [{"en": "used to", "zh": "以前常常"}, {"en": "after school", "zh": "放學後"}, {"en": "prefer", "zh": "比較喜歡"}], "point": "「used to + 原形V」表示過去的習慣、現在已不再如此；「prefer to V / V-ing」表示比較喜歡做某事。", "topic": "study habits", "level": "B1"}, {"id": "T005", "zh": "剛上高中時，我還不習慣每天早上七點前就到學校。", "en": "When I first started senior high school, I wasn't used to arriving at school before seven every morning.", "alt": ["When I was new to senior high school, I was not used to getting to school before 7 a.m. every day."], "keys": [{"en": "be used to", "zh": "習慣於"}, {"en": "arrive at", "zh": "抵達"}], "point": "「be used to + V-ing」表示習慣於做某事，to 是介系詞，後接動名詞；勿與「used to + 原形V」（以前常常）混淆。", "topic": "school routine", "level": "B2"}, {"id": "T006", "zh": "這場英文演講比賽的結果將在下週一公布。", "en": "The results of the English speech contest will be announced next Monday.", "alt": ["The English speech contest results will be announced next Monday."], "keys": [{"en": "result", "zh": "結果"}, {"en": "announce", "zh": "公布；宣布"}, {"en": "speech contest", "zh": "演講比賽"}], "point": "主詞是事物（結果）時用被動語態；未來式被動為「will be + p.p.」。", "topic": "school events", "level": "B1"}, {"id": "T007", "zh": "坐在我隔壁的那個女生是我們班上數學最好的學生。", "en": "The girl who sits next to me is the best math student in our class.", "alt": ["The girl sitting next to me is the best math student in our class."], "keys": [{"en": "sit next to", "zh": "坐在…旁邊"}, {"en": "math", "zh": "數學"}], "point": "關係代名詞 who 引導形容詞子句修飾人，也可簡化為分詞片語 sitting next to me；最高級用「the best … in + 範圍」。", "topic": "classmates", "level": "B1"}, {"id": "T008", "zh": "對我來說，學英文比學數學有趣得多。", "en": "For me, learning English is much more interesting than learning math.", "alt": ["I find learning English much more interesting than learning math."], "keys": [{"en": "much more", "zh": "…得多；更加"}, {"en": "interesting", "zh": "有趣的"}], "point": "比較級「much + 比較級 + than」表示…得多；動名詞片語 learning English 可當主詞，比較的兩邊須對等（learning … than learning …）。", "topic": "school subjects", "level": "B1"}, {"id": "T009", "zh": "老師的解釋非常清楚，所以全班同學很快就懂了。", "en": "The teacher's explanation was so clear that the whole class understood it right away.", "alt": ["The teacher explained it so clearly that everyone in the class understood it quickly."], "keys": [{"en": "explanation", "zh": "解釋；說明"}, {"en": "understand", "zh": "理解；懂"}], "point": "「so + adj./adv. + that + 子句」表示如此…以致於…；so 後接形容詞（clear）或副詞（clearly）視句子結構而定。", "topic": "teachers", "level": "B1"}, {"id": "T010", "zh": "那本小說好看到我一個晚上就把它看完了。", "en": "It was such a good novel that I finished reading it in one night.", "alt": ["That novel was so good that I finished it in just one night."], "keys": [{"en": "such", "zh": "如此的；這麼"}, {"en": "novel", "zh": "小說"}, {"en": "finish", "zh": "完成；看完"}], "point": "「such + a/an + adj. + 單數名詞 + that + 子句」表示如此…以致於…；改用 so 時語序為「so + adj. + that + 子句」；finish 後接動名詞（finish reading）。", "topic": "reading", "level": "B1"}, {"id": "T011", "zh": "王老師不但教學認真，而且非常關心每一位學生。", "en": "Mr. Wang not only takes his teaching seriously but also really cares about every student.", "alt": ["Not only does Mr. Wang take his teaching seriously, but he also cares a lot about each of his students."], "keys": [{"en": "seriously", "zh": "認真地"}, {"en": "care about", "zh": "關心"}], "point": "「not only A but also B」連接詞性對等的動詞片語（takes / cares）；Not only 置於句首時須倒裝（Not only does + S + V…）。", "topic": "teachers", "level": "B2"}, {"id": "T012", "zh": "我每天搭捷運到學校大約要花四十分鐘。", "en": "It takes me about forty minutes to get to school by MRT every day.", "alt": ["Taking the MRT to school takes me about forty minutes every day.", "I spend about forty minutes getting to school by MRT every day."], "keys": [{"en": "take", "zh": "花費（時間）"}, {"en": "get to", "zh": "抵達"}, {"en": "MRT", "zh": "捷運"}], "point": "「It takes + 人 + 時間 + to V」表示某人做某事花多少時間；也可用「人 + spend + 時間 + V-ing」。", "topic": "commuting to school", "level": "B1"}, {"id": "T013", "zh": "為了準備統測，他決定每天放學後留在學校自習。", "en": "To prepare for the college entrance exam, he decided to stay after school every day to study on his own.", "alt": ["In order to prepare for the college entrance exam, he decided to stay at school after classes every day and study by himself."], "keys": [{"en": "prepare for", "zh": "為…做準備"}, {"en": "decide", "zh": "決定"}, {"en": "entrance exam", "zh": "入學考試"}], "point": "句首「To V / In order to V」表示目的；「decide + to V」表示決定做某事；放學後留校可用 stay after school，自習可譯為 study on one's own / by oneself。", "topic": "exam preparation", "level": "B1"}, {"id": "T014", "zh": "你應該避免在考試前一晚熬夜，才能保持頭腦清醒。", "en": "You should avoid staying up late the night before an exam so that you can keep a clear head.", "alt": ["To keep a clear head, you should avoid staying up late on the night before a test."], "keys": [{"en": "avoid", "zh": "避免"}, {"en": "stay up late", "zh": "熬夜"}], "point": "「avoid + V-ing」表示避免做某事，avoid 後不可接不定詞；「so that + S + can + V」表示目的（以便…）。", "topic": "exam preparation", "level": "B2"}, {"id": "T015", "zh": "如果我是你，我會先把作業寫完再去打電動。", "en": "If I were you, I would finish my homework before playing video games.", "alt": ["If I were you, I'd finish my homework first and then play video games."], "keys": [{"en": "finish", "zh": "完成"}, {"en": "homework", "zh": "作業"}, {"en": "video game", "zh": "電動；電玩"}], "point": "與現在事實相反的假設語氣：「If + S + were…, S + would + 原形V」，be 動詞一律用 were；介系詞 before 後接動名詞。", "topic": "homework", "level": "B2"}, {"id": "T016", "zh": "你昨天應該複習課本，而不是一直在滑手機。", "en": "You should have reviewed your textbook yesterday instead of scrolling through your phone the whole time.", "alt": ["Yesterday you should have reviewed your textbook instead of spending all your time on your phone."], "keys": [{"en": "review", "zh": "複習"}, {"en": "textbook", "zh": "課本"}, {"en": "instead of", "zh": "而不是；代替"}], "point": "「should have + p.p.」表示過去應該做卻沒做（帶有後悔或責備）；instead of 為介系詞片語，後接 V-ing。", "topic": "studying", "level": "B2"}, {"id": "T017", "zh": "老師提醒我們，週五以前一定要交出科學報告。", "en": "The teacher reminded us that we had to hand in our science reports by Friday.", "alt": ["Our teacher reminded us to hand in our science reports by Friday.", "The teacher reminded us that our science reports must be turned in by Friday."], "keys": [{"en": "remind", "zh": "提醒"}, {"en": "hand in", "zh": "繳交"}, {"en": "report", "zh": "報告"}], "point": "「remind + 人 + to V」或「remind + 人 + that 子句」表示提醒某人做某事；hand in = turn in（繳交），by Friday 表示「在週五以前」。", "topic": "assignments", "level": "B1"}, {"id": "T018", "zh": "自從加入籃球隊以後，我交到了很多好朋友。", "en": "Since I joined the basketball team, I have made a lot of good friends.", "alt": ["I've made many good friends since joining the basketball team."], "keys": [{"en": "join", "zh": "加入"}, {"en": "basketball team", "zh": "籃球隊"}, {"en": "make", "zh": "結交（朋友）"}], "point": "「since + 過去式子句」搭配主要子句的現在完成式（have + p.p.），表示從過去某時持續到現在的經驗或結果；交朋友用 make friends。", "topic": "school clubs", "level": "B1"}, {"id": "T019", "zh": "老師走進教室的時候，大家正在熱烈地討論昨天的考試。", "en": "When the teacher walked into the classroom, everyone was excitedly discussing yesterday's exam.", "alt": ["Everyone was excitedly discussing yesterday's exam when the teacher came into the classroom.", "Everyone was having a lively discussion about yesterday's exam when the teacher walked into the classroom."], "keys": [{"en": "walk into", "zh": "走進"}, {"en": "discuss", "zh": "討論"}], "point": "過去進行式「was/were + V-ing」表示過去某時正在進行的動作，when 子句用過去簡單式；discuss 為及物動詞，後面不加 about。", "topic": "classroom life", "level": "B1"}, {"id": "T020", "zh": "儘管這次段考成績不理想，他並沒有放棄，反而更加努力讀書。", "en": "Although he didn't do well on this exam, he didn't give up; instead, he studied even harder.", "alt": ["Even though he didn't get a good score on this exam, he didn't give up. Instead, he studied even harder."], "keys": [{"en": "do well", "zh": "表現好；考得好"}, {"en": "give up", "zh": "放棄"}, {"en": "instead", "zh": "反而"}], "point": "although / even though 引導讓步子句，英文不可再與 but 連用；比較級前加 even 表示「更加…」。", "topic": "exams", "level": "B2"}, {"id": "T021", "zh": "班長負責在上課前把作業收齊並交給老師。", "en": "The class leader is responsible for collecting all the homework and handing it to the teacher before class.", "alt": ["The class leader is in charge of collecting everyone's homework and handing it to the teacher before class.", "Before class starts, the class leader is responsible for collecting everyone's homework and giving it to the teacher."], "keys": [{"en": "be responsible for", "zh": "負責"}, {"en": "collect", "zh": "收集；收齊"}], "point": "「be responsible for + N / V-ing」表示負責…，for 是介系詞，後接動名詞；兩個動名詞 collecting 與 handing 以 and 對等連接。", "topic": "class duties", "level": "B1"}, {"id": "T022", "zh": "全班同學都很期待下個月去台南的畢業旅行。", "en": "Everyone in our class is really looking forward to the graduation trip to Tainan next month.", "alt": ["All of my classmates are really looking forward to next month's graduation trip to Tainan."], "keys": [{"en": "look forward to", "zh": "期待"}, {"en": "graduation trip", "zh": "畢業旅行"}], "point": "「look forward to + N / V-ing」表示期待，to 是介系詞；everyone 當主詞時動詞用單數。", "topic": "school trips", "level": "B1"}, {"id": "T023", "zh": "他的英文程度已經好到可以看懂沒有字幕的英文影片了。", "en": "His English is now good enough for him to understand English videos without subtitles.", "alt": ["His English has become so good that he can understand English videos without subtitles."], "keys": [{"en": "enough", "zh": "足夠地"}, {"en": "subtitle", "zh": "字幕"}], "point": "「adj. + enough (+ for 人) + to V」表示夠…而能…，enough 修飾形容詞時須放在形容詞後面。", "topic": "learning English", "level": "B2"}, {"id": "T024", "zh": "很多學生在背英文單字時遇到困難，因為他們常常很快就忘記。", "en": "Many students have trouble memorizing English words because they often forget them quickly.", "alt": ["Many students have difficulty memorizing English vocabulary because they tend to forget the words very quickly."], "keys": [{"en": "have trouble", "zh": "有困難"}, {"en": "memorize", "zh": "背誦；記住"}, {"en": "forget", "zh": "忘記"}], "point": "「have trouble / difficulty (in) + V-ing」表示做某事有困難，後接動名詞而非不定詞。", "topic": "vocabulary learning", "level": "B2"}, {"id": "T025", "zh": "數學老師常讓我們分組討論，再請各組上台報告。", "en": "Our math teacher often lets us have group discussions and then asks each group to give a presentation in front of the class.", "alt": ["Our math teacher often divides us into groups for discussion and then asks each group to give a presentation in front of the class."], "keys": [{"en": "group discussion", "zh": "分組討論"}, {"en": "ask", "zh": "請；要求"}, {"en": "give a presentation", "zh": "上台報告"}], "point": "使役動詞「let / have + 受詞 + 原形V」；「ask + 受詞 + to V」表示請某人做某事。", "topic": "classroom activities", "level": "B2"}, {"id": "T026", "zh": "小時候，爸爸每個週末都會帶我去公園騎腳踏車。", "en": "When I was little, my dad used to take me to the park to ride my bike every weekend.", "alt": ["My dad would take me to the park to ride my bike every weekend when I was a kid.", "When I was young, my father used to take me to the park to ride a bicycle every weekend."], "keys": [{"en": "used to", "zh": "過去常常"}, {"en": "take someone to", "zh": "帶某人去"}], "point": "「used to + 原形V」表示過去常常做、現在已不再做的習慣；也可用 would + 原形V 表示過去的習慣。", "topic": "Childhood with family", "level": "B1"}, {"id": "T027", "zh": "因為父母必須到外地工作，我是由祖父母撫養長大的。", "en": "Because my parents had to work in another city, I was brought up by my grandparents.", "alt": ["I was raised by my grandparents because my parents had to work away from home.", "My grandparents brought me up because my parents had to work in another city."], "keys": [{"en": "bring up", "zh": "撫養；養育"}, {"en": "have to", "zh": "必須"}], "point": "bring up 表示撫養長大，被動語態為 be brought up by…（= be raised by）；過去的「必須」用 had to。", "topic": "Family upbringing", "level": "B2"}, {"id": "T028", "zh": "每天早上，我媽媽要花大約半小時為全家人準備早餐。", "en": "It takes my mother about half an hour to prepare breakfast for the whole family every morning.", "alt": ["Every morning, my mom spends about half an hour preparing breakfast for the whole family.", "My mother needs about thirty minutes to make breakfast for the whole family every morning."], "keys": [{"en": "prepare", "zh": "準備"}, {"en": "half an hour", "zh": "半小時"}, {"en": "the whole family", "zh": "全家人"}], "point": "「It takes + 人 + 時間 + to V」表示某人做某事要花多少時間；也可改寫為「人 + spend + 時間 + V-ing」。", "topic": "Family routines", "level": "B1"}, {"id": "T029", "zh": "我哥哥比我大三歲，但是他看起來比我還年輕。", "en": "My brother is three years older than I am, but he looks younger than I do.", "alt": ["My brother is three years older than me, but he looks younger than me.", "Although my brother is three years older than I am, he looks younger than I do."], "keys": [{"en": "older than", "zh": "比…年長"}, {"en": "look", "zh": "看起來（連綴動詞）"}], "point": "比較級「數字 + years + older than」表示大幾歲；look 為連綴動詞，後接形容詞 younger，不可接副詞。", "topic": "Siblings", "level": "B1"}, {"id": "T030", "zh": "我阿姨不但很會煮菜，而且也很擅長照顧小孩。", "en": "My aunt is not only good at cooking but also good at taking care of children.", "alt": ["Not only does my aunt cook very well, but she is also good at taking care of kids.", "My aunt is great not only at cooking but also at taking care of children."], "keys": [{"en": "be good at", "zh": "擅長"}, {"en": "take care of", "zh": "照顧"}], "point": "「not only A but also B」連接的 A、B 須為對等結構；not only 移到句首時，主要子句要倒裝（Not only does my aunt cook…）。", "topic": "Relatives", "level": "B2"}, {"id": "T031", "zh": "住在花蓮的外婆每年過年前都會寄一大箱水果給我們。", "en": "My grandmother, who lives in Hualien, sends us a big box of fruit before Lunar New Year every year.", "alt": ["Every year before Lunar New Year, my grandma, who lives in Hualien, sends a large box of fruit to us.", "My grandmother in Hualien sends us a big box of fruit every year before Chinese New Year."], "keys": [{"en": "send", "zh": "寄送"}, {"en": "a box of", "zh": "一箱…"}, {"en": "Lunar New Year", "zh": "農曆新年；過年"}], "point": "外婆是特定的一位，可用非限定用法（逗號 + who）補充說明「住在花蓮」；也可直接用介系詞片語 in Hualien 修飾。send + 人 + 物 = send + 物 + to + 人。", "topic": "Grandparents", "level": "B2"}, {"id": "T032", "zh": "奶奶的記性越來越差，常常忘記自己把鑰匙放在哪裡。", "en": "My grandmother's memory is getting worse and worse, and she often forgets where she put her keys.", "alt": ["My grandma is becoming more and more forgetful and often can't remember where she put her keys.", "Grandma's memory is getting worse and worse, and she often forgets where she has left her keys."], "keys": [{"en": "memory", "zh": "記性；記憶力"}, {"en": "worse and worse", "zh": "越來越差"}, {"en": "forget", "zh": "忘記"}], "point": "「比較級 + and + 比較級」表示越來越…（worse and worse / more and more forgetful）；forget 後接 where 引導的名詞子句（間接問句），須用直述句語序 where she put her keys，不可寫成 where did she put her keys。", "topic": "Grandparents", "level": "B1"}, {"id": "T033", "zh": "那部電影太好笑了，我和朋友們一直笑個不停。", "en": "The movie was so funny that my friends and I couldn't stop laughing.", "alt": ["It was such a funny movie that my friends and I couldn't stop laughing.", "The film was so funny that my friends and I kept laughing the whole time."], "keys": [{"en": "funny", "zh": "好笑的"}, {"en": "stop", "zh": "停止（+ V-ing）"}, {"en": "laugh", "zh": "笑"}], "point": "「so + adj. + that…」與「such + a + adj. + N + that…」表示如此…以致於；stop + V-ing 表示停止正在做的事；「我和朋友」英文習慣說 my friends and I。", "topic": "Hanging out with friends", "level": "B1"}, {"id": "T034", "zh": "我的新同學很好相處，所以她很快就和班上每個人成為朋友。", "en": "My new classmate is easy to get along with, so she quickly became friends with everyone in our class.", "alt": ["My new classmate gets along well with others, so she soon became friends with everyone in our class.", "Because my new classmate is easy to get along with, she quickly made friends with everyone in the class."], "keys": [{"en": "get along with", "zh": "與…相處"}, {"en": "become friends with", "zh": "與…成為朋友"}], "point": "「人 + be easy to get along with」表示某人很好相處，句尾的介系詞 with 不可省略；become/make friends with 中的 friends 須用複數。", "topic": "Making friends", "level": "B1"}, {"id": "T035", "zh": "我和隔壁鄰居從國小就認識彼此，到現在還是好朋友。", "en": "My next-door neighbor and I have known each other since elementary school, and we are still good friends.", "alt": ["I have known my next-door neighbor since elementary school, and we are still good friends today.", "My next-door neighbor and I have known each other since we were in elementary school, and we are still close friends."], "keys": [{"en": "each other", "zh": "彼此"}, {"en": "since", "zh": "自從（接過去時間點）"}, {"en": "elementary school", "zh": "國小"}], "point": "「since + 過去時間點」搭配現在完成式（have + p.p.），表示從過去持續到現在的狀態；know 為狀態動詞，不用進行式。", "topic": "Childhood friends", "level": "B1"}, {"id": "T036", "zh": "如果你昨天有告訴我你心情不好，我就會去陪你了。", "en": "If you had told me yesterday that you were in a bad mood, I would have kept you company.", "alt": ["Had you told me yesterday that you were in a bad mood, I would have kept you company.", "If you had let me know yesterday that you were feeling down, I would have come over to be with you."], "keys": [{"en": "in a bad mood", "zh": "心情不好"}, {"en": "keep someone company", "zh": "陪伴某人"}], "point": "與過去事實相反的假設：「If + S + had + p.p.…, S + would have + p.p.」；省略 if 時須倒裝為「Had + S + p.p.」。", "topic": "Supporting friends", "level": "B2"}, {"id": "T037", "zh": "雖然我們讀不同的高中，我和國中同學仍然保持聯絡。", "en": "Although we go to different high schools, my junior high classmates and I still keep in touch.", "alt": ["My junior high classmates and I still keep in touch even though we go to different high schools.", "Although my junior high classmates and I attend different senior high schools, we still stay in touch."], "keys": [{"en": "keep in touch", "zh": "保持聯絡"}, {"en": "although", "zh": "雖然"}], "point": "keep in touch (with + 人) 表示與某人保持聯絡；although 與 but 不可在同一句中連用。", "topic": "Old classmates", "level": "B1"}, {"id": "T038", "zh": "我很後悔對最好的朋友說了那些傷人的話。", "en": "I really regret saying those hurtful things to my best friend.", "alt": ["I deeply regret having said those hurtful things to my best friend.", "I feel really sorry that I said those hurtful words to my best friend."], "keys": [{"en": "regret", "zh": "後悔"}, {"en": "hurtful", "zh": "傷人的"}], "point": "「regret + V-ing」表示後悔做過某事；「regret + to V」則表示遺憾要（告知）某事，兩者意思不同。", "topic": "Friendship problems", "level": "B1"}, {"id": "T039", "zh": "得知最喜歡的歌手取消了演唱會，她感到非常失望。", "en": "She felt very disappointed when she learned that her favorite singer had canceled the concert.", "alt": ["She was really disappointed to learn that her favorite singer had canceled the concert.", "Learning that her favorite singer had called off the concert, she felt very disappointed."], "keys": [{"en": "disappointed", "zh": "失望的"}, {"en": "cancel", "zh": "取消"}, {"en": "concert", "zh": "演唱會"}], "point": "描述人的感受用 -ed 形容詞（disappointed），描述令人…的事物用 -ing（disappointing）；取消發生在得知之前，用過去完成式 had canceled。", "topic": "Disappointment", "level": "B1"}, {"id": "T040", "zh": "不論遇到什麼困難，她總是保持積極樂觀的態度。", "en": "No matter what difficulties she faces, she always keeps a positive and optimistic attitude.", "alt": ["She always keeps a positive and optimistic attitude no matter what problems she runs into.", "Whatever difficulties she faces, she always stays positive and optimistic."], "keys": [{"en": "no matter what", "zh": "不論什麼"}, {"en": "positive", "zh": "積極的；正面的"}, {"en": "attitude", "zh": "態度"}], "point": "「No matter what + N + S + V」= Whatever + N + S + V，表示不論什麼；keep a positive attitude 為常見搭配。", "topic": "Attitudes", "level": "B2"}, {"id": "T041", "zh": "我對明天的鋼琴比賽太緊張了，根本睡不著。", "en": "I am too nervous about tomorrow's piano competition to fall asleep.", "alt": ["I'm so nervous about tomorrow's piano competition that I can't fall asleep.", "Tomorrow's piano competition makes me so nervous that I can't get to sleep."], "keys": [{"en": "nervous", "zh": "緊張的"}, {"en": "competition", "zh": "比賽；競賽"}, {"en": "fall asleep", "zh": "入睡"}], "point": "「too + adj. + to V」表示太…而無法…，本身已含否定意味，不可再加 not；可改寫為「so + adj. + that + S + can't + V」。", "topic": "Nervousness", "level": "B1"}, {"id": "T042", "zh": "陌生人的一個微笑，就能讓人一整天心情都很好。", "en": "Just one smile from a stranger can make people feel happy all day long.", "alt": ["A single smile from a stranger can make someone feel good for the whole day.", "Just a smile from a stranger can put people in a good mood all day long."], "keys": [{"en": "stranger", "zh": "陌生人"}, {"en": "make", "zh": "使（make + O + 原形V）"}, {"en": "all day long", "zh": "一整天"}], "point": "使役動詞 make + 受詞 + 原形動詞（feel），不可接 to feel；改為被動時才用 be made to V。", "topic": "Happiness", "level": "B1"}, {"id": "T043", "zh": "與其一直抱怨，不如想想自己能做些什麼來改善情況。", "en": "Rather than complaining all the time, you should think about what you can do to improve the situation.", "alt": ["You should think about what you can do to improve the situation instead of complaining all the time.", "Instead of always complaining, think about what you can do to make the situation better."], "keys": [{"en": "rather than", "zh": "與其；而不是"}, {"en": "complain", "zh": "抱怨"}, {"en": "improve", "zh": "改善"}], "point": "「與其A，不如B」可用「Rather than / Instead of + V-ing, S + should + V」；what you can do 為名詞子句，當 think about 的受詞，須用直述句語序。", "topic": "Attitudes", "level": "B2"}, {"id": "T044", "zh": "讀到好朋友寫給她的生日卡片時，她忍不住哭了出來。", "en": "When she read the birthday card that her good friend had written to her, she couldn't help crying.", "alt": ["She couldn't help crying when she read the birthday card her good friend had written for her.", "Reading the birthday card from her good friend, she couldn't hold back her tears."], "keys": [{"en": "can't help", "zh": "忍不住（+ V-ing）"}, {"en": "cry", "zh": "哭"}, {"en": "birthday card", "zh": "生日卡片"}], "point": "「can't help + V-ing」表示忍不住…；寫卡片發生在讀卡片之前，用過去完成式 had written；受格關係代名詞 that 可省略。", "topic": "Emotions", "level": "B2"}, {"id": "T045", "zh": "在捷運上大聲講手機很沒禮貌，會打擾到其他乘客。", "en": "It is rude to talk loudly on the phone on the MRT because it disturbs other passengers.", "alt": ["Talking loudly on your phone on the MRT is rude because it bothers other passengers.", "It is bad manners to talk loudly on your cell phone on the MRT, since it disturbs other passengers."], "keys": [{"en": "rude", "zh": "無禮的"}, {"en": "disturb", "zh": "打擾"}, {"en": "passenger", "zh": "乘客"}], "point": "「It is + adj. + to V」以虛主詞 it 代替後面的不定詞片語；talk on the phone 表示「講電話」。", "topic": "Public manners", "level": "B1"}, {"id": "T046", "zh": "在便利商店結帳時，我們應該排隊等候，絕對不可以插隊。", "en": "When checking out at a convenience store, we should wait our turn and never cut in line.", "alt": ["When we pay at a convenience store, we should line up and never cut in line.", "We should wait in line when paying at a convenience store and never cut in front of others."], "keys": [{"en": "convenience store", "zh": "便利商店"}, {"en": "wait one's turn", "zh": "等候輪到自己"}, {"en": "cut in line", "zh": "插隊"}], "point": "When + V-ing 為分詞構句，由 When we check out 省略主詞並將動詞改為 V-ing（前提是與主要子句主詞相同）；cut in line 表示插隊。", "topic": "Waiting in line", "level": "B1"}, {"id": "T047", "zh": "如果你不小心撞到別人，應該馬上向對方道歉。", "en": "If you accidentally bump into someone, you should apologize to that person right away.", "alt": ["If you bump into someone by accident, you should apologize to them right away.", "You should say sorry right away if you accidentally bump into someone."], "keys": [{"en": "bump into", "zh": "撞到"}, {"en": "apologize to", "zh": "向…道歉"}, {"en": "right away", "zh": "立刻"}], "point": "「apologize to + 人 + for + 事」表示向某人為某事道歉；If 子句用現在式表示一般情況，主要子句用 should + 原形V 提出建議。", "topic": "Polite behavior", "level": "B1"}, {"id": "T048", "zh": "在圖書館裡，大家都被要求把手機調成靜音並降低說話音量。", "en": "In the library, everyone is asked to put their phones on silent and keep their voices down.", "alt": ["Everyone in the library is asked to switch their cell phones to silent mode and keep their voices down.", "In the library, people are required to set their phones to silent and speak quietly."], "keys": [{"en": "be asked to", "zh": "被要求（做）"}, {"en": "keep one's voice down", "zh": "壓低音量"}, {"en": "silent", "zh": "靜音的；安靜的"}], "point": "「ask + 人 + to V」改為被動時是「人 + be asked to V」；everyone 視為單數，動詞用 is。", "topic": "Library manners", "level": "B2"}, {"id": "T049", "zh": "請問你介不介意把背包拿下來，讓後面的人有更多空間？", "en": "Would you mind taking off your backpack so that the people behind you have more room?", "alt": ["Would you mind taking your backpack off so that the people behind you can have more space?", "Do you mind taking off your backpack to give the people behind you more room?"], "keys": [{"en": "would you mind", "zh": "你介意…嗎"}, {"en": "take off", "zh": "脫下；取下"}, {"en": "so that", "zh": "以便"}], "point": "「Would you mind + V-ing…?」是禮貌的請求句型，mind 後接動名詞；so that 引導表示目的的副詞子句。", "topic": "Polite requests", "level": "B2"}, {"id": "T050", "zh": "用餐時，嘴裡含著食物說話被認為是不禮貌的行為。", "en": "Talking with your mouth full during a meal is considered bad manners.", "alt": ["It is considered impolite to talk with food in your mouth while eating.", "Speaking with your mouth full at the table is regarded as bad manners."], "keys": [{"en": "with one's mouth full", "zh": "嘴裡含著食物；滿嘴食物"}, {"en": "be considered", "zh": "被認為"}, {"en": "bad manners", "zh": "沒禮貌的行為"}], "point": "動名詞片語當主詞時，動詞用單數；「be considered (to be) + N/adj.」表示被認為是…；with + O + adj. 表示附帶狀況。", "topic": "Table manners", "level": "B2"}, {"id": "T051", "zh": "我直到看到健康檢查的結果，才開始少喝含糖飲料。", "en": "I didn't start drinking fewer sugary drinks until I saw the results of my health checkup.", "alt": ["It wasn't until I saw the results of my health checkup that I started drinking fewer sugary drinks.", "I didn't start cutting back on sugary drinks until I saw my health checkup results."], "keys": [{"en": "until", "zh": "直到"}, {"en": "checkup", "zh": "健康檢查"}, {"en": "sugary", "zh": "含糖的"}], "point": "「S + not + V + until + 子句」表示直到…才…，主要子句須用否定；也可改寫為強調句型「It was not until + 子句 + that + S + V」。", "topic": "healthy drinks", "level": "B2"}, {"id": "T052", "zh": "每天早上，我們都可以在公園裡看到很多老人家在打太極拳。", "en": "Every morning, we can see many elderly people doing tai chi in the park.", "alt": ["We can see lots of older people practicing tai chi in the park every morning.", "Every morning in the park, we can see a lot of elderly people practicing tai chi."], "keys": [{"en": "elderly", "zh": "年長的；上了年紀的"}, {"en": "do tai chi", "zh": "打太極拳"}], "point": "感官動詞「see + 受詞 + V-ing」表示看到某人正在做某事；若要表示看到動作從頭到尾的全部過程，則用「see + 受詞 + 原形V」。", "topic": "morning exercise", "level": "B1"}, {"id": "T053", "zh": "從嚴重的運動傷害中完全復原，可能需要好幾個月的時間。", "en": "It may take several months to fully recover from a serious sports injury.", "alt": ["Fully recovering from a serious sports injury may take several months.", "A full recovery from a serious sports injury can take several months."], "keys": [{"en": "recover from", "zh": "從…中復原"}, {"en": "injury", "zh": "傷害；受傷"}, {"en": "serious", "zh": "嚴重的"}], "point": "「It takes + 時間 + to V」表示做某事需要多少時間；recover from 表示從疾病或傷害中復原。", "topic": "sports injuries", "level": "B2"}, {"id": "T054", "zh": "這碗牛肉麵太燙了，我現在沒辦法吃。", "en": "This bowl of beef noodle soup is too hot for me to eat right now.", "alt": ["This bowl of beef noodle soup is so hot that I can't eat it right now."], "keys": [{"en": "bowl", "zh": "碗"}, {"en": "beef noodle soup", "zh": "牛肉麵"}], "point": "「too + adj. + for + 人 + to V」表示太…而某人無法…；句尾不可再加受詞 it，但改用 so…that 時須補上 it。", "topic": "food", "level": "B1"}, {"id": "T055", "zh": "為了安全起見，未滿十二歲的兒童不可以單獨進入游泳池。", "en": "For safety reasons, children under twelve are not allowed to enter the swimming pool alone.", "alt": ["For safety reasons, children under the age of twelve are not allowed to go into the swimming pool by themselves.", "For safety reasons, children under twelve may not enter the swimming pool alone."], "keys": [{"en": "allow", "zh": "允許"}, {"en": "safety", "zh": "安全"}, {"en": "alone", "zh": "單獨地；獨自"}], "point": "「allow + 人 + to V」的被動式為「人 + be allowed to V」，表示被允許做…；否定的 be not allowed to V 即「不准、不可以」做…。under + 數字表示「未滿…（歲）」。", "topic": "swimming", "level": "B1"}, {"id": "T056", "zh": "那場籃球比賽實在太精彩了，觀眾們從頭到尾都站著歡呼。", "en": "The basketball game was so exciting that the spectators stood and cheered from beginning to end.", "alt": ["It was such an exciting basketball game that the spectators stood and cheered from start to finish."], "keys": [{"en": "exciting", "zh": "令人興奮的；精彩的"}, {"en": "spectator", "zh": "觀眾"}, {"en": "cheer", "zh": "歡呼"}], "point": "「so + adj. + that + 子句」表示如此…以致於…；名詞前則用「such + a/an + adj. + N + that」。", "topic": "basketball", "level": "B1"}, {"id": "T057", "zh": "規律運動不但能讓身體更健康，還能幫助我們減輕壓力。", "en": "Regular exercise can not only make our bodies healthier but also help us reduce stress.", "alt": ["Exercising regularly not only makes our bodies healthier but also helps us reduce stress."], "keys": [{"en": "regular", "zh": "規律的；定期的"}, {"en": "reduce", "zh": "減少；減輕"}, {"en": "stress", "zh": "壓力"}], "point": "「not only A but also B」連接對等結構，A 與 B 詞性須一致（此處皆為原形動詞 make / help）。", "topic": "exercise benefits", "level": "B2"}, {"id": "T058", "zh": "這家餐廳所有的食物都是用當地新鮮的食材做成的。", "en": "All the food at this restaurant is made with fresh local ingredients.", "alt": ["Every dish at this restaurant is made with fresh, local ingredients."], "keys": [{"en": "ingredient", "zh": "食材；原料"}, {"en": "local", "zh": "當地的"}, {"en": "fresh", "zh": "新鮮的"}], "point": "主詞「食物」是被製作的一方，用被動語態「be + p.p.」；be made with 表示用…（材料）做成。", "topic": "restaurant food", "level": "B1"}, {"id": "T059", "zh": "研究顯示，每天睡不到六小時的人比較容易生病。", "en": "Studies show that people who sleep less than six hours a day are more likely to get sick.", "alt": ["Research shows that those who sleep less than six hours a day tend to get sick more easily."], "keys": [{"en": "likely", "zh": "很可能的"}, {"en": "get sick", "zh": "生病"}], "point": "「people who + V」以關係子句修飾先行詞；「be more likely to V」表示比較可能、比較容易…。", "topic": "sleep and health", "level": "B2"}, {"id": "T060", "zh": "如果你每天晚上都滑手機到半夜，隔天上課一定會很想睡覺。", "en": "If you use your phone until midnight every night, you will definitely feel sleepy in class the next day.", "alt": ["If you keep using your phone until midnight every night, you will surely be sleepy in class the next day."], "keys": [{"en": "midnight", "zh": "半夜；午夜"}, {"en": "sleepy", "zh": "想睡的"}], "point": "條件句「If + 現在簡單式, 主詞 + will + 原形V」表示對未來可能結果的推測，if 子句不用 will。", "topic": "sleep habits", "level": "B1"}, {"id": "T061", "zh": "要是我昨天比賽前有先做暖身運動，腳踝就不會扭傷了。", "en": "If I had warmed up before the game yesterday, I wouldn't have sprained my ankle.", "alt": ["Had I warmed up before yesterday's game, I wouldn't have sprained my ankle.", "If I had done warm-up exercises before yesterday's game, I would not have sprained my ankle."], "keys": [{"en": "warm up", "zh": "暖身"}, {"en": "sprain", "zh": "扭傷"}, {"en": "ankle", "zh": "腳踝"}], "point": "與過去事實相反的假設用「If + had + p.p., 主詞 + would have + p.p.」；省略 if 時可倒裝為「Had + 主詞 + p.p.」。", "topic": "sports injuries", "level": "B2"}, {"id": "T062", "zh": "醫生建議我少吃油炸食物，多吃蔬菜水果。", "en": "The doctor advised me to eat less fried food and more fruit and vegetables.", "alt": ["The doctor suggested that I eat less fried food and more fruit and vegetables."], "keys": [{"en": "advise", "zh": "建議；勸告"}, {"en": "fried", "zh": "油炸的"}], "point": "「advise + 人 + to V」表示建議某人做某事；suggest 則接「that + 主詞 + (should) + 原形V」，不可接「人 + to V」。", "topic": "diet", "level": "B1"}, {"id": "T063", "zh": "每天走路上學是一個保持健康又省錢的好方法。", "en": "Walking to school every day is a good way to stay healthy and save money.", "alt": ["Going to school on foot every day is a great way to stay healthy and save money."], "keys": [{"en": "stay healthy", "zh": "保持健康"}, {"en": "save money", "zh": "省錢"}], "point": "動名詞（V-ing）片語可當主詞，視為單數，動詞用 is；「a good way to V」表示做某事的好方法。", "topic": "healthy habits", "level": "B1"}, {"id": "T064", "zh": "自從開始每週上三次健身房後，他已經瘦了五公斤。", "en": "Since he started going to the gym three times a week, he has lost five kilograms.", "alt": ["He has lost five kilograms since he began working out at the gym three times a week."], "keys": [{"en": "since", "zh": "自從"}, {"en": "gym", "zh": "健身房"}, {"en": "kilogram", "zh": "公斤"}], "point": "「since + 過去式子句」表示從過去某時開始，主要子句用現在完成式「have/has + p.p.」。", "topic": "fitness", "level": "B1"}, {"id": "T065", "zh": "那位在奧運贏得金牌的選手，是我們學校的畢業生。", "en": "The athlete who won a gold medal at the Olympics is a graduate of our school.", "alt": ["The athlete who won an Olympic gold medal graduated from our school."], "keys": [{"en": "athlete", "zh": "運動員；選手"}, {"en": "gold medal", "zh": "金牌"}, {"en": "graduate", "zh": "畢業生；畢業"}], "point": "關係代名詞 who 引導形容詞子句修飾人（the athlete），主要動詞 is 須與先行詞一致。", "topic": "athletes", "level": "B2"}, {"id": "T066", "zh": "你白天運動得越多，晚上通常就睡得越好。", "en": "The more you exercise during the day, the better you usually sleep at night.", "alt": ["Generally, the more exercise you get during the day, the better you sleep at night."], "keys": [{"en": "exercise", "zh": "運動"}, {"en": "during the day", "zh": "在白天"}, {"en": "at night", "zh": "在晚上"}], "point": "「The + 比較級 + 主詞 + V, the + 比較級 + 主詞 + V」表示越…就越…，兩個子句都要用比較級。", "topic": "exercise and sleep", "level": "B2"}, {"id": "T067", "zh": "游泳是最適合在炎熱夏天做的運動之一。", "en": "Swimming is one of the most suitable sports for hot summer days.", "alt": ["Swimming is one of the best sports to do on hot summer days."], "keys": [{"en": "one of", "zh": "…之一"}, {"en": "suitable", "zh": "適合的"}], "point": "「one of the + 最高級 + 複數名詞」表示最…的…之一，名詞須用複數，動詞則與 one 一致用單數。", "topic": "swimming", "level": "B1"}, {"id": "T068", "zh": "我爸爸試過好幾次要戒菸，但從來都沒有成功過。", "en": "My father has tried to give up smoking several times, but he has never succeeded.", "alt": ["My dad has tried several times to quit smoking, but he has never been successful.", "My father has tried to quit smoking a number of times, but he has never succeeded."], "keys": [{"en": "try", "zh": "嘗試；試圖"}, {"en": "give up", "zh": "戒除；放棄"}, {"en": "succeed", "zh": "成功"}], "point": "「try to V」表示試圖、努力去做某事，「try V-ing」則表示試試看某方法；give up + V-ing 表示戒除某習慣；現在完成式 has tried / has never succeeded 表示到目前為止的經驗。", "topic": "quitting smoking", "level": "B1"}, {"id": "T069", "zh": "為了降低罹患糖尿病的風險，我們應該減少攝取甜食。", "en": "To lower the risk of getting diabetes, we should cut down on sweets.", "alt": ["We should eat fewer sweets in order to reduce the risk of developing diabetes."], "keys": [{"en": "cut down on", "zh": "減少（攝取）"}, {"en": "risk", "zh": "風險"}, {"en": "diabetes", "zh": "糖尿病"}], "point": "「cut down on + N」表示減少某物的量；表目的的「為了…」可用 to V 或 in order to V，放句首時後加逗號。", "topic": "diet and disease", "level": "B2"}, {"id": "T070", "zh": "很多學生週末都花好幾個小時打電動，很少出去運動。", "en": "Many students spend several hours playing video games on weekends and seldom go out to exercise.", "alt": ["On weekends, many students spend hours playing video games and rarely go outside to exercise."], "keys": [{"en": "spend", "zh": "花費（時間）"}, {"en": "video game", "zh": "電玩；電動"}, {"en": "seldom", "zh": "很少"}], "point": "「spend + 時間 + V-ing」表示花時間做某事；seldom / rarely 為頻率副詞，放在一般動詞之前。", "topic": "lack of exercise", "level": "B1"}, {"id": "T071", "zh": "打球前做伸展運動可以防止我們的肌肉受傷。", "en": "Stretching before playing ball can prevent our muscles from getting injured.", "alt": ["Doing stretching exercises before playing ball can keep our muscles from getting hurt.", "Stretching before you play ball helps prevent muscle injuries."], "keys": [{"en": "stretch", "zh": "伸展"}, {"en": "prevent", "zh": "防止；預防"}, {"en": "muscle", "zh": "肌肉"}], "point": "「prevent / keep + 受詞 + from + V-ing」表示防止…發生；動名詞 Stretching 當主詞。", "topic": "sports safety", "level": "B2"}, {"id": "T072", "zh": "我真希望自己能跑得跟哥哥一樣快。", "en": "I really wish I could run as fast as my older brother.", "alt": ["I really wish I could run as fast as my older brother can.", "If only I could run as fast as my older brother!"], "keys": [{"en": "wish", "zh": "但願；希望（不太可能實現的事）"}, {"en": "as fast as", "zh": "和…一樣快"}], "point": "「wish + S + 過去式（could + 原形V）」表示與現在事實相反、不太可能實現的願望；「as + 形容詞／副詞原級 + as」表示和…一樣…。", "topic": "running", "level": "B2"}, {"id": "T073", "zh": "對正在發育的青少年來說，吃一頓營養均衡的早餐非常重要。", "en": "It is very important for growing teenagers to eat a well-balanced breakfast.", "alt": ["Eating a nutritionally balanced breakfast is essential for teenagers who are still growing."], "keys": [{"en": "balanced", "zh": "均衡的"}, {"en": "teenager", "zh": "青少年"}], "point": "「It is + adj. + for + 人 + to V」以虛主詞 it 代替後面的不定詞片語；growing 是現在分詞當形容詞，表「正在成長的」。", "topic": "breakfast", "level": "B2"}, {"id": "T074", "zh": "你感冒了，最好多喝水、早點上床休息。", "en": "You have a cold, so you had better drink more water and go to bed early.", "alt": ["Since you've caught a cold, you had better drink plenty of water and go to bed early."], "keys": [{"en": "have a cold", "zh": "感冒"}, {"en": "had better", "zh": "最好"}, {"en": "go to bed", "zh": "上床睡覺"}], "point": "「had better + 原形V」表示最好…，否定為 had better not + V；「感冒」可說 have a cold 或 catch a cold。", "topic": "colds", "level": "B1"}, {"id": "T075", "zh": "不管工作多忙，我姊姊每天都會抽出半小時做瑜伽。", "en": "No matter how busy she is at work, my older sister makes time to do yoga for half an hour every day.", "alt": ["However busy she is at work, my older sister still makes time for half an hour of yoga every day.", "No matter how busy my older sister is at work, she makes time to do yoga for half an hour every day."], "keys": [{"en": "no matter how", "zh": "不管多麼"}, {"en": "make time", "zh": "抽出時間"}, {"en": "yoga", "zh": "瑜伽"}], "point": "「no matter how + adj. + 主詞 + V」表示不管多麼…，等於「however + adj.」；make time to V 表示抽空做某事。", "topic": "yoga", "level": "B2"}, {"id": "T076", "zh": "因為風浪太大，明天往返綠島的船班全部都取消了。", "en": "Because of the strong winds and high waves, all of tomorrow's ferries to and from Green Island have been canceled.", "alt": ["All ferries to and from Green Island tomorrow have been canceled due to the rough seas."], "keys": [{"en": "cancel", "zh": "取消"}, {"en": "ferry", "zh": "渡輪；船班"}, {"en": "because of", "zh": "因為；由於"}], "point": "主詞是事物（船班）時用被動語態；「have/has been + p.p.」表示已被取消的結果；because of 後面接名詞。", "topic": "ferry travel", "level": "B1"}, {"id": "T077", "zh": "從台北搭高鐵到高雄，大約只需要一個半小時。", "en": "It only takes about an hour and a half to get from Taipei to Kaohsiung by high-speed rail.", "alt": ["The trip from Taipei to Kaohsiung by high-speed rail takes only about an hour and a half."], "keys": [{"en": "take", "zh": "花費（時間）"}, {"en": "high-speed rail", "zh": "高鐵"}], "point": "「It takes + 時間 + to V」表示做某事需要多少時間；「by + 交通工具」中間不加冠詞。", "topic": "high-speed rail", "level": "B1"}, {"id": "T078", "zh": "今天早上的霧太濃了，松山機場有許多班機因此延誤。", "en": "The fog was so thick this morning that many flights at Songshan Airport were delayed.", "alt": ["There was such thick fog this morning that many flights at Songshan Airport were delayed."], "keys": [{"en": "thick", "zh": "（霧）濃的"}, {"en": "delay", "zh": "延誤"}, {"en": "flight", "zh": "班機"}], "point": "「so + adj. + that…」表示如此…以致於；也可用「such + adj. + 名詞 + that…」，fog 為不可數名詞，所以 such 後不加 a；班機「被」延誤用 be delayed。", "topic": "weather and flights", "level": "B1"}, {"id": "T079", "zh": "九份是個非常迷人的山城，每年都吸引大批外國遊客前來。", "en": "Jiufen is such a charming mountain town that it attracts large numbers of foreign tourists every year.", "alt": ["Jiufen is so charming a mountain town that it attracts a great number of foreign visitors every year."], "keys": [{"en": "charming", "zh": "迷人的"}, {"en": "attract", "zh": "吸引"}, {"en": "tourist", "zh": "遊客；觀光客"}], "point": "「such + a/an + adj. + 單數名詞 + that…」表示如此…以致於；也可寫成「so + adj. + a/an + 名詞 + that…」。", "topic": "places in Taiwan", "level": "B2"}, {"id": "T080", "zh": "台南不但有許多歷史悠久的古蹟，還有各式各樣的美味小吃。", "en": "Tainan not only has many historic sites but also offers a wide variety of delicious snacks.", "alt": ["Tainan has not only many historic sites but also a wide variety of delicious snacks."], "keys": [{"en": "historic", "zh": "有歷史意義的；歷史悠久的"}, {"en": "a wide variety of", "zh": "各式各樣的"}, {"en": "snack", "zh": "小吃；點心"}], "point": "「not only A but also B」連接的 A、B 須為對等的詞類（同為動詞片語或同為名詞片語）。", "topic": "places in Taiwan", "level": "B1"}, {"id": "T081", "zh": "我以前都搭公車上學，但新的捷運線通車後，我就改搭捷運了。", "en": "I used to take the bus to school, but after the new MRT line opened, I started taking the MRT instead.", "alt": ["I used to go to school by bus, but since the new MRT line opened, I have been taking the MRT instead."], "keys": [{"en": "used to", "zh": "以前常常（現在不再）"}, {"en": "instead", "zh": "改為；取而代之"}], "point": "「used to + 原形V」表示過去的習慣，暗示現在已不再如此；instead 放句尾表示「改為…」。", "topic": "commuting", "level": "B1"}, {"id": "T082", "zh": "剛搬到基隆的時候，我很不習慣每次出門都得帶雨傘。", "en": "When I first moved to Keelung, I was not used to having to carry an umbrella every time I went out.", "alt": ["Right after I moved to Keelung, I wasn't used to having to take an umbrella whenever I went out."], "keys": [{"en": "be used to", "zh": "習慣於"}, {"en": "umbrella", "zh": "雨傘"}], "point": "「be used to + V-ing/N」表示習慣於（to 是介系詞）；勿與「used to + 原形V」（以前常常）混淆。", "topic": "rainy weather", "level": "B1"}, {"id": "T083", "zh": "位於南投的日月潭以美麗的湖光山色而聞名。", "en": "Sun Moon Lake, which is located in Nantou, is well known for its beautiful lake and mountain views.", "alt": ["Sun Moon Lake is located in Nantou and is famous for its beautiful views of the lake and the mountains."], "keys": [{"en": "be located in", "zh": "位於"}, {"en": "be well known for", "zh": "以…聞名"}], "point": "非限定關係子句「, which…,」補充說明專有名詞，不可用 that；「be (well) known for」或「be famous for」表示以…聞名。", "topic": "places in Taiwan", "level": "B2"}, {"id": "T084", "zh": "我們昨晚在墾丁住的那家民宿是由一對年輕夫婦經營的。", "en": "The bed and breakfast where we stayed in Kenting last night is run by a young couple.", "alt": ["The B&B that we stayed at in Kenting last night is run by a young couple."], "keys": [{"en": "run", "zh": "經營"}, {"en": "couple", "zh": "夫婦；一對"}, {"en": "bed and breakfast", "zh": "民宿"}], "point": "關係副詞 where（= at which）引導形容詞子句修飾地點；run 作「經營」解，被動為 be run by。", "topic": "accommodation", "level": "B2"}, {"id": "T085", "zh": "搭火車去花蓮雖然比開車貴，但是安全又舒適多了。", "en": "Although taking the train to Hualien is more expensive than driving, it is much safer and more comfortable.", "alt": ["Taking the train to Hualien costs more than driving, but it is much safer and more comfortable."], "keys": [{"en": "expensive", "zh": "昂貴的"}, {"en": "safe", "zh": "安全的"}, {"en": "comfortable", "zh": "舒適的"}], "point": "比較級：單音節形容詞加 -er（safer），多音節用 more（more comfortable）；much 修飾比較級表示「…得多」；英文的 although 與 but 不可並用。", "topic": "train travel", "level": "B1"}, {"id": "T086", "zh": "外面雨下得太大了，我們沒辦法騎腳踏車去河濱公園。", "en": "It is raining too hard outside for us to ride our bikes to the riverside park.", "alt": ["It is raining so hard outside that we can't ride our bikes to the riverside park."], "keys": [{"en": "hard", "zh": "猛烈地；（雨下得）大"}, {"en": "ride", "zh": "騎（腳踏車）"}, {"en": "riverside", "zh": "河邊的；河濱的"}], "point": "「too + adj./adv. + for + 人 + to V」表示太…以致於（某人）不能…，可改寫為「so…that + S + can't + V」。", "topic": "rainy weather", "level": "B1"}, {"id": "T087", "zh": "如果颱風明天侵襲台灣，學校很可能會停課。", "en": "If the typhoon hits Taiwan tomorrow, schools will probably be closed.", "alt": ["Classes will probably be canceled if the typhoon strikes Taiwan tomorrow."], "keys": [{"en": "typhoon", "zh": "颱風"}, {"en": "hit", "zh": "侵襲；襲擊"}, {"en": "probably", "zh": "很可能"}], "point": "表示未來可能發生的條件句：「If + 現在簡單式, S + will + V」，if 子句不用 will；學校「被」關閉用被動語態。", "topic": "typhoons", "level": "B1"}, {"id": "T088", "zh": "要是我有足夠的時間和金錢，我就會騎腳踏車環島一圈。", "en": "If I had enough time and money, I would travel around Taiwan by bike.", "alt": ["If I had enough time and money, I would ride my bike all the way around the island."], "keys": [{"en": "enough", "zh": "足夠的"}, {"en": "travel around", "zh": "環遊；到處旅行"}], "point": "與現在事實相反的假設：「If + S + 過去式, S + would + 原形V」（暗示現在其實沒有足夠的時間和金錢）。", "topic": "cycling trips", "level": "B2"}, {"id": "T089", "zh": "如果我們早一點出門的話，就不會錯過末班火車了。", "en": "If we had left home earlier, we wouldn't have missed the last train.", "alt": ["Had we left home earlier, we would not have missed the last train."], "keys": [{"en": "miss", "zh": "錯過"}, {"en": "leave", "zh": "離開；出發"}], "point": "與過去事實相反的假設：「If + S + had + p.p., S + would have + p.p.」；省略 if 時可倒裝為「Had + S + p.p.」。", "topic": "missing a train", "level": "B2"}, {"id": "T090", "zh": "上山健行之前，你一定要先查看天氣預報。", "en": "You must check the weather forecast before you go hiking in the mountains.", "alt": ["Before going hiking in the mountains, you must check the weather forecast first."], "keys": [{"en": "weather forecast", "zh": "天氣預報"}, {"en": "go hiking", "zh": "去健行"}, {"en": "check", "zh": "查看；檢查"}], "point": "「must + 原形V」表示必須；「go + V-ing」表示去從事某活動（go hiking/camping/swimming）；before 後可接子句或 V-ing。", "topic": "hiking safety", "level": "B1"}, {"id": "T091", "zh": "我們的班機早上七點起飛，所以我們必須在五點前抵達機場。", "en": "Our flight takes off at seven in the morning, so we have to arrive at the airport before five.", "alt": ["Our flight takes off at 7 a.m., so we need to arrive at the airport before 5 a.m.", "Since our flight leaves at seven in the morning, we have to get to the airport before five."], "keys": [{"en": "take off", "zh": "（飛機）起飛"}, {"en": "arrive at", "zh": "抵達（某地點）"}], "point": "「take off」表示飛機起飛；時刻表上排定的未來行程可用現在簡單式表示；「arrive at + 較小地點」、「arrive in + 城市/國家」。", "topic": "air travel", "level": "B1"}, {"id": "T092", "zh": "我們一抵達飯店就先辦理入住，然後到附近的夜市逛逛。", "en": "As soon as we arrived at the hotel, we checked in and then went to look around the nearby night market.", "alt": ["We checked in as soon as we got to the hotel, and then we went to explore the night market nearby."], "keys": [{"en": "as soon as", "zh": "一…就…"}, {"en": "check in", "zh": "辦理入住"}, {"en": "night market", "zh": "夜市"}], "point": "「as soon as + 子句」表示一…就…；「check in」為辦理入住（退房為 check out）；look around 表示四處看看、逛逛。", "topic": "hotel stays", "level": "B1"}, {"id": "T093", "zh": "在台灣，騎機車時戴安全帽是法律規定的。", "en": "In Taiwan, wearing a helmet while riding a scooter is required by law.", "alt": ["In Taiwan, the law requires people to wear a helmet when they ride a scooter."], "keys": [{"en": "helmet", "zh": "安全帽"}, {"en": "scooter", "zh": "機車"}, {"en": "require", "zh": "要求；規定"}], "point": "動名詞片語（wearing a helmet…）當主詞時視為單數，動詞用 is；「be required by law」表示依法規定；「require + 人 + to V」。", "topic": "road safety", "level": "B2"}, {"id": "T094", "zh": "你曾經去過阿里山看日出嗎？我已經去過兩次了。", "en": "Have you ever been to Alishan to watch the sunrise? I have already been there twice.", "alt": ["Have you ever visited Alishan to see the sunrise? I've already been there twice."], "keys": [{"en": "have been to", "zh": "曾經去過"}, {"en": "sunrise", "zh": "日出"}], "point": "現在完成式表示經驗；「have been to + 地點」表示曾經去過（已回來），「have gone to」則表示已前往（人不在這裡）。", "topic": "places in Taiwan", "level": "B1"}, {"id": "T095", "zh": "等我們抵達合歡山山頂的時候，太陽早就已經下山了。", "en": "By the time we reached the top of Hehuan Mountain, the sun had already set.", "alt": ["By the time we got to the top of Hehuan Mountain, the sun had already gone down."], "keys": [{"en": "by the time", "zh": "到…的時候"}, {"en": "reach", "zh": "抵達"}, {"en": "set", "zh": "（太陽）落下"}], "point": "過去完成式「had + p.p.」表示在過去某時間點之前已完成的動作；「by the time + 過去式子句」常搭配過去完成式；set 三態同形。", "topic": "mountain trips", "level": "B2"}, {"id": "T096", "zh": "台北101曾經是世界上最高的大樓，現在仍然是台灣最有名的地標之一。", "en": "Taipei 101 was once the tallest building in the world, and it is still one of Taiwan's most famous landmarks.", "alt": ["Taipei 101 used to be the world's tallest building, and it remains one of the best-known landmarks in Taiwan."], "keys": [{"en": "once", "zh": "曾經"}, {"en": "landmark", "zh": "地標"}], "point": "最高級「the + adj.-est / the most + adj.」；「one of the（或所有格，如 Taiwan's）+ 最高級 + 複數名詞」表示最…之一，名詞要用複數。", "topic": "places in Taiwan", "level": "B1"}, {"id": "T097", "zh": "為了避開連假的人潮，我們決定提前一個月訂飯店。", "en": "To avoid the holiday crowds, we decided to book a hotel a month in advance.", "alt": ["In order to avoid the crowds during the long weekend, we decided to reserve a hotel room one month in advance."], "keys": [{"en": "avoid", "zh": "避開；避免"}, {"en": "crowd", "zh": "人群；人潮"}, {"en": "in advance", "zh": "事先；提前"}], "point": "「To V / In order to V」表示目的；「decide to + V」決定做某事；in advance 表示事先、提前。", "topic": "holiday travel", "level": "B2"}, {"id": "T098", "zh": "受到寒流影響，明天北部的氣溫預計會降到攝氏十度以下。", "en": "Due to a cold wave, temperatures in northern Taiwan are expected to drop below ten degrees Celsius tomorrow.", "alt": ["Because of the cold wave, the temperature in northern Taiwan is expected to fall below 10°C tomorrow."], "keys": [{"en": "be expected to", "zh": "預計會…"}, {"en": "temperature", "zh": "氣溫"}, {"en": "drop", "zh": "下降"}], "point": "「be expected to + V」表示預計會…；「due to + 名詞」表示由於；氣溫「降到…以下」用 drop/fall below。", "topic": "cold weather", "level": "B2"}, {"id": "T099", "zh": "雨下得很大又叫不到計程車，所以爸爸開車到車站來接我。", "en": "It was raining heavily and I couldn't get a taxi, so my dad drove to the station to pick me up.", "alt": ["Since it was pouring and I couldn't find a taxi, my father drove to the station to pick me up."], "keys": [{"en": "pick up", "zh": "（開車）接（某人）"}, {"en": "taxi", "zh": "計程車"}], "point": "「pick + 人 + up」表示去接某人，受詞為代名詞時必須放在 pick 與 up 之間；過去進行式描述當時的天氣狀況。", "topic": "getting a ride", "level": "B1"}, {"id": "T100", "zh": "太魯閣國家公園的風景非常壯觀，絕對值得一遊。", "en": "The scenery in Taroko National Park is truly spectacular, and the park is definitely worth visiting.", "alt": ["Taroko National Park has truly spectacular scenery and is definitely worth a visit."], "keys": [{"en": "scenery", "zh": "風景"}, {"en": "spectacular", "zh": "壯觀的"}, {"en": "worth", "zh": "值得"}], "point": "「be worth + V-ing / a + N」表示值得…，V-ing 用主動形式表示被動意義；scenery 為不可數名詞，不加 s。", "topic": "places in Taiwan", "level": "B2"}, {"id": "T101", "zh": "我爸媽不准我晚上十點以後使用手機。", "en": "My parents don't allow me to use my cell phone after ten o'clock at night.", "alt": ["My parents won't let me use my phone after 10 p.m.", "I'm not allowed to use my cell phone after ten at night."], "keys": [{"en": "allow", "zh": "允許；准許"}, {"en": "at night", "zh": "在晚上"}], "point": "「allow + 受詞 + to V」表示允許某人做某事；也可用「let + 受詞 + 原形V」（let 後不加 to），或被動式「be allowed to V」。", "topic": "phone rules", "level": "B1"}, {"id": "T102", "zh": "這支手機太舊了，無法下載最新的應用程式。", "en": "This cell phone is too old to download the latest apps.", "alt": ["This phone is so old that it can't download the latest apps.", "This cell phone is too outdated to download the newest apps."], "keys": [{"en": "download", "zh": "下載"}, {"en": "latest", "zh": "最新的"}, {"en": "app", "zh": "應用程式"}], "point": "「too + adj. + to V」表示太…而不能…，本身已含否定意味，不可再加 not。", "topic": "smartphones", "level": "B1"}, {"id": "T103", "zh": "我花了三個小時才把所有的照片上傳到網路上。", "en": "It took me three hours to upload all the photos to the Internet.", "alt": ["I spent three hours uploading all the photos to the Internet.", "Uploading all the pictures to the Internet took me three hours."], "keys": [{"en": "upload", "zh": "上傳"}, {"en": "Internet", "zh": "網際網路"}], "point": "「It takes/took + 人 + 時間 + to V」表示某人花多少時間做某事；也可用「人 + spend + 時間 + V-ing」。", "topic": "uploading photos", "level": "B1"}, {"id": "T104", "zh": "這款新的智慧型手機將於下個月在台灣上市。", "en": "This new smartphone will be released in Taiwan next month.", "alt": ["This new smartphone is going to be released in Taiwan next month.", "This new smartphone will go on sale in Taiwan next month."], "keys": [{"en": "smartphone", "zh": "智慧型手機"}, {"en": "release", "zh": "發行；推出"}], "point": "手機是「被推出」的，故用被動語態；未來式被動為「will be + p.p.」或「be going to be + p.p.」；「上市」也可用主動的 go on sale。", "topic": "new gadgets", "level": "B1"}, {"id": "T105", "zh": "我小時候常寫信給朋友，但現在我們都用手機傳訊息。", "en": "When I was a child, I used to write letters to my friends, but now we all send text messages on our phones.", "alt": ["I used to write letters to my friends when I was young, but these days we all send text messages with our phones."], "keys": [{"en": "used to", "zh": "過去常常"}, {"en": "text message", "zh": "簡訊；文字訊息"}], "point": "「used to + 原形V」表示過去的習慣（現在已不再如此），勿與「be used to + V-ing」（習慣於）混淆。", "topic": "communication", "level": "B1"}, {"id": "T106", "zh": "社群媒體不但能讓我們和朋友保持聯絡，還能讓我們掌握最新消息。", "en": "Social media not only helps us keep in touch with our friends but also keeps us updated on the latest news.", "alt": ["Social media allows us not only to keep in touch with friends but also to stay updated on the latest news."], "keys": [{"en": "social media", "zh": "社群媒體"}, {"en": "keep in touch with", "zh": "與…保持聯絡"}], "point": "「not only A but also B」中 A、B 須為對等結構（此處皆為動詞片語）；「help + 人 + (to) V」。", "topic": "social media", "level": "B2"}, {"id": "T107", "zh": "那支影片太有創意了，一天之內就有超過一百萬人看過。", "en": "That video was so creative that more than one million people watched it within a day.", "alt": ["It was such a creative video that more than a million people watched it within one day.", "The video was so creative that it was watched by more than one million people within a day."], "keys": [{"en": "creative", "zh": "有創意的"}, {"en": "more than", "zh": "超過"}, {"en": "within", "zh": "在…之內"}], "point": "「so + adj. + that…」與「such + a/an + adj. + N + that…」皆表示「如此…以致於」；so 後接形容詞，such 後接名詞片語。", "topic": "viral videos", "level": "B1"}, {"id": "T108", "zh": "很多人沉迷於社群媒體，因為他們很在意自己的貼文得到多少個讚。", "en": "Many people are addicted to social media because they really care about how many likes their posts get.", "alt": ["Lots of people are addicted to social media since they care a lot about how many likes their posts receive."], "keys": [{"en": "be addicted to", "zh": "沉迷於；對…上癮"}, {"en": "care about", "zh": "在意；關心"}], "point": "「be addicted to + N/V-ing」的 to 為介系詞；間接問句 how many likes their posts get 用直述句語序。", "topic": "social media", "level": "B2"}, {"id": "T109", "zh": "開發這個熱門應用程式的那位工程師只有二十歲。", "en": "The engineer who developed this popular app is only twenty years old.", "alt": ["The engineer that developed this popular app is just twenty years old.", "The engineer behind this popular app is only twenty."], "keys": [{"en": "develop", "zh": "開發"}, {"en": "engineer", "zh": "工程師"}, {"en": "popular", "zh": "熱門的；受歡迎的"}], "point": "關係代名詞 who/that 引導形容詞子句修飾先行詞「人」；主要動詞 is 須與主詞 engineer 一致。", "topic": "app developers", "level": "B1"}, {"id": "T110", "zh": "如果你在網路上分享太多個人資料，你可能會成為詐騙的受害者。", "en": "If you share too much personal information online, you may become a victim of fraud.", "alt": ["Sharing too much personal information on the Internet may make you a victim of fraud.", "If you share too much of your personal information online, you might fall victim to fraud."], "keys": [{"en": "personal information", "zh": "個人資料"}, {"en": "victim", "zh": "受害者"}, {"en": "fraud", "zh": "詐騙"}], "point": "「If + 現在式, 主詞 + may/will + 原形V」表示對未來的真實條件；information 不可數，用 much 修飾。", "topic": "online safety", "level": "B2"}, {"id": "T111", "zh": "我們過馬路的時候不應該一直盯著手機看。", "en": "We shouldn't keep staring at our phones while we are crossing the street.", "alt": ["We should not keep staring at our cell phones when crossing the road."], "keys": [{"en": "stare at", "zh": "盯著看"}, {"en": "cross", "zh": "穿越；過（馬路）"}], "point": "「keep + V-ing」表示一直做某事；「should not + 原形V」表示不應該；while 引導時間副詞子句。", "topic": "phone safety", "level": "B1"}, {"id": "T112", "zh": "對年輕人來說，網路購物比去實體商店方便多了。", "en": "For young people, shopping online is much more convenient than going to physical stores.", "alt": ["Young people find it much more convenient to shop online than to go to physical stores.", "For young people, online shopping is far more convenient than visiting physical stores."], "keys": [{"en": "convenient", "zh": "方便的"}, {"en": "physical store", "zh": "實體商店"}], "point": "「much/far + 比較級 + than」強調「…得多」；比較的兩者須對等（shopping online 與 going to… 皆為動名詞）。", "topic": "online shopping", "level": "B1"}, {"id": "T113", "zh": "長時間使用電腦可能會對你的視力造成傷害。", "en": "Using a computer for long periods of time may do harm to your eyesight.", "alt": ["Using computers for a long time can do harm to your eyesight.", "Spending long hours on the computer may harm your eyesight."], "keys": [{"en": "do harm to", "zh": "對…造成傷害"}, {"en": "eyesight", "zh": "視力"}], "point": "動名詞片語當主詞時，動詞用單數；「do harm to + N」= harm + N，表示對…有害。", "topic": "computers and health", "level": "B2"}, {"id": "T114", "zh": "自從我買了這支新手機以後，我已經拍了好幾百張照片。", "en": "Since I bought this new phone, I have taken hundreds of photos.", "alt": ["I have taken hundreds of pictures since I bought this new cell phone."], "keys": [{"en": "since", "zh": "自從"}, {"en": "hundreds of", "zh": "數以百計的；好幾百"}], "point": "「since + 過去式子句」表示「自從…」，主要子句用現在完成式 have/has + p.p.。", "topic": "phone cameras", "level": "B1"}, {"id": "T115", "zh": "這個網站已經被駭客攻擊過好幾次，所以很多使用者不再信任它。", "en": "This website has been attacked by hackers several times, so many users no longer trust it.", "alt": ["Hackers have attacked this website several times, so many users don't trust it anymore."], "keys": [{"en": "hacker", "zh": "駭客"}, {"en": "no longer", "zh": "不再"}, {"en": "trust", "zh": "信任"}], "point": "現在完成式被動語態「has been + p.p.」；「no longer」= not … anymore，表示不再。", "topic": "cybersecurity", "level": "B2"}, {"id": "T116", "zh": "出門前別忘了把手機充飽電，以免在路上沒電。", "en": "Don't forget to fully charge your phone before going out so that it won't run out of battery on the way.", "alt": ["Remember to charge your phone fully before you go out, or it may run out of battery on the way.", "Don't forget to charge your phone fully before you leave home in case the battery dies on the way."], "keys": [{"en": "forget", "zh": "忘記"}, {"en": "charge", "zh": "充電"}, {"en": "run out of", "zh": "用完；耗盡"}], "point": "「forget to V」表示忘記去做（尚未做），「forget V-ing」則是忘記做過；so that 引導表目的的子句，「以免」可用 so that … won't 或 in case 表達。", "topic": "phone batteries", "level": "B1"}, {"id": "T117", "zh": "我不小心把手機摔壞了，所以得把它送去修理。", "en": "I dropped my phone by accident and broke it, so I need to get it repaired.", "alt": ["My phone broke when I dropped it by accident, so I have to get it repaired.", "I accidentally dropped and broke my phone, so I have to have it fixed."], "keys": [{"en": "by accident", "zh": "不小心地；意外地"}, {"en": "repair", "zh": "修理"}], "point": "使役動詞「get/have + 受詞 + p.p.」表示請別人做某事（手機是被修理的）；by accident = accidentally。", "topic": "phone repairs", "level": "B1"}, {"id": "T118", "zh": "現在很多人依賴網路地圖找路，而不是向路人問路。", "en": "Many people now rely on online maps to find their way instead of asking passersby for directions.", "alt": ["These days, a lot of people rely on online maps to find their way instead of asking people on the street for directions.", "Nowadays, lots of people depend on online maps to find their way rather than asking passersby for directions."], "keys": [{"en": "rely on", "zh": "依賴"}, {"en": "instead of", "zh": "而不是"}, {"en": "direction", "zh": "方向；（複數）指路說明"}], "point": "「instead of + V-ing」表示「而不是…」，of 為介系詞須接動名詞；rely on = depend on。", "topic": "online maps", "level": "B2"}, {"id": "T119", "zh": "你花在社群媒體上的時間越多，能用來讀書的時間就越少。", "en": "The more time you spend on social media, the less time you have for studying.", "alt": ["If you spend more time on social media, you will have less time to study."], "keys": [{"en": "spend", "zh": "花費（時間）"}, {"en": "less", "zh": "較少的"}], "point": "「The + 比較級 + S + V…, the + 比較級 + S + V」表示「越…就越…」；less 修飾不可數名詞 time。", "topic": "social media", "level": "B2"}, {"id": "T120", "zh": "除非你定期更改密碼，否則你的帳號很容易被盜用。", "en": "Unless you change your password regularly, your account can easily be hacked.", "alt": ["Your account can easily be hacked if you don't change your password regularly.", "If you don't change your password on a regular basis, someone could easily hack into your account."], "keys": [{"en": "unless", "zh": "除非"}, {"en": "password", "zh": "密碼"}, {"en": "account", "zh": "帳號"}], "point": "unless = if … not，引導條件子句，子句中不可再用否定；條件子句以現在式代替未來式。", "topic": "passwords", "level": "B2"}, {"id": "T121", "zh": "現在智慧型手機常被用來在便利商店付款。", "en": "Smartphones are now often used to pay for things at convenience stores.", "alt": ["These days, people often use their phones to pay for things at convenience stores.", "Smartphones are now commonly used to make payments at convenience stores."], "keys": [{"en": "pay for", "zh": "支付；付…的錢"}, {"en": "convenience store", "zh": "便利商店"}], "point": "「be used to + 原形V」表示「被用來做…」（被動語態），與「be used to + V-ing」（習慣於）不同。", "topic": "mobile payment", "level": "B1"}, {"id": "T122", "zh": "我的手機容量不夠大，無法儲存這麼多影片。", "en": "My phone doesn't have enough storage space to save so many videos.", "alt": ["My phone's storage isn't large enough to hold so many videos.", "There isn't enough storage space on my phone to save so many videos."], "keys": [{"en": "enough", "zh": "足夠的"}, {"en": "storage", "zh": "儲存（空間）"}], "point": "「enough + N + to V」或「adj. + enough + to V」表示足夠…可以做…；注意 enough 與形容詞的位置。", "topic": "phone storage", "level": "B1"}, {"id": "T123", "zh": "專家警告青少年不要在網路上散播關於同學的謠言。", "en": "Experts warn teenagers not to spread rumors about their classmates online.", "alt": ["Experts warn young people not to spread rumors about classmates on the Internet."], "keys": [{"en": "warn", "zh": "警告"}, {"en": "spread", "zh": "散播"}, {"en": "rumor", "zh": "謠言"}], "point": "「warn + 人 + not to V」表示警告某人不要做某事，否定的不定詞 not 須放在 to 之前。", "topic": "cyberbullying", "level": "B2"}, {"id": "T124", "zh": "我正在上網看影片的時候，網路連線突然中斷了。", "en": "While I was watching a video online, my Internet connection suddenly went down.", "alt": ["I was watching a video on the Internet when I suddenly lost my connection.", "While I was watching a video online, the Internet connection was suddenly cut off."], "keys": [{"en": "connection", "zh": "連線"}, {"en": "suddenly", "zh": "突然地"}, {"en": "go down", "zh": "（網路、系統）中斷；停擺"}], "point": "過去進行式「was/were + V-ing」表示過去某時正在進行的動作，常與表示突發事件的過去簡單式（如 went down）連用；while 後常接進行式。", "topic": "internet connection", "level": "B1"}, {"id": "T125", "zh": "如果我沒有手機，我就不知道該怎麼和家人聯絡了。", "en": "If I didn't have a cell phone, I wouldn't know how to contact my family.", "alt": ["Without a cell phone, I wouldn't know how to get in touch with my family.", "If I had no cell phone, I wouldn't know how to contact my family."], "keys": [{"en": "contact", "zh": "聯絡"}, {"en": "how to", "zh": "如何…"}], "point": "與現在事實相反的假設語氣：「If + 過去式, S + would + 原形V」；「疑問詞 + to V」當名詞片語作受詞。", "topic": "smartphones", "level": "B2"}, {"id": "T126", "zh": "去年暑假，我在一家便利商店打工，賺了一些零用錢。", "en": "Last summer vacation, I worked part-time at a convenience store and earned some pocket money.", "alt": ["I had a part-time job at a convenience store last summer vacation and made some pocket money."], "keys": [{"en": "work part-time", "zh": "打工"}, {"en": "convenience store", "zh": "便利商店"}, {"en": "pocket money", "zh": "零用錢"}], "point": "「work part-time」＝打工，也可說 have a part-time job；去年發生的事用過去式。", "topic": "part-time work", "level": "B1"}, {"id": "T127", "zh": "面試時，他被問到為什麼想要這份工作，緊張得說不出話來。", "en": "During the interview, he was asked why he wanted the job, and he was too nervous to say a word.", "alt": ["In the interview, he was asked why he wanted this job, and he was so nervous that he couldn't say a word."], "keys": [{"en": "interview", "zh": "面試"}, {"en": "nervous", "zh": "緊張的"}], "point": "「被問」用被動語態 be asked；間接問句 why he wanted 用直述句語序；「too + adj. + to V」表示太…而不能…。", "topic": "job interviews", "level": "B2"}, {"id": "T128", "zh": "我的夢想是成為一名護理師，這樣我就能照顧生病的人。", "en": "My dream is to become a nurse so that I can take care of sick people.", "alt": ["My dream is to be a nurse so that I can take care of people who are sick."], "keys": [{"en": "become", "zh": "成為"}, {"en": "take care of", "zh": "照顧"}], "point": "不定詞 to V 當主詞補語（My dream is to V）；「so that + S + can + V」表目的，意為「以便、這樣才能」。", "topic": "career plans", "level": "B1"}, {"id": "T129", "zh": "我每天騎機車上班大約要花三十分鐘。", "en": "It takes me about thirty minutes to ride my scooter to work every day.", "alt": ["I spend about thirty minutes riding my scooter to work every day."], "keys": [{"en": "take", "zh": "花費（時間）"}, {"en": "scooter", "zh": "機車"}], "point": "「It takes + 人 + 時間 + to V」表示某人花多少時間做某事；也可用「人 + spend + 時間 + V-ing」。", "topic": "commuting to work", "level": "B1"}, {"id": "T130", "zh": "我們公司需要一位能說流利英文又會使用電腦的助理。", "en": "Our company needs an assistant who speaks fluent English and knows how to use computers.", "alt": ["Our company needs an assistant who can speak English fluently and use computers."], "keys": [{"en": "assistant", "zh": "助理"}, {"en": "fluent", "zh": "流利的"}], "point": "關係代名詞 who 引導形容詞子句修飾「人」，子句動詞須與先行詞 an assistant 一致（speaks、knows）；know how to V 表「會做某事」。", "topic": "job requirements", "level": "B2"}, {"id": "T131", "zh": "我哥哥以前在餐廳當服務生，現在是一名廚師。", "en": "My older brother used to be a waiter at a restaurant, but now he is a cook.", "alt": ["My elder brother used to work as a waiter in a restaurant, and now he is a chef."], "keys": [{"en": "used to", "zh": "以前（常）"}, {"en": "waiter", "zh": "服務生"}], "point": "「used to + 原形V」表示過去的狀態或習慣，現在已不再如此；work as + 職業 表「擔任…」。", "topic": "jobs", "level": "B1"}, {"id": "T132", "zh": "剛開始工作時我常常遲到，但現在我已經習慣早起了。", "en": "I was often late when I first started working, but now I am used to getting up early.", "alt": ["When I first began working, I was often late, but I am used to getting up early now."], "keys": [{"en": "be used to", "zh": "習慣於"}, {"en": "get up", "zh": "起床"}], "point": "「be used to + V-ing」習慣於…，此處 to 是介系詞，後接動名詞；勿與 used to + 原形V 混淆。", "topic": "workplace habits", "level": "B1"}, {"id": "T133", "zh": "參加面試時，你應該穿著整齊並且準時到達。", "en": "When you go to a job interview, you should dress neatly and arrive on time.", "alt": ["You should dress neatly and arrive on time when you attend a job interview."], "keys": [{"en": "dress", "zh": "穿著"}, {"en": "neatly", "zh": "整齊地"}, {"en": "on time", "zh": "準時"}], "point": "助動詞 should 表建議；副詞 neatly 修飾動詞 dress；on time 準時（in time 及時，意思不同）。", "topic": "job interviews", "level": "B1"}, {"id": "T134", "zh": "這份工作不但薪水高，而且讓我學到很多新技能。", "en": "This job not only offers a high salary but also allows me to learn many new skills.", "alt": ["Not only does this job pay well, but it also lets me learn a lot of new skills."], "keys": [{"en": "salary", "zh": "薪水"}, {"en": "skill", "zh": "技能"}], "point": "「not only A but also B」不但…而且…，A 與 B 須對等；Not only 放句首時要倒裝（Not only does + S + V）；allow + O + to V，let + O + 原形V。", "topic": "jobs", "level": "B2"}, {"id": "T135", "zh": "對我來說，找到一份有興趣的工作比賺很多錢更重要。", "en": "For me, finding a job that I am interested in is more important than making a lot of money.", "alt": ["To me, finding a job I am interested in matters more than earning a lot of money."], "keys": [{"en": "be interested in", "zh": "對…有興趣"}, {"en": "make a lot of money", "zh": "賺很多錢"}], "point": "動名詞 V-ing 當主詞時視為單數，動詞用 is；比較級「more + adj. + than」，比較的兩者都用 V-ing 保持對等。", "topic": "career plans", "level": "B1"}, {"id": "T136", "zh": "如果我是老闆，我會讓員工每週在家工作一天。", "en": "If I were the boss, I would let my employees work from home one day a week.", "alt": ["If I were the boss, I would allow my employees to work from home one day every week."], "keys": [{"en": "boss", "zh": "老闆"}, {"en": "employee", "zh": "員工"}, {"en": "work from home", "zh": "在家工作"}], "point": "與現在事實相反的假設：「If + S + were／過去式, S + would + 原形V」，be 動詞一律用 were；let + O + 原形V。", "topic": "workplace", "level": "B2"}, {"id": "T137", "zh": "她上個月申請了一份銀行的工作，正在等待結果。", "en": "She applied for a job at a bank last month and is waiting for the result.", "alt": ["Last month she applied for a position at a bank, and now she is waiting for the result."], "keys": [{"en": "apply for", "zh": "申請"}, {"en": "wait for", "zh": "等待"}], "point": "「apply for + 工作／職位」表申請；上個月的動作用過去式，「正在等待」用現在進行式。", "topic": "job hunting", "level": "B1"}, {"id": "T138", "zh": "我在這家餐廳工作非常忙，忙到連喝口水的時間都沒有。", "en": "I am so busy working at this restaurant that I don't even have time to drink water.", "alt": ["Working at this restaurant keeps me so busy that I don't even have time for a drink of water."], "keys": [{"en": "busy", "zh": "忙碌的"}, {"en": "even", "zh": "甚至、連"}], "point": "「so + adj. + that + 子句」表示如此…以致於…；be busy + V-ing 表「忙著做某事」；even 表「甚至、連」。", "topic": "part-time work", "level": "B2"}, {"id": "T139", "zh": "我很喜歡在書店打工，因為我可以和不同的客人聊天。", "en": "I really enjoy working part-time at the bookstore because I can chat with different customers.", "alt": ["I really enjoy my part-time job at the bookstore because I can chat with all kinds of customers."], "keys": [{"en": "enjoy", "zh": "喜歡、享受"}, {"en": "chat with", "zh": "和…聊天"}, {"en": "customer", "zh": "顧客"}], "point": "enjoy 後面接動名詞 V-ing 或名詞，不接不定詞；because 引導表原因的副詞子句。", "topic": "part-time work", "level": "B1"}, {"id": "T140", "zh": "王先生在這家公司已經工作了二十年，從來沒有請過一天假。", "en": "Mr. Wang has worked for this company for twenty years and has never taken a day off.", "alt": ["Mr. Wang has been working at this company for twenty years, and he has never taken a day off."], "keys": [{"en": "work for", "zh": "為…工作、任職於"}, {"en": "take a day off", "zh": "請一天假"}], "point": "現在完成式 has／have + p.p. 表示從過去持續到現在的狀態，搭配「for + 一段時間」；never 放在 has 與 p.p. 之間。", "topic": "workplace", "level": "B2"}, {"id": "T141", "zh": "我表哥大學畢業後，被一家科技公司錄用了。", "en": "After graduating from college, my cousin was hired by a technology company.", "alt": ["My cousin was hired by a tech company after he graduated from college."], "keys": [{"en": "graduate from", "zh": "從…畢業"}, {"en": "hire", "zh": "僱用、錄用"}], "point": "主詞是被錄用的人，用被動語態「be + p.p.」；After + V-ing 的省略主詞須與主要子句主詞（my cousin）相同。", "topic": "jobs", "level": "B1"}, {"id": "T142", "zh": "我妹妹才十五歲，年紀還不夠大，不能在餐廳打工。", "en": "My younger sister is only fifteen, so she isn't old enough to work part-time at a restaurant.", "alt": ["My younger sister is only fifteen years old and is not old enough to work part-time in a restaurant."], "keys": [{"en": "old enough", "zh": "年紀夠大"}, {"en": "work part-time", "zh": "打工"}], "point": "「adj. + enough + to V」表示夠…而能…，enough 修飾形容詞時放在形容詞之後。", "topic": "part-time work", "level": "B1"}, {"id": "T143", "zh": "我希望將來能在一個可以發揮創意的環境中工作。", "en": "In the future, I hope to work in an environment where I can make full use of my creativity.", "alt": ["I hope that someday I will be able to work in an environment in which I can use my creativity."], "keys": [{"en": "environment", "zh": "環境"}, {"en": "creativity", "zh": "創意、創造力"}], "point": "關係副詞 where 修飾表地點或場合的名詞，等於 in which；hope + to V 表希望做某事。", "topic": "career plans", "level": "B2"}, {"id": "T144", "zh": "因為工作時間太長，她決定辭掉那份工作。", "en": "She decided to quit that job because the working hours were too long.", "alt": ["Because the working hours were too long, she decided to quit that job."], "keys": [{"en": "decide", "zh": "決定"}, {"en": "quit", "zh": "辭掉、辭職"}, {"en": "working hours", "zh": "工作時間"}], "point": "decide + to V 表示決定做某事；quit 的過去式和過去分詞與原形同形（quit－quit－quit）。", "topic": "jobs", "level": "B1"}, {"id": "T145", "zh": "我真後悔面試前沒有多查一些那家公司的資料。", "en": "I really regret not looking up more information about the company before the interview.", "alt": ["I really should have looked up more information about that company before the interview."], "keys": [{"en": "regret", "zh": "後悔"}, {"en": "look up", "zh": "查詢"}, {"en": "information", "zh": "資料、資訊"}], "point": "「regret + (not) V-ing」後悔做過（沒做）某事；也可用「should have + p.p.」表示過去應該做卻沒做；information 為不可數名詞。", "topic": "job interviews", "level": "B2"}, {"id": "T146", "zh": "在這間超市，我負責整理貨架和幫客人結帳。", "en": "At this supermarket, I am responsible for organizing the shelves and helping customers check out.", "alt": ["I am in charge of organizing the shelves and helping customers check out at this supermarket."], "keys": [{"en": "be responsible for", "zh": "負責"}, {"en": "check out", "zh": "結帳"}], "point": "「be responsible for + N／V-ing」負責…，介系詞 for 後接動名詞；help + O + 原形V。", "topic": "workplace duties", "level": "B1"}, {"id": "T147", "zh": "在職場上，學會與同事好好合作和溝通是非常重要的。", "en": "In the workplace, it is very important to learn to cooperate and communicate well with your coworkers.", "alt": ["In the workplace, learning to work and communicate well with your coworkers is very important."], "keys": [{"en": "workplace", "zh": "職場"}, {"en": "cooperate", "zh": "合作"}, {"en": "coworker", "zh": "同事"}], "point": "虛主詞 it 代替真正的主詞（不定詞片語）：「It is + adj. + to V」；也可用動名詞片語直接當主詞。", "topic": "workplace", "level": "B2"}, {"id": "T148", "zh": "我打算存錢，畢業後到國外打工度假一年。", "en": "I plan to save money and go on a working holiday abroad for a year after I graduate.", "alt": ["I am going to save money and spend a year on a working holiday overseas after graduation."], "keys": [{"en": "save money", "zh": "存錢"}, {"en": "working holiday", "zh": "打工度假"}, {"en": "abroad", "zh": "在國外、到國外"}], "point": "plan + to V 表示打算做某事；abroad 是副詞，前面不加 to；時間副詞子句 after I graduate 用現在式表未來。", "topic": "career plans", "level": "B1"}, {"id": "T149", "zh": "只要你有自信又誠實地回答問題，就能讓面試官留下好印象。", "en": "As long as you answer the questions confidently and honestly, you will make a good impression on the interviewer.", "alt": ["As long as you answer the questions with confidence and honesty, the interviewer will have a good impression of you."], "keys": [{"en": "as long as", "zh": "只要"}, {"en": "make a good impression on", "zh": "使…留下好印象"}, {"en": "interviewer", "zh": "面試官"}], "point": "「as long as」只要；條件子句以現在式代替未來式；make a good impression on + 人＝讓某人留下好印象。", "topic": "job interviews", "level": "B2"}, {"id": "T150", "zh": "寄出履歷之前，記得要仔細檢查有沒有拼字錯誤。", "en": "Before sending out your résumé, remember to check it carefully for spelling mistakes.", "alt": ["Remember to check your résumé carefully for any spelling mistakes before you send it out."], "keys": [{"en": "send out", "zh": "寄出"}, {"en": "remember", "zh": "記得"}, {"en": "spelling mistake", "zh": "拼字錯誤"}], "point": "「remember + to V」記得要去做（尚未做）；「remember + V-ing」記得做過；介系詞 before 後接動名詞。", "topic": "job hunting", "level": "B1"}, {"id": "T151", "zh": "這家便利商店二十四小時營業，所以我們隨時都能買到飲料。", "en": "This convenience store is open 24 hours a day, so we can buy drinks at any time.", "alt": ["This convenience store stays open around the clock, so we can buy drinks at any time.", "Because this convenience store never closes, we can buy drinks whenever we want."], "keys": [{"en": "convenience store", "zh": "便利商店"}, {"en": "at any time", "zh": "隨時"}], "point": "open 在此為形容詞，「be open」表示營業中；「at any time」表示隨時、任何時候。", "topic": "convenience stores", "level": "B1"}, {"id": "T152", "zh": "我的錢不夠買那支新手機，所以我決定再存幾個月的錢。", "en": "I don't have enough money to buy that new phone, so I've decided to save up for a few more months.", "alt": ["I don't have enough money for that new phone, so I decided to save up for a few more months.", "Since I can't afford that new phone yet, I've decided to save up for another few months."], "keys": [{"en": "enough", "zh": "足夠的"}, {"en": "save up", "zh": "存錢"}], "point": "「enough + N + to V」表示有足夠的…去做…；「save up」表示存錢（為某目的而儲蓄）。", "topic": "saving money", "level": "B1"}, {"id": "T153", "zh": "這件外套太貴了，我買不起，只好等百貨公司週年慶再買。", "en": "This jacket is too expensive for me to buy, so I'll have to wait for the department store's anniversary sale.", "alt": ["This jacket is too expensive for me, so I'll have to wait until the department store's anniversary sale to buy it.", "I can't afford this jacket, so I have no choice but to wait for the department store's anniversary sale."], "keys": [{"en": "department store", "zh": "百貨公司"}, {"en": "anniversary sale", "zh": "週年慶"}], "point": "「too + adj. + for + 人 + to V」表示太…以致於某人無法…，句中不可再加 not。", "topic": "department store sales", "level": "B1"}, {"id": "T154", "zh": "如果你對這項產品不滿意，可以在七天內退貨。", "en": "If you are not satisfied with this product, you can return it within seven days.", "alt": ["You may return this product within seven days if you are not satisfied with it.", "If this product doesn't satisfy you, you can send it back within seven days."], "keys": [{"en": "satisfied with", "zh": "對…感到滿意"}, {"en": "return", "zh": "退還；退貨"}, {"en": "within", "zh": "在…之內"}], "point": "「be satisfied with」表示對…感到滿意；「within + 時間」表示在…之內；條件句用現在式。", "topic": "return policies", "level": "B1"}, {"id": "T155", "zh": "那位店員不但很有禮貌，而且很有耐心地回答我所有的問題。", "en": "The clerk was not only polite but also patient when answering all my questions.", "alt": ["Not only was the clerk polite, but she also answered all my questions patiently.", "The clerk was polite, and she also answered all of my questions with great patience."], "keys": [{"en": "clerk", "zh": "店員"}, {"en": "polite", "zh": "有禮貌的"}, {"en": "patient", "zh": "有耐心的"}], "point": "「not only A but also B」中 A 與 B 詞性須對等；Not only 置於句首時，後面的子句要倒裝。", "topic": "shop assistants", "level": "B2"}, {"id": "T156", "zh": "這支廣告的標語非常好記，連小孩子都能朗朗上口。", "en": "The slogan of this commercial is so easy to remember that even young children can repeat it.", "alt": ["This commercial has such a catchy slogan that even little kids can repeat it.", "The slogan in this ad is so easy to remember that even young kids know it by heart."], "keys": [{"en": "slogan", "zh": "標語；口號"}, {"en": "even", "zh": "甚至；連"}], "point": "「so + adj. + that + 子句」表示如此…以致於…；也可改用「such + a + adj. + N + that」。", "topic": "advertising slogans", "level": "B1"}, {"id": "T157", "zh": "自從那家公司開始在電視上打廣告，它的營業額就增加了一倍。", "en": "Since the company started advertising on TV, its sales have doubled.", "alt": ["The company's sales have doubled since it began to advertise on television.", "Ever since that company started advertising on TV, its sales have doubled."], "keys": [{"en": "advertise", "zh": "打廣告"}, {"en": "sales", "zh": "營業額；銷售量"}, {"en": "double", "zh": "加倍"}], "point": "「since + 過去式子句」表示自從…以來，主要子句用現在完成式 have/has + p.p.；double 可當動詞「加倍」。", "topic": "TV advertising", "level": "B2"}, {"id": "T158", "zh": "我們應該貨比三家，而不是買第一眼看到的東西。", "en": "We should shop around instead of buying the first thing we see.", "alt": ["Instead of buying the first thing we see, we should shop around.", "We should compare prices at different stores instead of buying the first item we see."], "keys": [{"en": "shop around", "zh": "貨比三家；四處比價"}, {"en": "instead of", "zh": "而不是"}], "point": "「instead of」為介系詞片語，後面接名詞或動名詞 V-ing；shop around 表示四處比價。", "topic": "smart shopping", "level": "B1"}, {"id": "T159", "zh": "現在越來越多公司請網紅在社群媒體上推銷他們的產品。", "en": "Nowadays, more and more companies hire influencers to promote their products on social media.", "alt": ["These days, more and more companies pay influencers to promote their products on social media.", "Nowadays, an increasing number of companies hire influencers to advertise their products on social media."], "keys": [{"en": "more and more", "zh": "越來越多的"}, {"en": "influencer", "zh": "網紅"}, {"en": "promote", "zh": "推銷；宣傳"}], "point": "「more and more + 複數名詞」表示越來越多的…；「hire + 人 + to V」表示僱用某人做某事。", "topic": "influencer marketing", "level": "B1"}, {"id": "T160", "zh": "這家餐廳的服務生都被訓練要面帶微笑地招呼每一位客人。", "en": "The waiters at this restaurant are trained to greet every customer with a smile.", "alt": ["This restaurant trains its waiters to greet every customer with a smile.", "All the servers in this restaurant are trained to welcome each guest with a smile."], "keys": [{"en": "be trained to", "zh": "被訓練去…"}, {"en": "greet", "zh": "招呼；迎接"}, {"en": "with a smile", "zh": "面帶微笑"}], "point": "主詞（服務生）是接受訓練的一方，用被動語態「be + p.p.」；「with a smile」表示面帶微笑地。", "topic": "restaurant service", "level": "B1"}, {"id": "T161", "zh": "我爸爸以前都用現金付款，但現在他已經習慣用信用卡了。", "en": "My father used to pay in cash, but now he is used to paying by credit card.", "alt": ["My dad always paid in cash in the past, but now he has gotten used to using a credit card.", "My father used to pay in cash, but he is now accustomed to paying with a credit card."], "keys": [{"en": "used to", "zh": "過去常常…（過去的習慣）"}, {"en": "be used to", "zh": "習慣於…"}, {"en": "in cash", "zh": "用現金"}], "point": "「used to + 原形V」表示過去的習慣；「be used to + V-ing」表示習慣於…，此處 to 是介系詞。", "topic": "ways of paying", "level": "B2"}, {"id": "T162", "zh": "我們花了整個下午才在夜市挑到一份合適的生日禮物。", "en": "It took us the whole afternoon to pick out a suitable birthday present at the night market.", "alt": ["We spent the whole afternoon picking out a suitable birthday gift at the night market.", "It took us all afternoon to choose a suitable birthday present at the night market."], "keys": [{"en": "pick out", "zh": "挑選"}, {"en": "suitable", "zh": "合適的"}], "point": "「It takes + 人 + 時間 + to V」表示某人花多少時間做某事；也可用「人 + spend + 時間 + V-ing」。", "topic": "gift shopping", "level": "B1"}, {"id": "T163", "zh": "那位顧客向店長抱怨，他上週買的耳機已經壞掉了。", "en": "The customer complained to the store manager that the earphones he had bought last week had already stopped working.", "alt": ["The customer complained to the store manager that the earphones he'd bought last week were already broken.", "The customer complained to the store manager that the earphones he had bought last week no longer worked."], "keys": [{"en": "complain to", "zh": "向…抱怨"}, {"en": "manager", "zh": "經理；店長"}, {"en": "stop working", "zh": "故障；停止運作"}], "point": "「complain to + 人 + that 子句」表示向某人抱怨…；買耳機發生在抱怨之前，用過去完成式 had + p.p.。", "topic": "customer complaints", "level": "B2"}, {"id": "T164", "zh": "我叔叔經營一家專門賣進口零食的小店。", "en": "My uncle runs a small shop that sells only imported snacks.", "alt": ["My uncle runs a little store which specializes in imported snacks.", "My uncle runs a small shop specializing in imported snacks."], "keys": [{"en": "run", "zh": "經營"}, {"en": "imported", "zh": "進口的"}], "point": "關係代名詞 that/which 引導形容詞子句修飾前面的事物（shop）；run 在此表示經營。", "topic": "small businesses", "level": "B1"}, {"id": "T165", "zh": "這家店的商品雖然比較貴，但品質比網路上賣的好得多。", "en": "Although this store's products are more expensive, they are of much better quality than the ones sold online.", "alt": ["This store's goods cost more, but their quality is much higher than that of the products sold online.", "This store's products are more expensive, but they are of much higher quality than those sold online."], "keys": [{"en": "although", "zh": "雖然"}, {"en": "quality", "zh": "品質"}], "point": "「much + 比較級」加強比較的程度；although 與 but 不可並用；「be of + adj. + quality」表示品質…。", "topic": "product quality", "level": "B2"}, {"id": "T166", "zh": "店員建議我先試穿這雙鞋，再決定要不要買。", "en": "The salesclerk suggested that I try on the shoes before deciding whether to buy them.", "alt": ["The salesclerk suggested I try on the shoes first and then decide whether or not to buy them.", "The salesclerk advised me to try the shoes on before I decided whether to buy them."], "keys": [{"en": "suggest", "zh": "建議"}, {"en": "try on", "zh": "試穿"}, {"en": "whether", "zh": "是否"}], "point": "「suggest that + 主詞 + (should) + 原形V」，should 常省略；before 為介系詞時後接 V-ing。", "topic": "shoe shopping", "level": "B2"}, {"id": "T167", "zh": "我寧願多花一點錢買耐用的東西，也不要一直買便宜貨。", "en": "I would rather pay a little more for durable things than keep buying cheap ones.", "alt": ["I would rather spend a bit more on durable products than keep buying cheap ones.", "I prefer to pay a little more for things that last rather than keep buying cheap ones."], "keys": [{"en": "would rather", "zh": "寧願"}, {"en": "durable", "zh": "耐用的"}], "point": "「would rather + 原形V1 + than + 原形V2」表示寧願…也不要…；「keep + V-ing」表示一直、持續…。", "topic": "shopping choices", "level": "B2"}, {"id": "T168", "zh": "因為景氣不好，這條街上很多小商店都被迫關門了。", "en": "Because of the poor economy, many small shops on this street have been forced to close.", "alt": ["Due to the bad economy, lots of small stores on this street have been forced to close down.", "Because the economy is weak, many small shops on this street have had to close."], "keys": [{"en": "because of", "zh": "因為；由於"}, {"en": "economy", "zh": "經濟"}, {"en": "be forced to", "zh": "被迫…"}], "point": "「because of + 名詞」、「because + 子句」用法不同；「be forced to + V」表示被迫…。", "topic": "the economy", "level": "B2"}, {"id": "T169", "zh": "每次這家超市打折，人們就會大排長龍搶購。", "en": "Whenever this supermarket has a sale, people wait in long lines to snap up bargains.", "alt": ["Every time this supermarket has a sale, people stand in long lines and rush to buy things.", "Whenever there is a sale at this supermarket, long lines form as shoppers rush to snap up bargains."], "keys": [{"en": "whenever", "zh": "每當"}, {"en": "have a sale", "zh": "舉辦特賣；打折"}, {"en": "snap up", "zh": "搶購"}], "point": "「whenever / every time + 子句」表示每當…；描述習慣性的事實用現在簡單式；「snap up」表示搶購，「wait in long lines」表示大排長龍。", "topic": "supermarket sales", "level": "B2"}, {"id": "T170", "zh": "為了吸引更多顧客，這家飲料店推出了買一送一的活動。", "en": "In order to attract more customers, this drink shop has launched a buy-one-get-one-free promotion.", "alt": ["To attract more customers, this drink shop is now offering a buy-one-get-one-free deal.", "This drink shop has launched a buy-one-get-one-free campaign so as to attract more customers."], "keys": [{"en": "in order to", "zh": "為了"}, {"en": "attract", "zh": "吸引"}, {"en": "launch", "zh": "推出"}], "point": "「in order to / so as to / to + 原形V」表示目的；放句首時用逗號與主要子句隔開。", "topic": "sales promotions", "level": "B1"}, {"id": "T171", "zh": "我姊姊每個月都把一半以上的薪水花在房租上。", "en": "My older sister spends more than half of her salary on rent every month.", "alt": ["Every month, my older sister spends over half of her salary on rent.", "More than half of my older sister's monthly salary is spent on rent."], "keys": [{"en": "spend", "zh": "花費"}, {"en": "salary", "zh": "薪水"}, {"en": "rent", "zh": "房租"}], "point": "「人 + spend + 金錢/時間 + on + N」表示把錢或時間花在…上；主詞為第三人稱單數，動詞加 s。", "topic": "monthly expenses", "level": "B1"}, {"id": "T172", "zh": "客服人員向我保證，這個問題明天以前就會解決。", "en": "The customer service representative promised me that the problem would be solved by tomorrow.", "alt": ["The customer service agent assured me that the problem would be fixed by tomorrow.", "The customer service representative promised me that the problem would be taken care of by tomorrow."], "keys": [{"en": "customer service", "zh": "客服"}, {"en": "promise", "zh": "保證；承諾"}, {"en": "solve", "zh": "解決"}], "point": "主詞是事物（問題）時用被動語態；主要動詞為過去式，that 子句時態跟著改為 would；「by + 時間」表示在…以前。", "topic": "customer service", "level": "B2"}, {"id": "T173", "zh": "許多年輕人很容易受到網路廣告的影響，結果買了不需要的東西。", "en": "Many young people are easily influenced by online advertisements and end up buying things they don't need.", "alt": ["Online ads can easily influence many young people, so they end up buying things they don't need.", "Lots of young people are easily influenced by Internet advertisements and end up buying unnecessary things."], "keys": [{"en": "influence", "zh": "影響"}, {"en": "advertisement", "zh": "廣告"}, {"en": "end up", "zh": "最後…；結果…"}], "point": "「be influenced by」表示受…影響（被動語態）；「end up + V-ing」表示結果、最後落得…。", "topic": "online ads", "level": "B1"}, {"id": "T174", "zh": "如果那家公司當初有聽取顧客的意見，就不會失去那麼多生意了。", "en": "If the company had listened to its customers' opinions, it wouldn't have lost so much business.", "alt": ["Had the company listened to its customers' opinions, it would not have lost so much business.", "If that company had paid attention to what its customers said, it wouldn't have lost so much business."], "keys": [{"en": "listen to", "zh": "聽取"}, {"en": "opinion", "zh": "意見"}, {"en": "lose", "zh": "失去"}], "point": "與過去事實相反的假設語氣：「If + 主詞 + had + p.p., 主詞 + would/could + have + p.p.」；省略 if 時可倒裝為 Had + 主詞 + p.p.。", "topic": "business mistakes", "level": "B2"}, {"id": "T175", "zh": "這個月我得省吃儉用，因為我已經把零用錢花光了。", "en": "I have to cut down on spending this month because I've already used up all my pocket money.", "alt": ["I need to live on a tight budget this month because I've already used up my pocket money.", "I have to cut down on spending this month since I've already spent all my pocket money."], "keys": [{"en": "cut down on", "zh": "減少"}, {"en": "use up", "zh": "用光"}, {"en": "pocket money", "zh": "零用錢"}], "point": "「cut down on + N/V-ing」表示減少…；「use up」表示用光，已完成的動作用現在完成式 have + p.p.。", "topic": "pocket money", "level": "B1"}, {"id": "T176", "zh": "一個塑膠袋在大自然中可能要花好幾百年才能分解。", "en": "It may take hundreds of years for a plastic bag to break down in nature.", "alt": ["A plastic bag can take hundreds of years to break down in nature.", "It can take several hundred years for a plastic bag to break down in the natural environment."], "keys": [{"en": "take", "zh": "花費（時間）"}, {"en": "break down", "zh": "分解"}, {"en": "hundreds of", "zh": "數以百計的"}], "point": "「It takes + 時間 + for + 人/物 + to V」表示某人/物做某事需要花多少時間；break down 在此指「分解」。", "topic": "plastic waste", "level": "B2"}, {"id": "T177", "zh": "我們應該把用過的寶特瓶和紙類分開，這樣它們才能被妥善回收。", "en": "We should separate used plastic bottles from paper so that they can be recycled properly.", "alt": ["Used plastic bottles should be separated from paper so that they can be properly recycled.", "We should sort used plastic bottles and paper separately so that they can be recycled properly."], "keys": [{"en": "separate", "zh": "分開"}, {"en": "recycle", "zh": "回收"}, {"en": "plastic bottle", "zh": "寶特瓶"}], "point": "「separate A from B」表示把 A 和 B 分開；so that + S + can + V 表示目的；物品「被回收」用被動語態 be recycled。", "topic": "recycling", "level": "B1"}, {"id": "T178", "zh": "最近空氣汙染非常嚴重，所以很多人出門時都戴著口罩。", "en": "Air pollution has been so serious recently that many people wear masks when they go out.", "alt": ["Recently, air pollution has been very serious, so many people wear masks when going out.", "Air pollution has been so bad lately that lots of people wear masks when they go out."], "keys": [{"en": "air pollution", "zh": "空氣汙染"}, {"en": "serious", "zh": "嚴重的"}, {"en": "go out", "zh": "出門"}], "point": "「so + adj. + that + 子句」表示「如此…以致於…」；描述從過去持續到現在的狀況可用現在完成式。", "topic": "air pollution", "level": "B1"}, {"id": "T179", "zh": "如果我們不停止砍伐森林，許多野生動物將會失去牠們的家園。", "en": "If we don't stop cutting down forests, many wild animals will lose their homes.", "alt": ["Many wild animals will lose their homes unless we stop cutting down forests.", "If we keep cutting down forests, a lot of wild animals will lose their homes."], "keys": [{"en": "cut down", "zh": "砍伐"}, {"en": "lose", "zh": "失去"}, {"en": "wild animal", "zh": "野生動物"}], "point": "「If + 現在式, S + will + V」表示對未來可能情況的條件句；stop + V-ing 表示停止做某事（stop + to V 則是停下來去做另一件事）。", "topic": "deforestation", "level": "B1"}, {"id": "T180", "zh": "全球暖化使得海平面上升，威脅到許多沿海城市。", "en": "Global warming has caused sea levels to rise, which threatens many coastal cities.", "alt": ["Rising sea levels caused by global warming are threatening many coastal cities.", "Because of global warming, sea levels are rising, and this threatens many cities along the coast."], "keys": [{"en": "global warming", "zh": "全球暖化"}, {"en": "sea level", "zh": "海平面"}, {"en": "threaten", "zh": "威脅"}], "point": "「cause + O + to V」表示造成…；非限定用法的「, which」可指前面整個子句所述之事，動詞用單數。", "topic": "global warming", "level": "B2"}, {"id": "T181", "zh": "騎腳踏車通勤比開車環保得多，而且也能省下不少錢。", "en": "Commuting by bike is much more environmentally friendly than driving, and it can also save a lot of money.", "alt": ["Cycling to work is much more environmentally friendly than driving a car, and it can save you a lot of money too.", "Commuting by bicycle is far more eco-friendly than driving, and it also saves a lot of money."], "keys": [{"en": "commute", "zh": "通勤"}, {"en": "environmentally friendly", "zh": "環保的"}, {"en": "save", "zh": "節省"}], "point": "比較級「much/far + 比較級 + than」表示「…得多」；動名詞片語 Commuting by bike 當主詞，動詞用單數。", "topic": "green commuting", "level": "B1"}, {"id": "T182", "zh": "這條河以前很髒，但多虧政府多年的整治，現在已經變乾淨了。", "en": "This river used to be very dirty, but thanks to years of cleanup efforts by the government, it is now clean.", "alt": ["This river was very dirty in the past, but it has become clean thanks to the government's efforts over the years.", "This river used to be really dirty, but it is clean now thanks to years of cleanup work by the government."], "keys": [{"en": "used to", "zh": "以前（曾經）"}, {"en": "thanks to", "zh": "多虧；由於"}], "point": "「used to + V」表示過去的狀態或習慣，現在已不再如此；thanks to + N 表示「多虧…」。", "topic": "river cleanup", "level": "B1"}, {"id": "T183", "zh": "新的限塑政策將從明年開始實施，餐廳將不再提供塑膠吸管。", "en": "The new policy on reducing plastic use will take effect next year, and restaurants will no longer provide plastic straws.", "alt": ["When the new policy to limit plastic use takes effect next year, restaurants will no longer offer plastic straws.", "The new policy to reduce plastic use will take effect next year, so restaurants will stop providing plastic straws."], "keys": [{"en": "take effect", "zh": "生效；實施"}, {"en": "no longer", "zh": "不再"}, {"en": "provide", "zh": "提供"}], "point": "take effect 表示（法規、政策）生效；no longer 表示「不再」，放在助動詞之後、一般動詞之前。", "topic": "plastic policy", "level": "B2"}, {"id": "T184", "zh": "那些被遊客留在海灘上的垃圾，最後常常會流入海洋，傷害海洋生物。", "en": "The trash that is left on the beach by tourists often ends up in the ocean and harms sea creatures.", "alt": ["Trash left on the beach by visitors often ends up in the sea, where it harms sea creatures.", "The garbage that tourists leave on the beach often ends up in the ocean, harming marine animals."], "keys": [{"en": "end up", "zh": "最後落得；最終到…"}, {"en": "harm", "zh": "傷害"}, {"en": "sea creature", "zh": "海洋生物"}], "point": "關係代名詞 that 引導形容詞子句修飾 trash，垃圾「被留下」用被動 is left；end up + 地點/V-ing 表示最後落得…。", "topic": "ocean pollution", "level": "B2"}, {"id": "T185", "zh": "上週末我們班參加了淨灘活動，撿了超過五十公斤的垃圾。", "en": "Last weekend, our class took part in a beach cleanup and picked up more than fifty kilograms of trash.", "alt": ["Our class took part in a beach cleanup last weekend, picking up over fifty kilograms of trash.", "Last weekend our class joined a beach cleanup activity and picked up more than 50 kilograms of garbage."], "keys": [{"en": "take part in", "zh": "參加"}, {"en": "pick up", "zh": "撿起"}], "point": "描述過去已完成的動作用過去簡單式；take part in（參加活動）和 pick up（撿起）皆為常考片語動詞。", "topic": "beach cleanup", "level": "B1"}, {"id": "T186", "zh": "農曆新年期間，家家戶戶都會貼春聯，祈求新的一年好運。", "en": "During Lunar New Year, every family puts up spring couplets to wish for good luck in the new year.", "alt": ["Families put up spring couplets during Lunar New Year, hoping for good luck in the coming year.", "During the Lunar New Year holiday, every household puts up spring couplets to wish for good fortune in the new year."], "keys": [{"en": "put up", "zh": "張貼"}, {"en": "wish for", "zh": "祈求；希望得到"}, {"en": "good luck", "zh": "好運"}], "point": "every + 單數名詞，動詞用單數（puts）；不定詞 to + V 表示目的；put up 表示張貼。", "topic": "Lunar New Year", "level": "B1"}, {"id": "T187", "zh": "人們慶祝端午節，是為了紀念一位名叫屈原的愛國詩人。", "en": "People celebrate the Dragon Boat Festival in memory of a patriotic poet named Qu Yuan.", "alt": ["The Dragon Boat Festival is celebrated in memory of a patriotic poet called Qu Yuan.", "People celebrate the Dragon Boat Festival to remember a patriotic poet named Qu Yuan."], "keys": [{"en": "celebrate", "zh": "慶祝"}, {"en": "in memory of", "zh": "紀念"}, {"en": "patriotic", "zh": "愛國的"}], "point": "in memory of + 人 表示「紀念某人」；過去分詞 named 修飾名詞，等於 who was named。", "topic": "Dragon Boat Festival", "level": "B1"}, {"id": "T188", "zh": "每年中秋節晚上，我們全家人都會一邊烤肉，一邊欣賞美麗的月亮。", "en": "Every year on the night of the Moon Festival, my whole family has a barbecue while enjoying the beautiful moon.", "alt": ["On Moon Festival night every year, my family enjoys the beautiful moon while having a barbecue together.", "Every Mid-Autumn Festival evening, my family has a barbecue and admires the beautiful moon at the same time."], "keys": [{"en": "have a barbecue", "zh": "烤肉"}, {"en": "enjoy", "zh": "欣賞；享受"}, {"en": "while", "zh": "一邊…一邊…；當…時"}], "point": "「while + V-ing」表示兩個動作同時進行（一邊…一邊…）；描述每年的習慣用現在簡單式，my whole family 視為單數。", "topic": "Moon Festival", "level": "B1"}, {"id": "T189", "zh": "據說只要在天燈上寫下願望，願望就會實現。", "en": "It is said that if you write your wishes on a sky lantern, they will come true.", "alt": ["People say that your wishes will come true if you write them on a sky lantern.", "Wishes written on a sky lantern are said to come true."], "keys": [{"en": "it is said that", "zh": "據說"}, {"en": "come true", "zh": "實現"}, {"en": "sky lantern", "zh": "天燈"}], "point": "「It is said that + 子句」等於「S + be said to + V」，表示「據說」；come true（實現）是不及物動詞片語，不可用被動。", "topic": "Lantern Festival", "level": "B2"}, {"id": "T190", "zh": "在台灣，很多人認為送別人時鐘當禮物會帶來厄運。", "en": "In Taiwan, many people believe that giving someone a clock as a gift brings bad luck.", "alt": ["Many people in Taiwan think it brings bad luck to give someone a clock as a gift.", "In Taiwan, giving a clock to someone as a present is believed by many to bring bad luck."], "keys": [{"en": "as a gift", "zh": "當作禮物"}, {"en": "bring bad luck", "zh": "帶來厄運"}, {"en": "believe", "zh": "相信；認為"}], "point": "動名詞片語 giving someone a clock 當主詞，動詞用單數 brings；也可用虛主詞 it 改寫為「It brings bad luck to + V」。", "topic": "gift taboos", "level": "B2"}, {"id": "T191", "zh": "阿美族每年都會舉行豐年祭，感謝祖靈帶來豐收。", "en": "Every year, the Amis people hold the Harvest Festival to thank the spirits of their ancestors for a good harvest.", "alt": ["The Harvest Festival is held by the Amis people every year to thank their ancestors' spirits for a rich harvest.", "The Amis hold a Harvest Festival every year to express thanks to their ancestors' spirits for a good harvest."], "keys": [{"en": "hold", "zh": "舉行"}, {"en": "thank", "zh": "感謝"}, {"en": "harvest", "zh": "收成"}], "point": "「thank + 人 + for + 事」表示為某事感謝某人；不定詞 to + V 表示目的；hold 在此指「舉行（活動）」。", "topic": "Indigenous festivals", "level": "B1"}, {"id": "T192", "zh": "雖然我的外國朋友一開始不敢吃臭豆腐，但他現在已經愛上它了。", "en": "Although my foreign friend didn't dare to try stinky tofu at first, he has now fallen in love with it.", "alt": ["My foreign friend was afraid to eat stinky tofu at first, but now he has fallen in love with it.", "At first, my foreign friend didn't dare to eat stinky tofu, but now he really loves it."], "keys": [{"en": "dare", "zh": "敢"}, {"en": "at first", "zh": "起初"}, {"en": "fall in love with", "zh": "愛上"}], "point": "英文的 although 與 but 不可同時使用，只能擇一；fall in love with 表示愛上，搭配現在完成式表示「已經」愛上。", "topic": "food culture", "level": "B2"}, {"id": "T193", "zh": "清明節時，許多人會回到家鄉掃墓，向祖先表達敬意。", "en": "On Tomb Sweeping Day, many people go back to their hometowns to sweep their family graves and show respect for their ancestors.", "alt": ["Many people return to their hometowns on Tomb Sweeping Day to clean their family graves and show respect to their ancestors.", "On Tomb Sweeping Day, lots of people return to their hometowns to clean their ancestors' tombs and pay their respects to them."], "keys": [{"en": "go back to", "zh": "回到"}, {"en": "hometown", "zh": "家鄉"}, {"en": "show respect", "zh": "表達敬意"}], "point": "不定詞 to + V 表示目的；show respect for/to + 人 表示對某人表達敬意。", "topic": "Tomb Sweeping Day", "level": "B1"}, {"id": "T194", "zh": "根據新聞報導，這起車禍是由一名酒駕的司機所造成的。", "en": "According to the news report, the car accident was caused by a drunk driver.", "alt": ["The news reported that a drunk driver caused the car accident.", "According to the news, a driver who had been drinking caused the car accident."], "keys": [{"en": "according to", "zh": "根據"}, {"en": "cause", "zh": "造成"}, {"en": "drunk driver", "zh": "酒駕司機"}], "point": "被動語態「be + p.p. + by + 人」表示「由某人所…」；according to 表示「根據」。", "topic": "news reports", "level": "B1"}, {"id": "T195", "zh": "隨著台灣的老年人口不斷增加，照顧長者已經成為一個重要的社會議題。", "en": "As Taiwan's elderly population keeps growing, taking care of seniors has become an important social issue.", "alt": ["As the elderly population in Taiwan continues to increase, taking care of older people has become a major social issue.", "With Taiwan's elderly population continuing to grow, caring for the elderly has become an important social issue."], "keys": [{"en": "keep", "zh": "持續；不斷"}, {"en": "take care of", "zh": "照顧"}, {"en": "social issue", "zh": "社會議題"}], "point": "keep + V-ing 表示「持續、不斷」；as 引導子句表示「隨著」；現在完成式 has become 表示已經成為。", "topic": "aging society", "level": "B2"}, {"id": "T196", "zh": "當志工不但能幫助有需要的人，也能讓我們自己變得更快樂。", "en": "Volunteering can not only help people in need but also make us happier.", "alt": ["Being a volunteer not only helps those in need but also makes us happier.", "Doing volunteer work can help people in need, and it can also make us feel happier."], "keys": [{"en": "volunteer", "zh": "當志工"}, {"en": "in need", "zh": "有需要的"}], "point": "「not only A but also B」連接兩個對等的動詞片語；make + O + adj. 表示使某人…，happier 為比較級。", "topic": "volunteering", "level": "B1"}, {"id": "T197", "zh": "地震發生後，許多人捐錢幫助那些失去家園的災民。", "en": "After the earthquake, many people donated money to help the victims who had lost their homes.", "alt": ["Many people donated money after the earthquake to help those who had lost their homes.", "After the earthquake struck, lots of people gave money to help the victims who lost their homes."], "keys": [{"en": "donate", "zh": "捐贈"}, {"en": "victim", "zh": "受害者；災民"}], "point": "關係代名詞 who 引導形容詞子句修飾 victims；過去完成式 had lost 表示比「捐錢」更早發生的動作。", "topic": "disaster relief", "level": "B2"}, {"id": "T198", "zh": "現在的年輕人已經習慣用手機看新聞，而不是看報紙。", "en": "Young people today have gotten used to reading the news on their phones rather than in newspapers.", "alt": ["Nowadays, young people are used to reading the news on their phones rather than in newspapers.", "These days, young people have gotten used to getting their news from their phones instead of from newspapers."], "keys": [{"en": "get used to", "zh": "習慣於"}, {"en": "rather than", "zh": "而不是"}], "point": "「be/get used to + V-ing」表示習慣於…（to 為介系詞，後接動名詞）；rather than 表示「而不是」。", "topic": "news habits", "level": "B1"}, {"id": "T199", "zh": "這則新聞聽起來太離譜了，不可能是真的，你最好先查證一下。", "en": "This news story sounds too ridiculous to be true, so you had better check the facts first.", "alt": ["This piece of news sounds so ridiculous that it can't be true; you'd better check it first.", "The news sounds too absurd to be true, so you had better check whether it is real first."], "keys": [{"en": "sound", "zh": "聽起來"}, {"en": "had better", "zh": "最好"}, {"en": "check", "zh": "查證；檢查"}], "point": "「too + adj. + to + V」表示「太…而不能…」；had better + 原形動詞 表示「最好…」。", "topic": "fake news", "level": "B1"}, {"id": "T200", "zh": "如果更多人願意讓座給需要的人，我們的社會就會變得更溫暖。", "en": "If more people were willing to give up their seats to those who need them, our society would become a warmer place.", "alt": ["Our society would be a warmer place if more people were willing to give up their seats to people in need.", "If more people are willing to offer their seats to those in need, our society will become a warmer place."], "keys": [{"en": "be willing to", "zh": "願意"}, {"en": "give up", "zh": "讓出；放棄"}], "point": "「If + S + 過去式（be 動詞用 were）, S + would + 原形動詞」表示與現在事實相反或不太可能的假設；若視為未來可能發生的情況，也可用「If + 現在式, S + will + V」；give up one's seat to + 人 表示讓座給某人。", "topic": "kindness in society", "level": "B2"}, {"id": "T201", "zh": "我每天早上七點起床，七點半出門上學。", "en": "I get up at seven every morning and leave for school at seven thirty.", "alt": ["I get up at seven o'clock every morning and leave for school at 7:30.", "Every morning, I get up at seven and leave home for school at half past seven."], "keys": [{"en": "get up", "zh": "起床"}, {"en": "leave for", "zh": "出發前往"}], "point": "表示每天的習慣用現在簡單式；「在幾點」用介系詞 at；leave for + 地點 表示「出發前往某地」。", "topic": "daily routine", "level": "A2"}, {"id": "T202", "zh": "我妹妹比我高。", "en": "My younger sister is taller than me.", "alt": ["My younger sister is taller than I am.", "My little sister is taller than me."], "keys": [{"en": "taller than", "zh": "比……高"}], "point": "比較兩者用比較級「形容詞 + -er + than」；than 後面可接受格 me，也可寫成 than I am。", "topic": "family", "level": "A2"}, {"id": "T203", "zh": "上個週末我們全家一起去海邊。", "en": "My whole family went to the beach last weekend.", "alt": ["Last weekend, my whole family went to the beach together.", "My family and I went to the beach last weekend."], "keys": [{"en": "went", "zh": "去（go 的過去式）"}, {"en": "beach", "zh": "海邊"}], "point": "句中有 last weekend 等過去時間，動詞用過去式；go 是不規則動詞，過去式為 went。", "topic": "weekend", "level": "A2"}, {"id": "T204", "zh": "氣象報告說明天會下雨。", "en": "The weather report says it will rain tomorrow.", "alt": ["The weather forecast says it will rain tomorrow.", "The weather report says that it will rain tomorrow."], "keys": [{"en": "weather report", "zh": "氣象報告"}, {"en": "will rain", "zh": "會下雨"}], "point": "預測未來會發生的事用 will + 原形動詞；主詞 The weather report 是第三人稱單數，現在式動詞 say 要加 -s。", "topic": "weather", "level": "A2"}, {"id": "T205", "zh": "我哥哥會說三種語言。", "en": "My older brother can speak three languages.", "alt": ["My big brother can speak three languages.", "My older brother speaks three languages."], "keys": [{"en": "can speak", "zh": "會說"}, {"en": "languages", "zh": "語言（複數）"}], "point": "助動詞 can 表示「能力」，後面接原形動詞；三種語言是複數，language 要加 -s。", "topic": "languages", "level": "A2"}, {"id": "T206", "zh": "在這間博物館裡不可以拍照。", "en": "You must not take photos in this museum.", "alt": ["You mustn't take pictures in this museum.", "You must not take pictures in this museum.", "You can't take pictures in this museum.", "Taking photos is not allowed in this museum."], "keys": [{"en": "must not", "zh": "不可以；禁止"}, {"en": "take photos", "zh": "拍照"}], "point": "must not（mustn't）表示「禁止、不可以」，後面接原形動詞。", "topic": "museum rules", "level": "A2"}, {"id": "T207", "zh": "那隻貓正在沙發上睡覺。", "en": "That cat is sleeping on the sofa.", "alt": ["That cat is sleeping on the couch.", "The cat over there is sleeping on the sofa."], "keys": [{"en": "is sleeping", "zh": "正在睡覺"}, {"en": "sofa", "zh": "沙發"}], "point": "表示說話時「正在」進行的動作用現在進行式：be 動詞 + V-ing。", "topic": "pets", "level": "A2"}, {"id": "T208", "zh": "你週末通常都做些什麼？", "en": "What do you usually do on weekends?", "alt": ["What do you usually do on the weekend?", "What do you usually do at weekends?"], "keys": [{"en": "usually", "zh": "通常"}, {"en": "on weekends", "zh": "在週末"}], "point": "一般動詞的疑問句：疑問詞 + do + 主詞 + 原形動詞；頻率副詞 usually 放在一般動詞前面。", "topic": "free time", "level": "A2"}, {"id": "T209", "zh": "這家麵包店的蛋糕是全台北最好吃的。", "en": "This bakery's cakes are the best in Taipei.", "alt": ["The cakes at this bakery are the best in Taipei.", "This bakery has the best cakes in Taipei.", "This bakery's cakes are the most delicious in Taipei."], "keys": [{"en": "bakery", "zh": "麵包店"}, {"en": "the best", "zh": "最好的"}], "point": "三者以上比較用最高級「the + 最高級」；good 的最高級是 best，屬於不規則變化。", "topic": "food", "level": "A2"}, {"id": "T210", "zh": "我昨天忘了帶數學課本。", "en": "I forgot to bring my math textbook yesterday.", "alt": ["Yesterday, I forgot to bring my math textbook.", "I forgot to bring my math book yesterday."], "keys": [{"en": "forgot to", "zh": "忘了（做某事）"}, {"en": "textbook", "zh": "課本"}], "point": "forget to + 原形動詞 表示「忘了去做某事」；forget 的過去式為 forgot。", "topic": "school", "level": "A2"}, {"id": "T211", "zh": "公園裡有很多人在跑步。", "en": "There are many people running in the park.", "alt": ["Many people are running in the park.", "There are a lot of people running in the park."], "keys": [{"en": "There are", "zh": "有"}, {"en": "running", "zh": "跑步"}], "point": "There are + 複數名詞 表示「某處有…」；名詞後面可接 V-ing，說明這些人正在做什麼。", "topic": "exercise", "level": "A2"}, {"id": "T212", "zh": "你可以幫我搬這個箱子嗎？", "en": "Can you help me carry this box?", "alt": ["Could you help me carry this box?", "Can you help me move this box?"], "keys": [{"en": "help me carry", "zh": "幫我搬"}, {"en": "box", "zh": "箱子"}], "point": "help + 人 + 原形動詞 表示「幫某人做某事」；Can you…? 用來請別人幫忙。", "topic": "asking for help", "level": "A2"}, {"id": "T213", "zh": "這個週末我打算去看電影。", "en": "I'm going to see a movie this weekend.", "alt": ["I am going to see a movie this weekend.", "I'm going to watch a movie this weekend.", "I plan to see a movie this weekend."], "keys": [{"en": "going to", "zh": "打算；將要"}, {"en": "movie", "zh": "電影"}], "point": "be going to + 原形動詞 表示事先計畫好的未來打算。", "topic": "weekend plans", "level": "A2"}, {"id": "T214", "zh": "外面太冷了，我們不能去游泳。", "en": "It's too cold outside for us to go swimming.", "alt": ["It is too cold outside, so we can't go swimming.", "It's so cold outside that we can't go swimming."], "keys": [{"en": "too cold", "zh": "太冷"}, {"en": "go swimming", "zh": "去游泳"}], "point": "too + 形容詞 + (for + 人) + to + 原形動詞 表示「太…而不能…」。", "topic": "weather", "level": "A2"}, {"id": "T215", "zh": "我的祖父母住在宜蘭的一個小村莊裡。", "en": "My grandparents live in a small village in Yilan.", "alt": ["My grandparents live in a little village in Yilan."], "keys": [{"en": "grandparents", "zh": "祖父母"}, {"en": "village", "zh": "村莊"}], "point": "主詞 My grandparents 是複數，現在簡單式動詞用原形 live，不加 -s；地點前用介系詞 in。", "topic": "family", "level": "A2"}, {"id": "T216", "zh": "我小時候很怕黑。", "en": "I was afraid of the dark when I was a child.", "alt": ["When I was little, I was afraid of the dark.", "I was scared of the dark when I was a kid."], "keys": [{"en": "afraid of", "zh": "害怕"}, {"en": "when I was a child", "zh": "我小時候"}], "point": "描述過去的狀態用過去式 was；be afraid of + 名詞 表示「害怕…」。", "topic": "childhood", "level": "A2"}, {"id": "T217", "zh": "這個暑假你想去日本旅行嗎？", "en": "Do you want to travel to Japan this summer vacation?", "alt": ["Would you like to travel to Japan this summer vacation?", "Do you want to take a trip to Japan this summer vacation?"], "keys": [{"en": "want to", "zh": "想要"}, {"en": "summer vacation", "zh": "暑假"}], "point": "want to + 原形動詞 表示「想要做…」；一般動詞的 Yes/No 疑問句以 Do 開頭，後接主詞和原形動詞。", "topic": "travel", "level": "A2"}, {"id": "T218", "zh": "睡覺前不要喝咖啡。", "en": "Don't drink coffee before you go to bed.", "alt": ["Do not drink coffee before you go to bed.", "Don't drink coffee before going to bed."], "keys": [{"en": "Don't drink", "zh": "不要喝"}, {"en": "go to bed", "zh": "上床睡覺"}], "point": "否定祈使句用 Don't + 原形動詞；before 可引導時間子句，表示「在…之前」。", "topic": "health", "level": "A2"}, {"id": "T219", "zh": "我的手機在哪裡？我找不到它。", "en": "Where is my phone? I can't find it.", "alt": ["Where's my phone? I can't find it.", "Where is my cell phone? I cannot find it."], "keys": [{"en": "can't find", "zh": "找不到"}], "point": "can't（cannot）+ 原形動詞 表示「無法…」；代名詞 it 用來代替前面提到的手機。", "topic": "daily life", "level": "A2"}, {"id": "T220", "zh": "那家便利商店就在我家對面。", "en": "That convenience store is right across from my house.", "alt": ["That convenience store is just across from my home.", "That convenience store is right across the street from my house."], "keys": [{"en": "convenience store", "zh": "便利商店"}, {"en": "across from", "zh": "在……對面"}], "point": "介系詞片語 across from 表示「在…的對面」；right 放在介系詞片語前面加強語氣，表示「就在」。", "topic": "neighborhood", "level": "A2"}, {"id": "T221", "zh": "他每天騎腳踏車上學。", "en": "He rides his bike to school every day.", "alt": ["He rides a bike to school every day.", "He goes to school by bike every day."], "keys": [{"en": "rides", "zh": "騎（第三人稱單數）"}, {"en": "every day", "zh": "每天"}], "point": "every day 表示習慣，用現在簡單式；主詞 He 是第三人稱單數，動詞 ride 要加 -s。", "topic": "transportation", "level": "A2"}, {"id": "T222", "zh": "我們上個月在學校種了一棵樹。", "en": "We planted a tree at school last month.", "alt": ["Last month, we planted a tree at our school.", "We planted a tree at our school last month."], "keys": [{"en": "planted", "zh": "種（plant 的過去式）"}, {"en": "last month", "zh": "上個月"}], "point": "規則動詞的過去式在字尾加 -ed，例如 plant → planted；last month 表示過去的時間。", "topic": "school activities", "level": "A2"}, {"id": "T223", "zh": "那個電視節目很無聊，所以我就把電視關掉了。", "en": "That TV show was very boring, so I turned off the TV.", "alt": ["That TV show was so boring that I turned the TV off.", "That TV program was really boring, so I turned off the TV."], "keys": [{"en": "boring", "zh": "無聊的"}, {"en": "turned off", "zh": "關掉（turn off 的過去式）"}], "point": "連接詞 so 表示「所以」，連接原因與結果；turn off 表示「關掉（電器）」，過去式為 turned off。", "topic": "entertainment", "level": "A2"}, {"id": "T224", "zh": "你最喜歡哪一種音樂？", "en": "What kind of music do you like best?", "alt": ["What kind of music do you like the most?", "What is your favorite kind of music?"], "keys": [{"en": "kind of", "zh": "種類"}, {"en": "like best", "zh": "最喜歡"}], "point": "「最喜歡」可用 like … best（或 like … the most）；What kind of + 名詞 用來詢問「哪一種…」。", "topic": "music", "level": "A2"}, {"id": "T225", "zh": "下課後我們一起去打籃球吧。", "en": "Let's play basketball together after class.", "alt": ["Let's go play basketball together after class.", "Let's go and play basketball after class.", "Let's play basketball together after school."], "keys": [{"en": "Let's", "zh": "我們……吧"}, {"en": "after class", "zh": "下課後"}], "point": "Let's（= Let us）+ 原形動詞 用來提議「我們一起…吧」；play + 球類運動時，球類名稱前不加 the。", "topic": "sports", "level": "A2"}, {"id": "T226", "zh": "如果當初政府沒有及早投資再生能源，我們現在恐怕就得面臨更嚴重的缺電問題。", "en": "If the government had not invested in renewable energy early on, we would probably be facing a more serious power shortage now.", "alt": ["Had the government not invested in renewable energy at an early stage, we would probably be facing more serious power shortages today.", "If the government hadn't invested early in renewable energy, we might be dealing with a worse power shortage now."], "keys": [{"en": "invest", "zh": "投資"}, {"en": "renewable energy", "zh": "再生能源"}, {"en": "power shortage", "zh": "缺電；電力短缺"}], "point": "混合假設語氣：if 子句與「過去事實」相反，用 had + p.p.；主要子句與「現在事實」相反，用 would + V（此處用進行式 would be facing，表示「現在正在面臨」）。", "topic": "energy policy", "level": "C1"}, {"id": "T227", "zh": "這項由台灣團隊研發的新技術，不僅能降低生產成本，還能大幅減少工廠的碳排放。", "en": "Not only can this new technology, developed by a Taiwanese team, lower production costs, but it can also greatly reduce carbon emissions from factories.", "alt": ["This new technology developed by a Taiwanese team can not only lower production costs but also greatly reduce factories' carbon emissions.", "Developed by a Taiwanese team, this new technology not only cuts production costs but also significantly reduces carbon emissions from factories."], "keys": [{"en": "not only", "zh": "不僅"}, {"en": "production cost", "zh": "生產成本"}, {"en": "carbon emission", "zh": "碳排放"}], "point": "Not only 置於句首時，其後的子句須倒裝（助動詞 can 移到主詞之前），後半句用 but (also)；過去分詞片語 developed by… 修飾 technology，表示被動。", "topic": "green technology", "level": "C1"}, {"id": "T228", "zh": "正是這位老師的一句鼓勵，說服了他不要放棄成為建築師的夢想。", "en": "It was one encouraging remark from this teacher that persuaded him not to give up on his dream of becoming an architect.", "alt": ["It was a single word of encouragement from this teacher that convinced him not to give up his dream of becoming an architect.", "What persuaded him not to abandon his dream of becoming an architect was one encouraging remark from this teacher."], "keys": [{"en": "encouraging", "zh": "鼓勵的"}, {"en": "persuade", "zh": "說服"}, {"en": "give up", "zh": "放棄"}], "point": "強調句（分裂句）「It was + 被強調部分 + that + 其餘部分」，用來強調主詞「這位老師的一句鼓勵」；persuade + O + (not) to V 表示「說服某人（不要）做某事」。", "topic": "career dreams", "level": "C1"}, {"id": "T229", "zh": "在海外工作十年之後，她決定回到台東，運用自己累積的經驗幫助家鄉發展觀光。", "en": "Having worked overseas for a decade, she decided to return to Taitung and draw on the experience she had accumulated to help develop tourism in her hometown.", "alt": ["After working abroad for ten years, she decided to move back to Taitung and use the experience she had gained to help her hometown develop its tourism.", "Having spent ten years working overseas, she chose to return to Taitung, drawing on the experience she had built up to promote tourism in her hometown."], "keys": [{"en": "overseas", "zh": "在海外"}, {"en": "draw on", "zh": "運用；借助（經驗、知識等）"}, {"en": "accumulate", "zh": "累積"}, {"en": "tourism", "zh": "觀光業"}], "point": "完成式分詞構句 Having + p.p. 表示「在主要子句的動作之前已經完成的事」，其主詞須與主要子句相同（she）；draw on 意為「運用；借助」；the experience (that) she had accumulated 為省略關係代名詞的形容詞子句，用過去完成式表示經驗在她回台東之前就已累積。", "topic": "returning home", "level": "C1"}, {"id": "T230", "zh": "為了防範地震、颱風等天災，專家建議每個家庭都準備一個緊急避難包，裡面要有水、食物、手電筒和急救用品。", "en": "To guard against natural disasters such as earthquakes and typhoons, experts recommend that every household prepare an emergency kit containing water, food, a flashlight and first-aid supplies.", "alt": ["Experts suggest that every family should prepare an emergency bag with water, food, a flashlight and first-aid supplies in case of natural disasters like earthquakes and typhoons.", "To be ready for natural disasters such as earthquakes and typhoons, experts recommend that each household have an emergency kit containing water, food, a flashlight and first-aid items."], "keys": [{"en": "natural disaster", "zh": "天災；自然災害"}, {"en": "emergency kit", "zh": "緊急避難包"}, {"en": "first-aid", "zh": "急救的"}], "point": "recommend、suggest 等表示「建議」的動詞後接 that 子句時，子句動詞用「(should) + 原形」，故為 every household prepare（不加 s）；containing… 為現在分詞片語，修飾 kit。", "topic": "disaster preparedness", "level": "C1"}, {"id": "T231", "zh": "唯有當我們真正了解其他文化的價值觀時，才能避免用自己的標準去評斷別人。", "en": "Only when we truly understand the values of other cultures can we avoid judging others by our own standards.", "alt": ["Only when we really understand the values of other cultures will we be able to avoid judging people by our own standards.", "We can avoid judging others by our own standards only when we truly understand the values of other cultures."], "keys": [{"en": "values", "zh": "價值觀"}, {"en": "avoid", "zh": "避免（後接 V-ing）"}, {"en": "standard", "zh": "標準"}], "point": "「Only + when 子句」置於句首時，主要子句須倒裝（助動詞 can 移到主詞 we 之前）；avoid 後接動名詞 judging。", "topic": "cultural understanding", "level": "C1"}, {"id": "T232", "zh": "淡水紅毛城最初由西班牙人在十七世紀興建，後來由荷蘭人重建，最後還曾作為英國領事館。", "en": "Originally built by the Spanish in the seventeenth century, Fort San Domingo in Tamsui was later rebuilt by the Dutch and eventually served as the British consulate.", "alt": ["Fort San Domingo in Tamsui was first built by the Spanish in the 17th century, later rebuilt by the Dutch, and eventually used as the British consulate.", "First built by the Spanish in the seventeenth century, Tamsui's Fort San Domingo was later rebuilt by the Dutch and finally became the British consulate."], "keys": [{"en": "originally", "zh": "最初；原本"}, {"en": "rebuilt", "zh": "重建（rebuild 的過去分詞）"}, {"en": "consulate", "zh": "領事館"}], "point": "以過去分詞 built 開頭的分詞構句表示被動（＝ It was originally built…），其邏輯主詞須與主要子句的主詞 Fort San Domingo 一致；serve as 表示「充當；作為…之用」。", "topic": "Taiwanese history", "level": "C1"}, {"id": "T233", "zh": "這部紀錄片大受歡迎，以至於全台的電影院都不得不加開場次，以滿足觀眾的需求。", "en": "So popular was the documentary that cinemas across Taiwan had to add extra screenings to meet the demand from audiences.", "alt": ["The documentary was so popular that cinemas across Taiwan had to add more showings to meet audience demand.", "The documentary proved so popular that movie theaters all over Taiwan were forced to add extra screenings to satisfy viewers."], "keys": [{"en": "documentary", "zh": "紀錄片"}, {"en": "screening", "zh": "放映（場次）"}, {"en": "meet the demand", "zh": "滿足需求"}], "point": "「So + adj. + be 動詞 + S + that…」為 so…that（如此…以致於）的倒裝句型，用來強調形容詞 popular；meet the demand 表示「滿足需求」。", "topic": "film", "level": "C1"}, {"id": "T234", "zh": "如果不是這些志工每晚在海灘巡守，許多海龜蛋就會被偷走或遭到破壞。", "en": "Were it not for the volunteers who patrol the beach every night, many sea turtle eggs would be stolen or destroyed.", "alt": ["If it were not for the volunteers patrolling the beach every night, many sea turtle eggs would be stolen or damaged.", "Without the volunteers who guard the beach each night, a lot of sea turtle eggs would be stolen or destroyed."], "keys": [{"en": "were it not for", "zh": "若不是有…"}, {"en": "patrol", "zh": "巡邏；巡守"}, {"en": "sea turtle", "zh": "海龜"}], "point": "與現在事實相反的假設「若不是有…」可用 If it were not for…，省略 if 後倒裝為 Were it not for…，主要子句用 would + V；蛋「被偷、被破壞」用被動 be stolen / destroyed。", "topic": "wildlife conservation", "level": "C1"}, {"id": "T235", "zh": "無論人工智慧變得多麼先進，它都無法完全取代人與人之間面對面交流所帶來的溫暖。", "en": "However advanced artificial intelligence becomes, it will never completely replace the warmth that comes from face-to-face communication between people.", "alt": ["No matter how advanced artificial intelligence becomes, it cannot fully replace the warmth of face-to-face communication between people.", "No matter how advanced AI gets, it will never be able to completely take the place of the warmth that face-to-face interaction brings."], "keys": [{"en": "artificial intelligence", "zh": "人工智慧"}, {"en": "replace", "zh": "取代"}, {"en": "face-to-face", "zh": "面對面的"}], "point": "「However + adj. + S + V」＝「No matter how + adj. + S + V」，表示「無論多麼…」，形容詞須緊接在 however 之後；the warmth that comes from… 為形容詞子句。", "topic": "AI and relationships", "level": "C1"}, {"id": "T236", "zh": "真正讓這家小書店存活下來的，並不是低價，而是老闆對每位顧客閱讀喜好的了解。", "en": "What has really kept this small bookstore alive is not low prices but the owner's knowledge of every customer's reading tastes.", "alt": ["What has truly allowed this little bookstore to survive is not its low prices but the owner's understanding of each customer's reading preferences.", "It is not low prices but the owner's knowledge of every customer's reading tastes that has really kept this small bookstore going."], "keys": [{"en": "alive", "zh": "存活的（keep + O + alive 使…存活下去）"}, {"en": "knowledge", "zh": "了解；知識"}, {"en": "reading tastes", "zh": "閱讀喜好"}], "point": "「What + 子句 + is…」為準分裂句，用來強調「真正讓書店存活的原因」；not A but B 表示「不是 A 而是 B」，A、B 須為對等的名詞片語。", "topic": "small businesses", "level": "C1"}, {"id": "T237", "zh": "考慮到台灣人口老化的速度很快，政府應該盡早規劃更完善的長期照顧制度。", "en": "Considering how rapidly Taiwan's population is aging, the government should plan a more comprehensive long-term care system as soon as possible.", "alt": ["Given that Taiwan's population is aging so quickly, the government should develop a more complete long-term care system as early as possible.", "In view of the rapid aging of Taiwan's population, the government ought to plan a better long-term care system without delay."], "keys": [{"en": "aging", "zh": "老化"}, {"en": "comprehensive", "zh": "全面的；完善的"}, {"en": "long-term care", "zh": "長期照顧"}], "point": "Considering / Given that 意為「考慮到…；鑑於…」，為慣用的分詞片語，不必與主要子句的主詞一致；how rapidly… 為名詞子句，作 considering 的受詞。", "topic": "aging society", "level": "C1"}, {"id": "T238", "zh": "這位登山客把路線的每個細節都告訴家人，唯恐萬一在山上迷路時沒有人知道他在哪裡。", "en": "The hiker told his family every detail of his route for fear that nobody would know where he was if he got lost in the mountains.", "alt": ["The hiker gave his family the details of his route so that someone would know where he was if he got lost in the mountains.", "The hiker shared every detail of his route with his family in case he got lost in the mountains and nobody knew where he was."], "keys": [{"en": "for fear that", "zh": "唯恐；以免"}, {"en": "route", "zh": "路線"}, {"en": "lost", "zh": "迷路的（get lost 迷路）"}], "point": "for fear that + S + would/might + V 表示「唯恐…；以免…」，與 in case 意思相近；where he was 為間接問句，須用直述句的語序。", "topic": "mountain safety", "level": "C1"}, {"id": "T239", "zh": "那位作家把十九世紀倫敦的街道描寫得非常生動，彷彿她曾親自在那裡生活過一樣。", "en": "The writer describes the streets of nineteenth-century London so vividly that it is as if she had lived there herself.", "alt": ["The author describes the streets of 19th-century London vividly, as if she had actually lived there herself.", "The way the writer describes the streets of London in the 1800s is so vivid that it seems as though she had lived there in person."], "keys": [{"en": "vividly", "zh": "生動地"}, {"en": "as if", "zh": "彷彿；好像"}, {"en": "century", "zh": "世紀"}], "point": "as if / as though 可引導與事實相反的假設，指過去的事時用 had + p.p.（她其實不可能住過那裡）；so + adv. + that… 表示「如此…以致於」。", "topic": "literature", "level": "C1"}, {"id": "T240", "zh": "雖然常有人說從月球上看得到長城，但事實上長城太窄了，根本無法用肉眼看見。", "en": "Although the Great Wall is often said to be visible from the Moon, it is in fact far too narrow to be seen with the naked eye.", "alt": ["It is often said that the Great Wall can be seen from the Moon, but in fact it is much too narrow to be seen with the naked eye.", "The Great Wall is often claimed to be visible from the Moon; in reality, however, it is far too narrow to be seen with the naked eye."], "keys": [{"en": "visible", "zh": "看得見的"}, {"en": "narrow", "zh": "狹窄的"}, {"en": "naked eye", "zh": "肉眼"}], "point": "「S + be said to + V」＝ It is said that…，表示「據說…」；too + adj. + to V 表示「太…而無法…」，長城「被看見」用被動 to be seen。", "topic": "science myths", "level": "C1"}, {"id": "T241", "zh": "早知道這份實習每天都要工作到半夜，我當初就會選擇另一家公司了。", "en": "Had I known that this internship would require me to work until midnight every day, I would have chosen a different company.", "alt": ["If I had known that this internship would require me to work until midnight every day, I would have chosen another company.", "Had I known I would have to work until midnight every day at this internship, I would have picked a different company."], "keys": [{"en": "Had I known", "zh": "早知道…（與過去事實相反的倒裝）"}, {"en": "internship", "zh": "實習"}, {"en": "require", "zh": "要求；需要"}], "point": "與過去事實相反的假設 If I had known…，省略 if 後倒裝為 Had I known…，主要子句用 would have + p.p.；require + O + to V 表示「要求某人做…」。", "topic": "internships", "level": "C1"}, {"id": "T242", "zh": "許多國家已經採用一種制度，讓民眾可以把空的瓶罐退回商店並拿回押金。", "en": "Many countries have adopted a system in which people can return empty bottles and cans to stores and get their deposits back.", "alt": ["Many countries have introduced a system whereby people can take empty bottles and cans back to shops and get their deposits returned.", "A lot of countries have adopted a system that allows people to return empty drink containers to stores and get their deposits back."], "keys": [{"en": "adopt", "zh": "採用"}, {"en": "in which", "zh": "（介系詞 + 關係代名詞）在其中；藉此"}, {"en": "deposit", "zh": "押金"}], "point": "「介系詞 + which」引導形容詞子句修飾 system（in which ＝ whereby，表示「藉由此制度」）；get + O + back 表示「拿回…」。", "topic": "recycling", "level": "C1"}, {"id": "T243", "zh": "1999 年集集大地震的威力如此強大，以至於有些地方的地面被抬升了好幾公尺。", "en": "Such was the force of the 1999 Chi-Chi earthquake that the ground in some areas was pushed up by several meters.", "alt": ["The 1999 Chi-Chi earthquake was so powerful that in some places the ground was raised by several meters.", "So strong was the 1999 Chi-Chi earthquake that the ground in certain areas was lifted several meters."], "keys": [{"en": "such was", "zh": "（倒裝）…是如此之大"}, {"en": "force", "zh": "力量；威力"}, {"en": "pushed up", "zh": "被往上推；被抬升"}], "point": "「Such + be + N + that…」為 such…that（如此…以致於）的倒裝句型，強調名詞 the force；地面「被抬升」用被動 was pushed up，介系詞 by 表示幅度或差距。", "topic": "earthquakes", "level": "C1"}, {"id": "T244", "zh": "在網路上分享資訊之前，我們必須先確認消息來源是否可靠，以免在無意中散播假新聞。", "en": "It is essential that we check whether a source is reliable before sharing information online, so that we do not spread fake news unintentionally.", "alt": ["Before sharing information online, it is essential that we check whether the source is reliable so as not to spread fake news by accident.", "We must make sure that a source is trustworthy before we share information on the Internet, or we may spread fake news without meaning to."], "keys": [{"en": "essential", "zh": "必要的；極重要的"}, {"en": "reliable", "zh": "可靠的"}, {"en": "source", "zh": "（消息）來源"}, {"en": "fake news", "zh": "假新聞"}], "point": "It is essential / necessary / important that + S + (should) + 原形 V，故用 we check；whether 引導名詞子句，表示「是否」；so that… 表示目的。", "topic": "media literacy", "level": "C1"}, {"id": "T245", "zh": "儘管只受過六年的正規教育，這位農夫靠著自學，成為台灣備受尊敬的昆蟲專家。", "en": "Despite having received only six years of formal education, the farmer became a highly respected insect expert in Taiwan by teaching himself.", "alt": ["Although he had only six years of formal schooling, the farmer became one of Taiwan's most respected insect experts through self-study.", "In spite of having had just six years of formal education, the farmer educated himself and went on to become a highly respected insect expert in Taiwan."], "keys": [{"en": "despite", "zh": "儘管（介系詞，後接 N / V-ing）"}, {"en": "formal education", "zh": "正規教育"}, {"en": "teaching himself", "zh": "自學（teach oneself）"}, {"en": "highly respected", "zh": "備受尊敬的"}], "point": "despite / in spite of 為介系詞，後接名詞或動名詞，不可直接接子句；having received 為完成式動名詞，表示比主要動詞更早發生的事；by + V-ing 表示「藉由…（方法）」。", "topic": "self-learning", "level": "C1"}, {"id": "T246", "zh": "我很少遇到像她這樣的人，即使在極大的壓力下，仍然能保持冷靜並做出正確的決定。", "en": "Seldom have I met anyone who, like her, can stay calm and make the right decisions even under extreme pressure.", "alt": ["I have seldom met anyone like her who can remain calm and make the right decisions even under enormous pressure.", "Rarely have I met a person who, like her, is able to stay calm and make the right decisions even under extreme pressure."], "keys": [{"en": "seldom", "zh": "很少"}, {"en": "stay calm", "zh": "保持冷靜"}, {"en": "pressure", "zh": "壓力"}], "point": "否定副詞 Seldom / Rarely 置於句首時，主要子句須倒裝（have I met）；even under extreme pressure 意為「即使在極大的壓力下」。", "topic": "leadership", "level": "C1"}, {"id": "T247", "zh": "有些人認為觀光能帶動當地經濟，另一些人卻擔心大批遊客會破壞這座小島原本寧靜的生活方式。", "en": "While some argue that tourism can boost the local economy, others fear that an influx of visitors will destroy the tranquil way of life the island has long enjoyed.", "alt": ["Some believe tourism can boost the local economy, whereas others fear that huge crowds of tourists will ruin the island's peaceful way of life.", "Although some people think tourism will give the local economy a boost, others are concerned that large numbers of tourists will destroy the quiet way of life the island used to enjoy."], "keys": [{"en": "boost", "zh": "促進；提振"}, {"en": "local economy", "zh": "當地經濟"}, {"en": "influx", "zh": "（人潮等）湧入"}, {"en": "way of life", "zh": "生活方式"}], "point": "while / whereas 可表示對比「…，而…」；some…others… 表示「有些人…，另一些人…」；an influx of + N 表示「大量湧入的…」；the island has long enjoyed 為省略關係代名詞的形容詞子句，修飾 way of life，表達「原本」享有的寧靜生活。", "topic": "tourism", "level": "C1"}, {"id": "T248", "zh": "當時沒有人想得到，那位在夜市賣小吃的年輕人，日後竟會成為全國最成功的企業家之一。", "en": "Nobody could have imagined at the time that the young man selling snacks at the night market was to become one of the most successful entrepreneurs in the country.", "alt": ["At that time, no one could have imagined that the young man selling snacks at the night market would one day become one of the country's most successful entrepreneurs.", "No one at the time could have guessed that the young man who sold snacks at the night market would later become one of the most successful businesspeople in the country."], "keys": [{"en": "could have imagined", "zh": "（當時）能夠想像得到"}, {"en": "was to become", "zh": "日後（注定）會成為"}, {"en": "entrepreneur", "zh": "企業家；創業家"}], "point": "「was / were to + V」可表示過去的人「日後（注定）會…」；could have + p.p. 表示對過去可能性的推測，nobody could have imagined 即「當時沒有人想得到」；現在分詞片語 selling snacks… 修飾 the young man。", "topic": "entrepreneurs", "level": "C1"}, {"id": "T249", "zh": "有些研究指出，社群媒體非但沒有拉近青少年之間的距離，反而讓許多人覺得比以往更孤單。", "en": "Far from bringing teenagers closer together, social media has, according to some studies, left many of them feeling lonelier than ever before.", "alt": ["According to some studies, instead of bringing teenagers closer, social media has made many of them feel lonelier than before.", "Some studies suggest that, far from drawing teenagers closer together, social media has actually made many of them lonelier than ever."], "keys": [{"en": "far from", "zh": "非但不…；一點也不…"}, {"en": "according to", "zh": "根據"}, {"en": "lonelier", "zh": "更孤單的（lonely 的比較級）"}], "point": "Far from + V-ing 表示「非但沒有…，反而…」；leave + O + V-ing 表示「使…處於某種狀態」，也可改用 make + O + 原形 V（made them feel）。", "topic": "social media", "level": "C1"}, {"id": "T250", "zh": "萬一這座冰川完全融化，下游數百萬仰賴它供水的居民將面臨嚴重的缺水危機。", "en": "Were this glacier to melt completely, the millions of people downstream who depend on it for water would face a severe shortage.", "alt": ["If this glacier were to melt completely, millions of people living downstream who rely on it for their water would face a serious water shortage.", "Should this glacier melt entirely, the millions of people downstream who depend on it for water would suffer a severe water shortage."], "keys": [{"en": "glacier", "zh": "冰川"}, {"en": "downstream", "zh": "在下游"}, {"en": "depend on", "zh": "依賴"}, {"en": "shortage", "zh": "短缺"}], "point": "假設未來不太可能發生的事可用 If + S + were to + V，省略 if 後倒裝為 Were + S + to + V，主要子句用 would + V；depend on A for B 表示「依賴 A 提供 B」。", "topic": "climate change", "level": "C1"}, {"id": "T251", "zh": "一個科學理論之所以可信，並不是因為它從未受到質疑，而是因為它一次又一次地經得起嚴格的檢驗。", "en": "A scientific theory is credible not because it has never been questioned, but because it has withstood rigorous testing time and time again.", "alt": ["What gives a scientific theory its credibility is not that it has never been challenged, but that it has stood up to rigorous scrutiny again and again."], "keys": [{"en": "credible", "zh": "可信的"}, {"en": "not because", "zh": "並不是因為"}, {"en": "withstood", "zh": "經得起（withstand 的過去分詞）"}, {"en": "rigorous testing", "zh": "嚴格的檢驗"}, {"en": "time and time again", "zh": "一次又一次"}], "point": "「之所以……，並不是因為 A，而是因為 B」可譯為 S + be + adj. + not because A, but because B；也可用 What gives… is not that…, but that…（名詞子句作主詞與補語）。withstand 的過去式與過去分詞皆為 withstood，意為「經得起、承受住」，常與 testing、pressure、scrutiny 搭配；stand up to scrutiny 亦表「經得起檢視」。現在完成式 has withstood 表示「到目前為止一再經得起」。", "topic": "scientific method", "level": "C2"}, {"id": "T252", "zh": "衡量一座城市是否友善，往往不是看它蓋了多少地標建築，而是看行人能不能安心地走在人行道上。", "en": "The measure of a city's friendliness is often not how many landmarks it has built, but whether pedestrians can walk its sidewalks without fear.", "alt": ["Whether a city is friendly often depends less on the number of landmark buildings it has put up than on whether people can walk safely along its sidewalks."], "keys": [{"en": "measure of", "zh": "衡量……的標準"}, {"en": "landmark", "zh": "地標"}, {"en": "pedestrians", "zh": "行人"}, {"en": "without fear", "zh": "安心地；無所畏懼地"}, {"en": "depends less on", "zh": "與其說取決於……"}], "point": "「衡量……的標準」可用 the measure of sth，後接 is not A but B，A、B 皆為名詞子句（how many… / whether…）；另一譯法 depend less on A than on B 表「與其說取決於 A，不如說取決於 B」，語氣較委婉。walk its sidewalks 中的 walk 作及物動詞，意為「走在……上」。", "topic": "urban life", "level": "C2"}, {"id": "T253", "zh": "翻譯詩歌最難的地方，與其說是找到對等的字詞，不如說是保留原文的節奏與言外之意。", "en": "The hardest part of translating poetry is not so much finding equivalent words as preserving the rhythm and unspoken implications of the original.", "alt": ["What makes poetry so hard to translate is less the search for equivalent words than the challenge of keeping the original's rhythm and everything it leaves unsaid."], "keys": [{"en": "not so much", "zh": "與其說……"}, {"en": "equivalent", "zh": "對等的"}, {"en": "rhythm", "zh": "節奏"}, {"en": "unspoken implications", "zh": "言外之意"}, {"en": "leaves unsaid", "zh": "沒有明說（的部分）"}], "point": "「與其說是 A，不如說是 B」用 not so much A as B，A 與 B 須為對等結構（finding / preserving 皆為動名詞）；less A than B 也有相同意思。「言外之意」可譯為 unspoken implications、subtext 或 what is left unsaid；the original 在此指「原文」。", "topic": "literary translation", "level": "C2"}, {"id": "T254", "zh": "我們在享受免費應用程式所帶來的便利時，很少意識到自己其實是以個人資料作為代價。", "en": "While enjoying the convenience of free apps, we seldom realize that we are in fact paying for it with our personal data.", "alt": ["Seldom do we realize, as we enjoy the convenience of free apps, that it comes at the cost of our personal data."], "keys": [{"en": "convenience", "zh": "便利"}, {"en": "seldom do we realize", "zh": "我們很少意識到（倒裝）"}, {"en": "paying for it with", "zh": "以……來支付"}, {"en": "at the cost of", "zh": "以……為代價"}, {"en": "personal data", "zh": "個人資料"}], "point": "否定副詞 seldom、rarely 置於句首時，主要子句須倒裝（Seldom do we realize…）；while + V-ing 為省略主詞的副詞子句，表「在……的同時」。「以……為代價」可用 pay for sth with…，或 come at the cost / price of…。", "topic": "digital privacy", "level": "C2"}, {"id": "T255", "zh": "一旦某個物種從生態系中消失，它所引發的連鎖反應往往要過好幾十年才會完全顯現出來。", "en": "Once a species disappears from an ecosystem, the ripple effects it sets in motion often take decades to become fully apparent.", "alt": ["When a species vanishes from an ecosystem, it is often decades before the chain reaction it has triggered becomes fully visible."], "keys": [{"en": "ecosystem", "zh": "生態系"}, {"en": "ripple effects", "zh": "連鎖效應"}, {"en": "sets in motion", "zh": "引發；啟動"}, {"en": "it is often decades before", "zh": "往往要過好幾十年才……"}, {"en": "apparent", "zh": "明顯的；顯而易見的"}], "point": "「要過了（一段時間）才……」可用 take + 時間 + to V，或 It is + 時間 + before…；ripple effect / chain reaction 意為「連鎖效應、連鎖反應」；set sth in motion 意為「使……開始運作、引發」，關係子句 it sets in motion 省略了作受詞的關係代名詞 that。", "topic": "biodiversity", "level": "C2"}, {"id": "T256", "zh": "有些人把忙碌當成成就的象徵，卻沒有察覺長期過勞正悄悄地侵蝕他們的健康與創造力。", "en": "Some people treat being busy as a badge of achievement, without noticing that chronic overwork is quietly eroding their health and creativity.", "alt": ["Some regard busyness as a mark of achievement, oblivious to the way prolonged overwork is quietly wearing down their health and creativity."], "keys": [{"en": "badge of", "zh": "……的象徵（標誌）"}, {"en": "chronic overwork", "zh": "長期過勞"}, {"en": "eroding", "zh": "侵蝕；逐漸削弱"}, {"en": "oblivious to", "zh": "對……渾然不覺"}, {"en": "wearing down", "zh": "逐漸消磨"}], "point": "treat / regard A as B「把 A 視為 B」；a badge of honor / achievement 指「（引以為傲的）象徵」；erode 原指「侵蝕（岩石、土壤）」，引申為「逐漸削弱」，常與 health、trust、confidence 搭配；oblivious to sth 為形容詞片語，補充說明主詞的狀態「對……渾然不覺」。", "topic": "work-life balance", "level": "C2"}, {"id": "T257", "zh": "若不是那些抄寫員一字一句地謄抄古籍，許多古代的思想恐怕早就失傳了。", "en": "Had it not been for the scribes who painstakingly copied ancient texts word by word, many ideas from antiquity would in all likelihood have been lost long ago.", "alt": ["But for the scribes who laboriously copied out old manuscripts one word at a time, a great many ancient ideas would probably have disappeared long ago."], "keys": [{"en": "had it not been for", "zh": "若不是（有）……"}, {"en": "painstakingly", "zh": "費盡心力地；一絲不苟地"}, {"en": "antiquity", "zh": "古代"}, {"en": "in all likelihood", "zh": "十之八九；恐怕"}, {"en": "but for", "zh": "要不是"}], "point": "與過去事實相反的假設可用倒裝 Had it not been for + N（＝ If it had not been for…），主要子句用 would have + p.p.；But for + N 為較正式的同義說法。「恐怕」可用 in all likelihood 或 probably 表推測；antiquity 指「古代（尤指古希臘羅馬時期）」。", "topic": "preserving knowledge", "level": "C2"}, {"id": "T258", "zh": "真正的包容，不是對彼此的差異視而不見，而是承認這些不同，並且仍然願意坐下來好好對話。", "en": "True tolerance is not a matter of turning a blind eye to our differences but of acknowledging them while remaining willing to sit down and talk.", "alt": ["Genuine inclusiveness does not mean pretending our differences do not exist; it means recognizing them and still being prepared to engage in real dialogue."], "keys": [{"en": "is not a matter of", "zh": "不在於……"}, {"en": "turning a blind eye to", "zh": "對……視而不見"}, {"en": "acknowledging", "zh": "承認"}, {"en": "remaining willing to", "zh": "仍然願意"}, {"en": "engage in", "zh": "參與；進行"}], "point": "be not a matter of A but of B「不在於 A，而在於 B」，A、B 皆為動名詞片語；turn a blind eye to sth 為慣用語，意為「對……視而不見、假裝沒看到」；while remaining… 為連接詞後接分詞，表「同時仍……」；engage in dialogue 意為「進行對話」。", "topic": "diversity and dialogue", "level": "C2"}, {"id": "T259", "zh": "貝多芬晚年雖然幾乎完全失聰，卻仍創作出了他一生中最具開創性的一些作品，第九號交響曲便是其中之一。", "en": "Though almost completely deaf in his later years, Beethoven nevertheless composed some of the most groundbreaking works of his career, the Ninth Symphony among them.", "alt": ["Almost totally deaf as he was in his final years, Beethoven still went on to write some of his most pioneering music, including the Ninth Symphony."], "keys": [{"en": "though almost completely deaf", "zh": "雖然幾乎完全失聰"}, {"en": "groundbreaking", "zh": "開創性的"}, {"en": "among them", "zh": "（是）其中之一"}, {"en": "deaf as he was", "zh": "儘管他失聰（讓步倒裝）"}, {"en": "went on to", "zh": "後來還（完成……）"}], "point": "讓步子句可省略主詞與 be 動詞：Though (he was) almost completely deaf…；也可用讓步倒裝 Adj. + as + S + be（Almost totally deaf as he was ＝ Though he was almost totally deaf）。句尾 the Ninth Symphony among them 為獨立結構，補充說明「第九號交響曲即為其中之一」；groundbreaking 與 pioneering 皆表「開創性的」。", "topic": "music history", "level": "C2"}, {"id": "T260", "zh": "人工智慧越能以假亂真地模仿人類的語言，我們就越需要學會分辨哪些內容值得信任。", "en": "The more convincingly artificial intelligence can mimic human language, the more we need to learn to tell which content deserves our trust.", "alt": ["The better AI becomes at passing itself off as human in its use of language, the more essential it is for us to learn to distinguish trustworthy content from the rest."], "keys": [{"en": "the more convincingly", "zh": "越是逼真地"}, {"en": "mimic", "zh": "模仿"}, {"en": "passing itself off as", "zh": "冒充；以假亂真"}, {"en": "deserves our trust", "zh": "值得我們信任"}, {"en": "distinguish", "zh": "分辨"}], "point": "「越……就越……」用 the + 比較級…, the + 比較級…，前半句的副詞 convincingly 須隨 the more 一起移到句首；「以假亂真」可譯為 convincingly mimic 或 pass oneself off as…（冒充）；tell / distinguish A from B 意為「分辨 A 與 B」，tell which… 後接名詞子句。", "topic": "artificial intelligence", "level": "C2"}, {"id": "T261", "zh": "人往往要等到失去了某樣東西，才明白它曾經有多珍貴。", "en": "It is often only when we have lost something that we realize how precious it once was.", "alt": ["Only after we have lost something do we usually come to appreciate how precious it was.", "We often fail to realize how much something means to us until it is gone."], "keys": [{"en": "it is often only when", "zh": "往往要等到……才"}, {"en": "only after", "zh": "直到……之後才"}, {"en": "come to appreciate", "zh": "漸漸體會到"}, {"en": "precious", "zh": "珍貴的"}, {"en": "until it is gone", "zh": "直到它不在了"}], "point": "分裂句 It is only when… that…（強調「要等到……的時候」）；Only + 副詞子句置於句首時，主要子句須倒裝（do we come to…）；come to V 表「逐漸開始（理解、喜歡等）」；not…until… 亦可表「直到……才」，fail to V 在此等於 not。", "topic": "everyday reflections", "level": "C2"}, {"id": "T262", "zh": "我們今晚看到的某些星光，早在數百甚至數千年前就已離開了它的恆星；換句話說，我們仰望的其實是過去的天空。", "en": "Some of the starlight we see tonight left its star hundreds or even thousands of years ago; in other words, what we are gazing at is, in effect, the sky of the past.", "alt": ["Part of the starlight reaching our eyes tonight set out from its source centuries or even millennia ago, which means that when we look up, we are really looking into the past."], "keys": [{"en": "starlight", "zh": "星光"}, {"en": "in other words", "zh": "換句話說"}, {"en": "gazing at", "zh": "凝視；仰望"}, {"en": "in effect", "zh": "實際上；實質上"}, {"en": "millennia", "zh": "數千年（millennium 的複數）"}], "point": "「換句話說」用 in other words；what we are gazing at 為名詞子句作主詞（「我們所仰望的」）；in effect 意為「實際上、實質上」，作插入語；millennium（千年）的複數為 millennia；set out from 表「從……出發」。", "topic": "astronomy", "level": "C2"}, {"id": "T263", "zh": "打折促銷之所以讓人難以抗拒，部分原因在於它製造出一種「現在不買就吃虧」的錯覺。", "en": "Part of the reason sales promotions are so hard to resist is that they create the illusion that not buying now would mean losing out.", "alt": ["Discount promotions prove difficult to resist partly because they foster the illusion that failing to buy immediately amounts to a loss."], "keys": [{"en": "part of the reason", "zh": "部分原因"}, {"en": "hard to resist", "zh": "難以抗拒"}, {"en": "illusion", "zh": "錯覺"}, {"en": "losing out", "zh": "吃虧；錯失好處"}, {"en": "amounts to", "zh": "等同於"}], "point": "「之所以……，部分原因在於……」可用 Part of the reason (why)… is that…；create / foster the illusion that… 中的 that 子句為同位語，說明錯覺的內容；lose out 意為「吃虧、錯失好處」；amount to 意為「等於、相當於」；prove + adj. 表「結果證明是……」。", "topic": "consumer psychology", "level": "C2"}, {"id": "T264", "zh": "快時尚讓人能以低廉的價格追逐潮流，但其背後的環境代價，往往是由下一代來承擔。", "en": "Fast fashion allows people to keep up with trends at low prices, but its environmental cost is often borne by the next generation.", "alt": ["Fast fashion lets consumers chase the latest trends cheaply, yet the environmental toll it takes is often left for the next generation to pay."], "keys": [{"en": "fast fashion", "zh": "快時尚"}, {"en": "keep up with", "zh": "跟上"}, {"en": "environmental cost", "zh": "環境代價"}, {"en": "borne by", "zh": "由……承擔"}, {"en": "toll", "zh": "代價；損害"}], "point": "bear（承擔）的過去分詞為 borne，be borne by… 表「由……承擔」；the toll (that) it takes 源自 take a toll (on…)「造成損害、讓……付出代價」；yet 作對等連接詞，表轉折；leave sth for sb to V 意為「留給某人去……」。", "topic": "sustainable fashion", "level": "C2"}, {"id": "T265", "zh": "與其一味追求標準答案，不如培養提出好問題的能力，因為後者才是一切探索的起點。", "en": "Rather than single-mindedly chasing the right answer, we would do better to cultivate the ability to ask good questions, for it is the latter that marks the starting point of all inquiry.", "alt": ["Instead of fixating on model answers, we would be wiser to develop the ability to ask good questions, since that is where all exploration begins."], "keys": [{"en": "rather than", "zh": "與其……"}, {"en": "would do better to", "zh": "不如……；最好……"}, {"en": "cultivate", "zh": "培養"}, {"en": "the latter", "zh": "後者"}, {"en": "inquiry", "zh": "探究；探索"}], "point": "「與其 A，不如 B」可用 Rather than A, S would do better to B；連接詞 for 表「因為」，語氣正式，只能置於句中；it is the latter that… 為強調句，the former / the latter 分別指「前者／後者」；single-mindedly 意為「一心一意地、一味地」，fixate on 意為「執著於」。", "topic": "education", "level": "C2"}, {"id": "T266", "zh": "印刷術的普及不僅讓知識不再為少數人所壟斷，也在無形中改變了人們思考與辯論的方式。", "en": "Not only did the spread of printing break the monopoly that a privileged few had held over knowledge, but it also subtly transformed the way people thought and argued.", "alt": ["The spread of printing not only ended a small elite's monopoly on knowledge but also quietly reshaped how people thought and debated."], "keys": [{"en": "not only did", "zh": "不僅（倒裝）"}, {"en": "monopoly", "zh": "壟斷"}, {"en": "privileged few", "zh": "少數特權者"}, {"en": "subtly", "zh": "在無形中；不知不覺地"}, {"en": "reshaped", "zh": "重塑"}], "point": "Not only 置於句首時，其後子句須倒裝（Not only did the spread of printing break…），後半句用 but (it) also；monopoly on / over sth 表「對……的壟斷」；the privileged few 指「少數享有特權的人」；「在無形中」可譯為 subtly 或 quietly。", "topic": "history of printing", "level": "C2"}, {"id": "T267", "zh": "好的主管在給予批評時會就事論事，而不是針對個人，好讓部屬在被指正之後仍能保有自尊。", "en": "When giving criticism, a good manager addresses the issue rather than the person, so that staff can keep their self-respect even after being corrected.", "alt": ["A good supervisor keeps criticism focused on the problem, not the individual, allowing team members to retain their dignity even when they have been told they got something wrong."], "keys": [{"en": "addresses the issue", "zh": "就事論事；針對問題本身"}, {"en": "rather than the person", "zh": "而不是針對個人"}, {"en": "self-respect", "zh": "自尊"}, {"en": "retain their dignity", "zh": "保有尊嚴"}, {"en": "being corrected", "zh": "被指正"}], "point": "「就事論事，不針對個人」可譯為 address the issue rather than the person，或 keep criticism focused on the problem, not the individual；so that 引導目的子句；allowing… 為分詞構句，表前述做法帶來的結果；even after being corrected 中的 being corrected 為被動式動名詞。", "topic": "workplace communication", "level": "C2"}, {"id": "T268", "zh": "資訊量龐大到令人應接不暇，以致我們常把「知道得多」誤以為「理解得深」。", "en": "So overwhelming is the sheer volume of information that we often mistake knowing a lot for understanding deeply.", "alt": ["The flood of information is so overwhelming that we frequently confuse knowing a great deal with understanding deeply."], "keys": [{"en": "so overwhelming is", "zh": "如此令人應接不暇（倒裝）"}, {"en": "sheer volume", "zh": "龐大的數量"}, {"en": "mistake", "zh": "誤以為；誤認"}, {"en": "flood of information", "zh": "資訊洪流"}, {"en": "confuse", "zh": "混淆"}], "point": "So + adj. + be + S + that… 為 so…that… 的倒裝句型，強調程度（＝ The sheer volume of information is so overwhelming that…）；sheer 在此強調數量之「龐大」；mistake A for B 與 confuse A with B 皆表「把 A 誤認為 B」，A、B 為對等的動名詞。", "topic": "information overload", "level": "C2"}, {"id": "T269", "zh": "濕地長久以來被視為無用的荒地，直到近幾十年，人們才逐漸認識到它在淨化水質與防洪上不可或缺的角色。", "en": "Long dismissed as useless wasteland, wetlands have only in recent decades come to be recognized for the indispensable role they play in purifying water and preventing floods.", "alt": ["For a long time wetlands were written off as worthless wasteland; it is only in the past few decades that people have begun to appreciate how vital they are for filtering water and controlling floods."], "keys": [{"en": "dismissed as", "zh": "被貶為；被看輕為"}, {"en": "wasteland", "zh": "荒地"}, {"en": "come to be recognized", "zh": "逐漸被認識到"}, {"en": "indispensable", "zh": "不可或缺的"}, {"en": "written off as", "zh": "被認定為（沒有價值的）"}], "point": "句首的過去分詞片語 Long dismissed as… 表被動，交代背景（＝ Wetlands, which were long dismissed as…, have…）；come to be + p.p. 表「逐漸被……」；dismiss / write off A as B 意為「把 A 看輕為 B」；play a role in + V-ing 表「在……中扮演角色」；it is only in… that… 為強調句。", "topic": "wetland conservation", "level": "C2"}, {"id": "T270", "zh": "偏鄉醫師短缺的問題並非一朝一夕形成的，要解決它，也絕不能只靠短期的補助。", "en": "The shortage of doctors in remote areas did not arise overnight, and it can by no means be solved with short-term subsidies alone.", "alt": ["The lack of physicians in rural communities did not develop overnight, nor can it be fixed simply by handing out short-term subsidies."], "keys": [{"en": "remote areas", "zh": "偏鄉；偏遠地區"}, {"en": "overnight", "zh": "一朝一夕；一夜之間"}, {"en": "by no means", "zh": "絕不"}, {"en": "subsidies", "zh": "補助"}, {"en": "nor can it", "zh": "也不能（倒裝）"}], "point": "「並非一朝一夕」可譯為 did not arise / develop overnight；by no means 意為「絕不」；alone 置於名詞後表「僅僅、單靠」；前一子句為否定時，可用 nor + 助動詞 + 主詞 的倒裝表「也不」（nor can it be fixed…）。", "topic": "rural healthcare", "level": "C2"}, {"id": "T271", "zh": "抗生素的濫用使細菌產生了抗藥性；若不加以節制，一些原本很容易治癒的感染，將來可能再度致命。", "en": "The misuse of antibiotics has enabled bacteria to develop resistance, and unless it is curbed, some infections that were once easily cured could become deadly again.", "alt": ["Antibiotic overuse has allowed bacteria to become resistant; left unchecked, it may one day turn some once easily treatable infections back into killers."], "keys": [{"en": "misuse", "zh": "濫用"}, {"en": "develop resistance", "zh": "產生抗藥性"}, {"en": "curbed", "zh": "受到抑制（curb 的過去分詞）"}, {"en": "left unchecked", "zh": "若不加以節制"}, {"en": "deadly", "zh": "致命的"}], "point": "unless（＝ if…not）引導條件子句，「若不加以節制」可譯為 unless it is curbed，或用分詞構句 left unchecked（＝ if it is left unchecked）；curb 意為「抑制、控制」；once 在此作副詞，意為「曾經、原本」；develop resistance 意為「產生抗藥性」。", "topic": "public health", "level": "C2"}, {"id": "T272", "zh": "老建築的價值不僅在於它的外觀，更在於它所承載的集體記憶；一旦拆除，便再也無法挽回。", "en": "The value of an old building lies not merely in its appearance but in the collective memory it embodies; once it has been torn down, that memory is lost beyond recovery.", "alt": ["What makes old buildings valuable is not just how they look but the collective memories they carry, and once they are demolished, they are gone for good."], "keys": [{"en": "lies not merely in", "zh": "不僅在於"}, {"en": "collective memory", "zh": "集體記憶"}, {"en": "embodies", "zh": "承載；體現"}, {"en": "torn down", "zh": "拆除"}, {"en": "beyond recovery", "zh": "無法挽回"}], "point": "lie in sth 意為「在於」，not merely A but (also) B 表「不僅 A，更是 B」；embody 意為「體現、承載」；tear down（三態 tear-tore-torn）與 demolish 皆表「拆除」；beyond recovery 意為「無法挽回」，for good 意為「永遠地」。", "topic": "heritage preservation", "level": "C2"}, {"id": "T273", "zh": "我們總以為自己還有很多時間，於是把真正重要的事一拖再拖，直到某天才驚覺為時已晚。", "en": "We always assume we have plenty of time, so we keep putting off what really matters until one day we wake up to the fact that it is too late.", "alt": ["Assuming that time is on our side, we put off the things that truly matter again and again, only to realize one day that it is too late."], "keys": [{"en": "putting off", "zh": "拖延"}, {"en": "what really matters", "zh": "真正重要的事"}, {"en": "wake up to the fact", "zh": "猛然意識到"}, {"en": "only to realize", "zh": "結果卻（驚覺）"}, {"en": "time is on our side", "zh": "時間還很充裕；時間站在我們這邊"}], "point": "put off + N / V-ing 意為「拖延」，keep + V-ing 表「一再」；wake up to the fact that… 意為「猛然意識到……」；only to V 表出乎意料（多為不好）的結果；time is on one's side 表「時間充裕、時間對某人有利」；what really matters 為名詞子句，意為「真正重要的事」。", "topic": "procrastination", "level": "C2"}, {"id": "T274", "zh": "網際網路最初是為了讓研究機構彼此分享資源而設計的，當時恐怕沒有幾個人料想得到，它日後會徹底改變人類的生活方式。", "en": "The Internet was originally designed to let research institutions share resources with one another, and few at the time could have foreseen that it would go on to transform the way humans live.", "alt": ["Little did anyone imagine, when the Internet was first developed so that research institutions could share resources, that it would one day revolutionize the way people live."], "keys": [{"en": "originally designed", "zh": "最初是為了……而設計"}, {"en": "could have foreseen", "zh": "（當時）能預料到"}, {"en": "go on to", "zh": "後來（進而）……"}, {"en": "little did anyone imagine", "zh": "幾乎沒有人料想得到（倒裝）"}, {"en": "revolutionize", "zh": "徹底改變"}], "point": "could have + p.p. 表對過去可能性的推測，few… could have foreseen 即「當時恐怕沒幾個人預料得到」；go on to V 表「接著、後來（做另一件事）」；否定副詞 Little 置於句首須倒裝（Little did anyone imagine…），表「完全沒料到」；revolutionize 意為「徹底改變、帶來革命性變化」。", "topic": "internet history", "level": "C2"}, {"id": "T275", "zh": "運動家精神的可貴之處在於，即使勝負已成定局，選手仍然全力以赴，並對對手表示尊重。", "en": "What makes sportsmanship so admirable is that athletes continue to give their all and show respect for their opponents even when the outcome is a foregone conclusion.", "alt": ["The beauty of sportsmanship lies in competitors still giving their utmost and treating their rivals with respect, even when the result is no longer in doubt."], "keys": [{"en": "sportsmanship", "zh": "運動家精神"}, {"en": "give their all", "zh": "全力以赴"}, {"en": "show respect for", "zh": "對……表示尊重"}, {"en": "foregone conclusion", "zh": "已成定局的事"}, {"en": "giving their utmost", "zh": "竭盡全力"}], "point": "What makes… so admirable is that… 為名詞子句作主詞的句型，表「……的可貴之處在於」；give one's all 與 do one's utmost 皆表「全力以赴」；a foregone conclusion 意為「必然的結果、已成定局」；lie in + 動名詞（前面的 competitors 為其意義上的主詞）表「在於……」。", "topic": "sports ethics", "level": "C2"}, {"id": "T276", "zh": "謝謝你邀請我參加這個週末的聚會，可惜我已經另有安排，下次有機會一定參加。", "en": "Thank you for inviting me to the party this weekend. I'm afraid I have a prior engagement, but I'll definitely come next time I get the chance.", "alt": ["Thanks so much for the invitation to this weekend's party. Unfortunately, I've already made other plans, but I'll be sure to join you next time.", "Thank you for asking me to this weekend's party. Sadly, I already have plans, but I'll certainly come next time I have the chance."], "keys": [{"en": "I'm afraid", "zh": "恐怕；很抱歉（委婉表達遺憾）"}, {"en": "prior engagement", "zh": "另有安排；先前的約定"}, {"en": "made other plans", "zh": "另有安排（另有計畫）"}, {"en": "definitely", "zh": "一定"}, {"en": "next time I get the chance", "zh": "下次有機會"}], "point": "婉拒邀請時，宜先致謝（Thank you for + V-ing），再以 I'm afraid… 委婉說明無法出席，最後表達下次參加的意願，語氣較為得體。「另有安排」可譯為 have a prior engagement（較正式；prior 已含「事先」之意，不必再加 already）或 have already made other plans。「下次有機會一定參加」可譯為 I'll definitely come next time I get the chance 或 I'll be sure to join you next time。", "topic": "declining invitations", "level": "C1"}, {"id": "T277", "zh": "很少有人意識到，長期睡眠不足不僅會影響專注力，還可能削弱身體的免疫力。", "en": "Few people realize that chronic sleep deprivation not only impairs concentration but may also weaken the immune system.", "alt": ["Rarely do people realize that a chronic lack of sleep can not only affect their concentration but also weaken the body's immunity."], "keys": [{"en": "Few people realize", "zh": "很少有人意識到"}, {"en": "chronic", "zh": "長期的；慢性的"}, {"en": "sleep deprivation", "zh": "睡眠不足"}, {"en": "impairs", "zh": "損害；削弱"}, {"en": "immune system", "zh": "免疫系統；免疫力"}], "point": "few 表「很少、幾乎沒有」，帶有否定意味，Few people realize… 簡潔自然；也可將否定副詞 Rarely 置於句首，其後子句須倒裝（Rarely do people realize…）。not only A but (also) B 中，A 與 B 須為對等結構（impairs… 與 may also weaken… 皆為動詞片語）。chronic 原指「慢性的」，在此表「長期的」；sleep deprivation 為「睡眠不足」的正式說法。", "topic": "sleep and health", "level": "C1"}, {"id": "T278", "zh": "如果弗萊明在 1928 年沒有注意到培養皿裡的那團黴菌，今天許多感染或許仍然很難治療。", "en": "If Alexander Fleming had not noticed the mold in his petri dish in 1928, many infections might still be difficult to treat today.", "alt": ["Had Fleming not noticed the mold growing in his petri dish in 1928, many infections might still be hard to treat today."], "keys": [{"en": "had not noticed", "zh": "沒有注意到（與過去事實相反）"}, {"en": "mold", "zh": "黴菌"}, {"en": "petri dish", "zh": "培養皿"}, {"en": "infections", "zh": "感染"}, {"en": "might still be", "zh": "或許仍然（會）"}], "point": "混合假設語氣：if 子句與「過去事實」相反，用 had + p.p.（had not noticed）；主要子句與「現在事實」相反，用 might + 原形動詞（might still be），表示過去的事對現在造成的影響。省略 if 時，可將 had 移至句首並倒裝（Had Fleming not noticed…）。mold 為美式拼法，英式拼法為 mould；弗萊明由此發現了青黴素（penicillin）。", "topic": "medical history", "level": "C1"}, {"id": "T279", "zh": "直到十九世紀末，台灣才在巡撫劉銘傳的主持下，興建了第一條鐵路。", "en": "It was not until the late nineteenth century that Taiwan's first railway was built under the direction of Governor Liu Ming-chuan.", "alt": ["Not until the late nineteenth century was Taiwan's first railway built, under the supervision of Governor Liu Ming-chuan."], "keys": [{"en": "It was not until", "zh": "直到……才"}, {"en": "late nineteenth century", "zh": "十九世紀末"}, {"en": "under the direction of", "zh": "在……的主持下"}, {"en": "governor", "zh": "巡撫"}, {"en": "railway", "zh": "鐵路"}], "point": "「直到……才……」可用強調句 It was not until + 時間 + that + S + V；也可將 Not until… 置於句首，此時主要子句須倒裝（was Taiwan's first railway built）。under the direction / supervision of 表「在……的主持／監督下」。「十九世紀末」譯為 the late nineteenth century。這條清代興建的鐵路北起基隆，南至新竹。", "topic": "Taiwanese history", "level": "C1"}, {"id": "T280", "zh": "蜜蜂在採集花蜜的同時，也替許多農作物授粉，因此在維持糧食生產上扮演不可或缺的角色。", "en": "While collecting nectar, bees also pollinate many crops, thus playing an indispensable role in sustaining food production.", "alt": ["As they gather nectar, bees also pollinate many crops and therefore play an essential role in maintaining food production."], "keys": [{"en": "nectar", "zh": "花蜜"}, {"en": "pollinate", "zh": "授粉"}, {"en": "crops", "zh": "農作物"}, {"en": "indispensable role", "zh": "不可或缺的角色"}, {"en": "food production", "zh": "糧食生產"}], "point": "While collecting… 為分詞構句，由 While bees are collecting… 省略主詞與 be 動詞而來，前提是前後主詞相同；thus playing… 為表示結果的分詞構句。play a(n) + adj. + role in + N / V-ing 表「在……中扮演……的角色」，in 為介系詞，故其後的 sustain 須改為動名詞 sustaining。", "topic": "pollinators", "level": "C1"}, {"id": "T281", "zh": "「不好意思打擾一下，我知道您很忙，不過不知道您能不能在週五前幫我看一下這份報告？」「沒問題，不過我可能要到週四下午才有空。」", "en": "\"Sorry to bother you. I know you're busy, but I was wondering if you could take a look at this report before Friday.\" \"Sure, although I might not be free until Thursday afternoon.\"", "alt": ["\"Excuse me, I realize you have a lot on your plate, but would you mind looking over this report before Friday?\" \"No problem, but I probably won't have time until Thursday afternoon.\""], "keys": [{"en": "Sorry to bother you", "zh": "不好意思打擾一下"}, {"en": "I was wondering if", "zh": "不知道能不能（委婉請求）"}, {"en": "take a look at", "zh": "看一下"}, {"en": "would you mind", "zh": "您介意……嗎"}, {"en": "not be free until", "zh": "直到……才有空"}], "point": "I was wondering if you could… 以過去進行式提出請求，比 Can you…? 委婉客氣，適合對上司或長輩使用；would you mind + V-ing 亦為禮貌的請求句型。have a lot on one's plate 為慣用語，意為「手邊的事情很多」。not… until… 表「直到……才……」，回答時先答應，再以 although 補充說明可能的限制，可使語氣更為周到。", "topic": "workplace requests", "level": "C1"}, {"id": "T282", "zh": "要不是有紅樹林保護海岸，這個漁村在颱風季節所遭受的損失恐怕會嚴重得多。", "en": "Were it not for the mangroves protecting the coast, this fishing village would probably suffer far greater losses during the typhoon season.", "alt": ["If it were not for the mangrove forests that shield the coastline, this fishing village would likely suffer much heavier losses in typhoon season."], "keys": [{"en": "Were it not for", "zh": "要不是有"}, {"en": "mangroves", "zh": "紅樹林"}, {"en": "fishing village", "zh": "漁村"}, {"en": "suffer", "zh": "遭受"}, {"en": "typhoon season", "zh": "颱風季節"}], "point": "Were it not for + N 是 If it were not for + N 省略 if 後的倒裝形式，表示與現在事實相反的假設，主要子句用 would + 原形動詞。protecting the coast 為現在分詞片語，修飾 mangroves。比較級前可加 far、much 加強語氣（far greater losses）。紅樹林能減緩海浪與暴潮的衝擊，並降低海岸侵蝕。", "topic": "coastal protection", "level": "C1"}, {"id": "T283", "zh": "在家遠距工作了三年之後，他發現自己已經很難再適應每天通勤兩小時的生活。", "en": "Having worked remotely for three years, he found it difficult to readjust to a two-hour daily commute.", "alt": ["After three years of working from home, he found it hard to get used to commuting two hours a day again."], "keys": [{"en": "Having worked", "zh": "在……之後（完成式分詞構句）"}, {"en": "remotely", "zh": "遠距地"}, {"en": "readjust to", "zh": "重新適應"}, {"en": "get used to", "zh": "適應；習慣"}, {"en": "commute", "zh": "通勤"}], "point": "Having + p.p. 為完成式分詞構句，表示該動作發生在主要子句動作（found）之前，且前後主詞相同。find it + adj. + to V 中，it 為虛受詞，真正的受詞是 to readjust…。readjust to 與 get used to 中的 to 皆為介系詞，後接名詞或動名詞（commuting）。two-hour 為複合形容詞，hour 不加 s。", "topic": "remote work", "level": "C1"}, {"id": "T284", "zh": "這款翻譯軟體的準確度提升得如此之快，以至於連一些專業譯者也開始用它來處理初稿。", "en": "So rapidly has the accuracy of this translation software improved that even some professional translators have started using it to handle first drafts.", "alt": ["The accuracy of this translation software has improved so quickly that even some professional translators have begun using it to produce first drafts."], "keys": [{"en": "So rapidly has", "zh": "如此快速地（倒裝）"}, {"en": "accuracy", "zh": "準確度"}, {"en": "translation software", "zh": "翻譯軟體"}, {"en": "professional translators", "zh": "專業譯者"}, {"en": "first drafts", "zh": "初稿"}], "point": "so + adv. + that… 表「如此……以至於……」；將 So rapidly 移至句首時，其後須倒裝，把助動詞 has 置於主詞之前（So rapidly has the accuracy… improved），語氣較為正式。software 為不可數名詞，不加 s；「處理初稿」可譯為 handle / produce first drafts。", "topic": "machine translation", "level": "C1"}, {"id": "T285", "zh": "「我已經咳嗽一個星期了，會不會是流感？」「很難說，也可能是其他病毒引起的；保險起見，你最好還是去給醫生看一下。」", "en": "\"I've been coughing for a week now. Could it be the flu?\" \"It's hard to say. It could also be caused by some other virus. To be on the safe side, you'd better have a doctor take a look.\"", "alt": ["\"I've had this cough for a week. Do you think it might be the flu?\" \"Hard to tell. Some other virus could also be causing it, so just to be safe, you should go and see a doctor.\""], "keys": [{"en": "Could it be", "zh": "會不會是"}, {"en": "It's hard to say", "zh": "很難說"}, {"en": "To be on the safe side", "zh": "保險起見"}, {"en": "you'd better", "zh": "你最好"}, {"en": "have a doctor take a look", "zh": "請醫生看一下"}], "point": "Could it be…? 以 could 表示對現在情況的推測，語氣帶有不確定；could also be caused by… 表「也可能是……引起的」。to be on the safe side 為慣用語，意為「保險起見」，也可說 just to be safe。had better（'d better）+ 原形動詞表「最好……」，帶有勸告意味；have + 人 + 原形動詞為使役用法，表「請某人做某事」。", "topic": "seeing a doctor", "level": "C1"}, {"id": "T286", "zh": "這部電影最打動我的，不是它華麗的特效，而是演員們細膩而真實的演出。", "en": "What moved me most about this film was not its spectacular special effects but the actors' subtle and authentic performances.", "alt": ["It was not the film's dazzling special effects but the actors' nuanced, genuine performances that touched me most."], "keys": [{"en": "What moved me most", "zh": "最打動我的"}, {"en": "special effects", "zh": "特效"}, {"en": "subtle", "zh": "細膩的"}, {"en": "authentic", "zh": "真實的"}, {"en": "nuanced", "zh": "細膩的；層次豐富的"}], "point": "What 引導的名詞子句作主詞（What moved me most…），形成「What… was…」的分裂句，用以強調後面的內容；not A but B 中，A 與 B 須為對等的名詞片語。也可改用強調句 It was not A but B that…。move 與 touch 皆可表「打動、使感動」；subtle 與 nuanced 均可形容演出「細膩」。", "topic": "film appreciation", "level": "C1"}, {"id": "T287", "zh": "既然每年都有大量即期食品被丟棄，有些超市便開始把這些食品捐給慈善團體，而不是直接銷毀。", "en": "Given that large quantities of food nearing its expiration date are thrown away every year, some supermarkets have begun donating such food to charities instead of simply destroying it.", "alt": ["Since huge amounts of food close to its expiry date are discarded every year, some supermarkets have started giving such food to charitable organizations rather than just destroying it."], "keys": [{"en": "Given that", "zh": "既然；考慮到"}, {"en": "nearing its expiration date", "zh": "即期（接近有效期限）"}, {"en": "thrown away", "zh": "丟棄"}, {"en": "charities", "zh": "慈善團體"}, {"en": "instead of", "zh": "而不是"}], "point": "Given that… 為較正式的連接詞，表「考慮到、既然」，與 since 相近。nearing its expiration date 為現在分詞片語，修飾 food，可用來表達「即期」；instead of 為介系詞，後接動名詞（destroying），表「而不是……」；rather than 在此亦接動名詞，與前面的 giving 對等。「有效期限」美式英語多說 expiration date，英式英語常說 expiry date。", "topic": "food waste", "level": "C1"}, {"id": "T288", "zh": "那位歌手才剛宣布要舉辦告別演唱會，門票就在幾分鐘內被搶購一空。", "en": "No sooner had the singer announced a farewell concert than the tickets sold out within minutes.", "alt": ["Hardly had the singer announced a farewell concert when all the tickets were snapped up in a matter of minutes."], "keys": [{"en": "No sooner had", "zh": "一……就……"}, {"en": "farewell concert", "zh": "告別演唱會"}, {"en": "sold out", "zh": "（門票）售完；被搶購一空"}, {"en": "snapped up", "zh": "搶購一空"}, {"en": "in a matter of minutes", "zh": "在短短幾分鐘內"}], "point": "No sooner had + S + p.p.… than + S + 過去式，表「一……就……」；否定副詞 No sooner 置於句首，其後子句須倒裝。Hardly / Scarcely had… when / before… 用法相同，但須搭配 when 或 before，不可用 than。sell out 表「售完」，be snapped up 表「被搶購一空」；within minutes 與 in a matter of minutes 皆表「在幾分鐘之內」。", "topic": "concerts", "level": "C1"}, {"id": "T289", "zh": "萬一颱風在比賽當天登陸，主辦單位將延期舉行，並另行通知參賽者。", "en": "Should the typhoon make landfall on the day of the competition, the organizers will postpone the event and notify participants of further arrangements.", "alt": ["If the typhoon makes landfall on the day of the competition, the event will be postponed, and participants will be notified separately."], "keys": [{"en": "Should the typhoon", "zh": "萬一颱風（省略 if 的倒裝）"}, {"en": "landfall", "zh": "登陸"}, {"en": "postpone", "zh": "延期"}, {"en": "organizers", "zh": "主辦單位"}, {"en": "notify", "zh": "通知"}], "point": "Should + S + 原形動詞是 If + S + should + V 省略 if 後的倒裝形式，表示「萬一」，指未來發生可能性較低的情況，主要子句可用 will 或祈使句。make landfall 為氣象新聞常見的搭配，意為「（颱風）登陸」；「另行通知」可譯為 notify sb of further arrangements 或 notify sb separately。", "topic": "typhoons and events", "level": "C1"}, {"id": "T290", "zh": "羅塞塔石碑以三種文字刻著同一份詔令，正因如此，學者才得以破解古埃及的象形文字。", "en": "The Rosetta Stone is inscribed with the same decree in three different scripts, and it was precisely this that enabled scholars to decipher ancient Egyptian hieroglyphs.", "alt": ["It was precisely because the Rosetta Stone bears the same decree in three scripts that scholars were able to decipher ancient Egyptian hieroglyphs."], "keys": [{"en": "inscribed with", "zh": "刻有"}, {"en": "decree", "zh": "詔令"}, {"en": "scripts", "zh": "文字（書寫系統）"}, {"en": "decipher", "zh": "破解；解讀"}, {"en": "hieroglyphs", "zh": "象形文字"}], "point": "be inscribed with 表「刻有……」；it was precisely this that… 為強調句，precisely 加強「正是」的語氣；enable + O + to V 表「使……能夠……」。指文字系統時用 script，不宜譯為 word 或 language。石碑上的三種文字分別是古埃及象形文字、世俗體（Demotic）與古希臘文，其中前兩種記錄的都是古埃及語，因此只有兩種語言、卻有三種文字。", "topic": "archaeology", "level": "C1"}, {"id": "T291", "zh": "不管對方開出的條件聽起來多麼誘人，在簽約之前，你都應該仔細閱讀每一項條款。", "en": "However attractive the other party's terms may sound, you should read every clause carefully before signing the contract.", "alt": ["No matter how tempting the other side's offer sounds, you ought to read each clause carefully before you sign the contract."], "keys": [{"en": "However attractive", "zh": "不管多麼誘人"}, {"en": "terms", "zh": "條件"}, {"en": "clause", "zh": "條款"}, {"en": "before signing", "zh": "在簽署……之前"}, {"en": "tempting", "zh": "誘人的"}], "point": "However + adj. + S + may + V 表讓步，意為「不論多麼……」，與 No matter how + adj. + S + V 同義，語氣較正式。before signing 中的 before 為介系詞，後接動名詞；也可寫成 before you sign。terms 指合約中的「條件」，clause 則指個別的「條款」。", "topic": "contracts", "level": "C1"}, {"id": "T292", "zh": "和傳統燃油車不同，電動車行駛時不會排放廢氣，但它對環境的整體影響，仍取決於電力是如何產生的。", "en": "Unlike conventional gasoline-powered cars, electric vehicles produce no exhaust emissions while running, but their overall environmental impact still depends on how the electricity is generated.", "alt": ["Electric vehicles, unlike traditional fuel-powered cars, emit no exhaust fumes on the road; however, their overall impact on the environment still hinges on how their electricity is produced."], "keys": [{"en": "Unlike", "zh": "和……不同"}, {"en": "conventional", "zh": "傳統的"}, {"en": "exhaust", "zh": "廢氣"}, {"en": "overall", "zh": "整體的"}, {"en": "hinges on", "zh": "取決於"}], "point": "Unlike + N 表「與……不同」，比較的對象須屬同類（cars 與 electric vehicles）。while running 是 while they are running 的省略。how 引導名詞子句，作介系詞 on 的受詞，須用直述句語序（how the electricity is generated）；hinge on 與 depend on 同義，常用來強調「關鍵在於、取決於」。", "topic": "electric vehicles", "level": "C1"}, {"id": "T293", "zh": "無障礙設計不只是為了身心障礙者，也讓推著嬰兒車的父母和年長者出入更加方便。", "en": "Barrier-free design is not only intended for people with disabilities; it also makes getting around easier for parents pushing strollers and for older people.", "alt": ["Accessible design benefits not just people with disabilities but also parents with strollers and the elderly, making it easier for them to get around."], "keys": [{"en": "Barrier-free", "zh": "無障礙的"}, {"en": "people with disabilities", "zh": "身心障礙者"}, {"en": "intended for", "zh": "為……而設計"}, {"en": "strollers", "zh": "嬰兒車"}, {"en": "get around", "zh": "到處走動；出入"}], "point": "「身心障礙者」宜譯為 people with disabilities，以人為主體的說法較為尊重。be intended for 表「為……而設計」。makes getting around easier 中，動名詞片語 getting around 為受詞，easier 為受詞補語；亦可用虛受詞 it 寫成 making it easier for them to get around。pushing strollers 為現在分詞片語，修飾 parents；stroller 為美式說法，英式說法為 pushchair。", "topic": "accessible design", "level": "C1"}, {"id": "T294", "zh": "第一次接觸程式設計的時候，我完全沒想到它日後竟會成為我的職業。", "en": "When I first encountered computer programming, little did I know that it would one day become my profession.", "alt": ["Little did I imagine, when I was first introduced to programming, that it would eventually become my career."], "keys": [{"en": "little did I", "zh": "完全沒想到（倒裝）"}, {"en": "first encountered", "zh": "初次接觸"}, {"en": "introduced to", "zh": "（被引導）接觸；認識"}, {"en": "one day", "zh": "日後；有朝一日"}, {"en": "profession", "zh": "職業"}], "point": "否定副詞 little 置於句首或主要子句之首時，其後須倒裝（little did I know / imagine），表「完全沒料到」，語氣比 I had no idea that… 更強烈。從過去的角度描述「日後會」，須用 would（過去未來式）。「接觸」在此指初次認識某個領域，可譯為 first encounter 或 be first introduced to；come across 多指「偶然碰到」，用在此處較不貼切。", "topic": "career paths", "level": "C1"}, {"id": "T295", "zh": "一般認為，適度運動有助於緩解焦慮，因為運動會促使大腦釋放讓人心情愉悅的化學物質。", "en": "Moderate exercise is generally believed to help relieve anxiety, as it prompts the brain to release chemicals that lift people's mood.", "alt": ["It is generally believed that moderate exercise can help ease anxiety because it stimulates the brain to release chemicals that make people feel good."], "keys": [{"en": "generally believed", "zh": "一般認為"}, {"en": "moderate", "zh": "適度的"}, {"en": "anxiety", "zh": "焦慮"}, {"en": "prompts", "zh": "促使"}, {"en": "release", "zh": "釋放"}], "point": "「一般認為」可用被動報導結構 S + be generally believed to V，或 It is generally believed that + 子句。help (to) V 表「有助於」；prompt / stimulate + O + to V 表「促使……做……」；lift one's mood 為「提振心情」的常見搭配。as 在此為連接詞，意同 because。", "topic": "exercise and mental health", "level": "C1"}, {"id": "T296", "zh": "冬季強勁的東北季風吹過台灣海峽，使台灣西部沿海成為發展離岸風電的理想地點。", "en": "The strong northeast monsoon winds that sweep through the Taiwan Strait in winter make the waters off Taiwan's west coast an ideal site for developing offshore wind power.", "alt": ["Thanks to the powerful northeasterly monsoon blowing through the Taiwan Strait in winter, the waters off Taiwan's west coast are ideally suited to offshore wind development."], "keys": [{"en": "northeast monsoon", "zh": "東北季風"}, {"en": "sweep through", "zh": "吹過；橫掃"}, {"en": "Taiwan Strait", "zh": "台灣海峽"}, {"en": "ideal site", "zh": "理想地點"}, {"en": "offshore wind", "zh": "離岸風電"}], "point": "主詞 The strong… winds 由關係子句 that sweep through… 修飾，主要動詞為 make，句型為 make + O + OC（名詞 an ideal site）。the waters off… 表「……外海的海域」，waters 用複數指特定海域。be ideally suited to 中的 to 為介系詞，後接名詞或動名詞。", "topic": "offshore wind power", "level": "C1"}, {"id": "T297", "zh": "我們早該全面檢討都市的道路設計，讓行人能夠更安全地通行。", "en": "It is high time we thoroughly reviewed the design of our city streets so that pedestrians can walk more safely.", "alt": ["It is about time that we carried out a comprehensive review of urban road design to make it safer for pedestrians to get around."], "keys": [{"en": "It is high time", "zh": "早該"}, {"en": "thoroughly", "zh": "全面地；徹底地"}, {"en": "reviewed", "zh": "檢討；重新檢視"}, {"en": "comprehensive review", "zh": "全面檢討"}, {"en": "pedestrians", "zh": "行人"}], "point": "It is (high / about) time + S + 過去式動詞，表「早該做某事了」；動詞雖用過去式，指的卻是現在應做而尚未做的事，high 可加強語氣。so that + S + can V 表目的。「檢討」在此指「重新檢視」，宜譯為 review，而非 criticize。", "topic": "pedestrian safety", "level": "C1"}, {"id": "T298", "zh": "儘管我很欣賞這位畫家的技巧，我還是覺得他後期的作品少了早期那種率真的情感。", "en": "Much as I admire this painter's technique, I still feel that his later works lack the spontaneous emotion of his early ones.", "alt": ["Although I greatly admire the painter's skill, I still find that his later paintings are missing the genuine, unaffected feeling of his earlier work."], "keys": [{"en": "Much as", "zh": "儘管"}, {"en": "technique", "zh": "技巧"}, {"en": "later works", "zh": "後期作品"}, {"en": "lack", "zh": "缺少"}, {"en": "spontaneous", "zh": "率真的；自然流露的"}], "point": "Much as + S + V 為較正式的讓步用法，意同 Although… very much，常與 admire、like、want 等表示喜好或意願的動詞連用。lack 作及物動詞時直接接受詞，不加 of（lack the spontaneous emotion）。ones 代替前面提過的 works，避免重複。", "topic": "painting", "level": "C1"}, {"id": "T299", "zh": "本行在任何情況下，都不會以簡訊或電話要求您提供密碼或一次性驗證碼。", "en": "Under no circumstances will our bank ask you for your password or one-time verification code by text message or phone call.", "alt": ["Our bank will never, under any circumstances, ask you to provide your password or one-time passcode via text message or over the phone."], "keys": [{"en": "Under no circumstances", "zh": "在任何情況下都不"}, {"en": "ask you for", "zh": "向您索取"}, {"en": "one-time", "zh": "一次性的"}, {"en": "verification code", "zh": "驗證碼"}, {"en": "text message", "zh": "簡訊"}], "point": "否定片語 Under no circumstances 置於句首時，其後須倒裝（will our bank ask），語氣強烈而正式，常見於公告與警示；若不倒裝，則寫成 will never, under any circumstances,…。ask sb for sth 表「向某人索取某物」；「簡訊」可譯為 text message，英式英語也常說 SMS。", "topic": "fraud prevention", "level": "C1"}, {"id": "T300", "zh": "唯有放慢腳步，我們才能真正注意到身邊那些平凡卻美好的小事。", "en": "Only by slowing down can we truly notice the ordinary yet beautiful little things around us.", "alt": ["It is only when we slow down that we can really notice the small, ordinary yet beautiful things around us."], "keys": [{"en": "Only by", "zh": "唯有藉由"}, {"en": "slowing down", "zh": "放慢腳步"}, {"en": "It is only when", "zh": "唯有在……的時候"}, {"en": "ordinary yet beautiful", "zh": "平凡卻美好的"}, {"en": "notice", "zh": "注意到"}], "point": "Only + 副詞片語（by slowing down）置於句首時，主要子句須倒裝（can we truly notice）；by + V-ing 表「藉由……的方式」。也可用強調句 It is only when… that… 表達。yet 在此為對等連接詞，意同 but，用來連接兩個形容詞，語氣較為書面。", "topic": "everyday reflections", "level": "C1"}, {"id": "T301", "zh": "天花在人類歷史上奪走了數以億計的性命，直到 1980 年，世界衛生組織才正式宣布這種疾病已被根除。", "en": "Smallpox claimed hundreds of millions of lives throughout human history, and not until 1980 did the World Health Organization officially declare the disease eradicated.", "alt": ["Smallpox killed hundreds of millions of people over the course of human history; it was not until 1980 that the World Health Organization officially declared that it had been eradicated."], "keys": [{"en": "claimed", "zh": "奪走（性命）"}, {"en": "hundreds of millions", "zh": "數以億計"}, {"en": "not until", "zh": "直到……才"}, {"en": "declare", "zh": "宣布"}, {"en": "eradicated", "zh": "被根除的"}], "point": "「直到……才……」可將 not until… 置於子句開頭，此時主要子句須倒裝為「助動詞 did + 主詞 + 原形動詞」（did the World Health Organization declare）；亦可改用強調句 It was not until… that…，that 之後不倒裝。claim 在此作「奪走（性命）」解，常見搭配為 claim + lives；declare + O + p.p. 表「宣布某事物已……」，eradicate 意為「根除、徹底消滅」。", "topic": "disease eradication", "level": "C1"}, {"id": "T302", "zh": "據估計已有約一萬七千年歷史的拉斯科洞窟壁畫，是在 1940 年被四名青少年偶然發現的。", "en": "The Lascaux cave paintings, which are estimated to be around 17,000 years old, were discovered by chance by four teenagers in 1940.", "alt": ["Estimated to be about 17,000 years old, the paintings in the Lascaux Cave were discovered by accident in 1940 by four teenagers."], "keys": [{"en": "cave paintings", "zh": "洞窟壁畫"}, {"en": "are estimated to be", "zh": "據估計（為）"}, {"en": "years old", "zh": "有……年歷史的"}, {"en": "discovered by chance", "zh": "偶然發現"}, {"en": "by accident", "zh": "偶然地"}], "point": "「據估計……」可用被動報導結構 S + be estimated / thought / believed + to V，也可改為過去分詞片語 Estimated to be… 置於句首修飾主詞。中文「……的拉斯科洞窟壁畫」修飾語很長，英文宜改用非限定關係子句（which are…）或分詞片語處理，避免把長修飾語堆在名詞前面。「被……偶然發現」用被動語態 were discovered by chance / by accident by…。", "topic": "prehistoric art", "level": "C1"}, {"id": "T303", "zh": "要是我昨天有把檔案備份到雲端，現在就不必熬夜把整份報告重寫一遍了。", "en": "If I had backed up the file to the cloud yesterday, I wouldn't have to stay up all night rewriting the entire report now.", "alt": ["Had I backed up the file to the cloud yesterday, I wouldn't need to stay up late rewriting the whole report now."], "keys": [{"en": "backed up", "zh": "備份（back up 的過去分詞）"}, {"en": "the cloud", "zh": "雲端"}, {"en": "stay up", "zh": "熬夜"}, {"en": "rewriting", "zh": "重寫"}], "point": "混合假設語氣：if 子句與過去事實相反，用 had + p.p.（had backed up）；主要子句與現在事實相反，用 would + V（wouldn't have to… now）。正式文體中可省略 if，改為倒裝 Had I backed up…。stay up (all night / late) + V-ing 表「熬夜做某事」；back up 作動詞表「備份」，名詞寫作 backup。", "topic": "data backup", "level": "C1"}, {"id": "T304", "zh": "海水的漲潮與退潮主要是由月球的引力所造成的，太陽的引力則扮演較次要的角色。", "en": "It is mainly the moon's gravitational pull that causes the rise and fall of the tides, while the sun's gravity plays a lesser role.", "alt": ["The ebb and flow of the tides is caused mainly by the moon's gravity, with the sun's gravitational pull playing a secondary role."], "keys": [{"en": "gravitational pull", "zh": "引力"}, {"en": "rise and fall", "zh": "漲落；起伏"}, {"en": "ebb and flow", "zh": "（潮水的）漲退"}, {"en": "plays a lesser role", "zh": "扮演較次要的角色"}, {"en": "secondary role", "zh": "次要的角色"}], "point": "強調句（分裂句）「It is + 被強調部分 + that + 其餘部分」可凸顯造成潮汐的主因 the moon's gravitational pull；while 表對比，意為「而……」。另一譯法句尾用 with + O + V-ing（with the sun's gravitational pull playing…）補充附帶情況。the rise and fall / the ebb and flow of the tides 皆指潮水的漲落。", "topic": "tides", "level": "C1"}, {"id": "T305", "zh": "「這個人事異動的消息，我可以先告訴其他同事嗎？」「我希望你暫時不要說，等公司正式公告之後再說會比較妥當。」", "en": "\"Would it be all right if I told my other colleagues about this personnel change in advance?\" \"I'd rather you didn't for the time being. It would be more appropriate to wait until the company makes an official announcement.\"", "alt": ["\"Is it OK if I let the rest of the team know about the staff change ahead of time?\" \"I'd prefer it if you kept it to yourself for now. It would be better to wait until the company has made an official announcement.\""], "keys": [{"en": "Would it be all right if", "zh": "……可以嗎（委婉請求許可）"}, {"en": "I'd rather you didn't", "zh": "我希望你不要（這麼做）"}, {"en": "for the time being", "zh": "暫時"}, {"en": "appropriate", "zh": "妥當的；適當的"}, {"en": "official announcement", "zh": "正式公告"}], "point": "would rather 後接子句時，子句動詞用過去式表示假設語氣，意為「寧願對方（不要）……」，故說 I'd rather you didn't，比 Don't tell them 委婉得多；I'd prefer it if you + 過去式 亦有相同語氣。Would it be all right if I + 過去式…? 是禮貌地請求許可的說法。for the time being 意為「暫時」；wait until… 的 until 子句以現在式（或現在完成式）代替未來式。", "topic": "workplace confidentiality", "level": "C1"}, {"id": "T306", "zh": "隨著越來越多年輕人移居都市，許多鄉村小學因學生人數不足而面臨被裁併的命運。", "en": "With more and more young people moving to the cities, many rural elementary schools are facing closure or merger due to low enrollment.", "alt": ["As an increasing number of young people move to urban areas, many village elementary schools are at risk of being closed or merged because they have too few students."], "keys": [{"en": "With more and more", "zh": "隨著越來越多"}, {"en": "rural", "zh": "鄉村的"}, {"en": "closure or merger", "zh": "裁併（裁撤或合併）"}, {"en": "enrollment", "zh": "就學（註冊）人數"}, {"en": "an increasing number of", "zh": "越來越多的"}], "point": "「隨著……」可用獨立結構 with + O + V-ing 表示伴隨的背景情況，亦可用 as 引導的副詞子句。「面臨被裁併的命運」可譯為 face closure or merger，或 be at risk of being closed or merged（介系詞 of 之後接被動式動名詞）。enrollment 指「註冊人數、就學人數」，low / falling enrollment（就學人數偏低／下滑）是新聞報導常見的搭配。", "topic": "rural education", "level": "C1"}, {"id": "T307", "zh": "全球暖化的影響在北極最為明顯，那裡的升溫速度遠遠超過全球平均。", "en": "Nowhere are the effects of global warming more evident than in the Arctic, where the rate of warming far exceeds the global average.", "alt": ["The effects of global warming are most evident in the Arctic, which is heating up much more quickly than the world as a whole."], "keys": [{"en": "Nowhere", "zh": "沒有任何地方（否定副詞）"}, {"en": "evident", "zh": "明顯的"}, {"en": "the Arctic", "zh": "北極（地區）"}, {"en": "rate of warming", "zh": "升溫速度"}, {"en": "far exceeds", "zh": "遠遠超過"}], "point": "最高級的意思可用「Nowhere + 比較級 + than」表達：「沒有任何地方比北極更明顯」即「在北極最明顯」；否定副詞 Nowhere 置於句首時須倒裝（are the effects…）。where 引導非限定關係子句，補充說明北極的情況；far 可修飾比較級或動詞 exceed，表「遠遠」。", "topic": "Arctic warming", "level": "C1"}, {"id": "T308", "zh": "很少有一本書能像《小王子》那樣同時打動兒童與成人讀者，難怪它至今已被翻譯成數百種語言。", "en": "Seldom has a book moved children and adults alike as deeply as The Little Prince has, so it is little wonder that it has been translated into hundreds of languages to date.", "alt": ["Few books have touched both young and adult readers the way The Little Prince has, so it is no wonder that it has so far been translated into hundreds of languages."], "keys": [{"en": "Seldom has", "zh": "很少有（否定副詞，句首倒裝）"}, {"en": "alike", "zh": "（兩者）同樣地"}, {"en": "little wonder", "zh": "難怪"}, {"en": "translated into", "zh": "被翻譯成"}, {"en": "to date", "zh": "至今"}], "point": "否定副詞 Seldom 置於句首時，句子須倒裝（Seldom has a book moved…）；也可改用 Few books have… 表達「很少有書……」。A and B alike 表「A 與 B 皆」；「難怪」可譯為 it is little / no wonder that…。「至今已被翻譯成」用現在完成式被動語態 has been translated into，搭配 to date 或 so far。", "topic": "children's literature", "level": "C1"}, {"id": "T309", "zh": "儘管在連續值班將近二十個小時後早已精疲力竭，這群急診室醫護人員仍堅持看完最後一位病人才肯下班。", "en": "Exhausted as they were after nearly twenty consecutive hours on duty, the emergency room staff insisted on seeing every last patient before going home.", "alt": ["Although they were completely worn out after almost twenty straight hours on duty, the emergency room team refused to leave until they had seen the last patient."], "keys": [{"en": "Exhausted as they were", "zh": "儘管精疲力竭"}, {"en": "consecutive", "zh": "連續的"}, {"en": "on duty", "zh": "值班"}, {"en": "insisted on", "zh": "堅持"}, {"en": "worn out", "zh": "筋疲力盡的"}], "point": "「儘管……」除了用 although 子句之外，也可用「形容詞 + as + 主詞 + be 動詞」的讓步倒裝結構（Exhausted as they were…），語氣較為正式。insist on + V-ing 表「堅持做某事」；every last + 單數名詞 表「每一個……（一個也不漏）」，正好表達「看完最後一位病人」；on duty 表「值班中」，consecutive / straight 表「連續的」。「看完……才肯下班」也可譯為 refuse to leave until…，until 子句中用過去完成式強調「先看完病人」。", "topic": "medical professionals", "level": "C1"}, {"id": "T310", "zh": "要不是阿波羅十三號的太空人把登月艙當作救生艇使用，他們恐怕無法平安返回地球。", "en": "Had the crew of Apollo 13 not used the lunar module as a lifeboat, they would probably not have made it back to Earth safely.", "alt": ["If the Apollo 13 astronauts had not used their lunar module as a lifeboat, they might never have returned safely to Earth."], "keys": [{"en": "Had the crew", "zh": "要不是太空人……（Had + S + not + p.p.，省略 if 的倒裝）"}, {"en": "lunar module", "zh": "登月艙"}, {"en": "lifeboat", "zh": "救生艇"}, {"en": "made it back", "zh": "成功返回"}], "point": "與過去事實相反的假設語氣：If + S + had + p.p., S + would / might + have + p.p.。正式文體中可省略 if，將 had 移至句首倒裝（Had the crew not used…），此時否定詞 not 須放在主詞之後，不可寫成 Hadn't the crew…。make it back 意為「成功回到」；「恐怕」以 probably 或 might 表示推測。", "topic": "space exploration", "level": "C1"}, {"id": "T311", "zh": "時間銀行是一種互助制度，參與者每提供一小時的服務，就能累積一小時的時數，日後再用來換取他人的協助。", "en": "A time bank is a mutual aid system whereby participants earn one hour of credit for every hour of service they provide, and the hours they accumulate can later be exchanged for help from others.", "alt": ["A time bank is a system of mutual support in which members earn an hour's credit for each hour they spend helping others and can later use that credit to receive help in return."], "keys": [{"en": "mutual aid", "zh": "互助"}, {"en": "whereby", "zh": "藉此；據此（＝by which）"}, {"en": "credit", "zh": "（可兌換的）時數；點數"}, {"en": "exchanged for", "zh": "（被用來）換取"}, {"en": "in return", "zh": "作為回報"}], "point": "whereby 為正式用語，等於 by which / through which，常用來說明一個制度「如何運作」；也可用 in which 引導關係子句。for every / each hour… 表「每……就……」的對應關係；「累積」可用 accumulate，the hours (that) they accumulate 中省略了關係代名詞 that。exchange A for B 表「以 A 換取 B」，被動式為 A can be exchanged for B。", "topic": "time banks", "level": "C1"}, {"id": "T312", "zh": "「教授，不好意思，請問我的期末報告可以延後幾天交嗎？我上週因為生病住院了。」「這種情況可以理解，不過請你補交醫院開立的證明。」", "en": "\"Excuse me, Professor. Would it be possible for me to hand in my final paper a few days late? I had to be hospitalized last week because I was ill.\" \"That's understandable, but I'll need you to provide a medical certificate issued by the hospital.\"", "alt": ["\"Sorry to bother you, Professor, but could I possibly have an extension of a few days on my final paper? I was in the hospital last week because I was sick.\" \"Given the circumstances, that's understandable. Please submit a note from the hospital, though.\""], "keys": [{"en": "Would it be possible", "zh": "請問是否可以……（委婉請求）"}, {"en": "hand in", "zh": "繳交"}, {"en": "extension", "zh": "延期"}, {"en": "hospitalized", "zh": "住院"}, {"en": "medical certificate", "zh": "醫療證明；診斷證明"}], "point": "Would it be possible for me to V…? 與 Could I possibly…? 都比 Can I…? 更委婉，適合向師長提出請求；「延後幾天交」可說 hand in… a few days late，或 have an extension of a few days on…。I'll need you to V 是禮貌而明確地提出要求的說法；issued by… 為過去分詞片語，表「由……開立的」。", "topic": "academic requests", "level": "C1"}, {"id": "T313", "zh": "由於使用人口逐漸減少，台灣有些原住民族語言已面臨消失的危機，這也促使政府近年積極推動族語復振計畫。", "en": "As the number of speakers continues to dwindle, some of Taiwan's indigenous languages are already in danger of dying out, which has prompted the government to actively promote language revitalization programs in recent years.", "alt": ["With their speaker populations steadily shrinking, several of Taiwan's indigenous languages are at risk of disappearing, a situation that has prompted the government to step up efforts to revitalize them in recent years."], "keys": [{"en": "dwindle", "zh": "逐漸減少"}, {"en": "indigenous languages", "zh": "原住民族語言"}, {"en": "in danger of dying out", "zh": "面臨消失的危機"}, {"en": "prompted", "zh": "促使"}, {"en": "revitalization", "zh": "復振；復興"}], "point": "dwindle 表「（數量）逐漸減少」，比 decrease 更具書面語色彩；「面臨消失的危機」可譯為 be in danger of dying out 或 be at risk of disappearing。非限定關係子句的 which 可指代前面整個子句的內容；prompt + O + to V 表「促使某人做某事」，搭配 in recent years 時動詞宜用現在完成式。", "topic": "indigenous languages", "level": "C1"}, {"id": "T314", "zh": "建於 1884 年的台北府城北門，是台北現存城門中唯一保留清代原貌的一座。", "en": "Built in 1884, the North Gate of Taipei is the only one of the city's surviving gates that still retains its original Qing dynasty appearance.", "alt": ["Of all the city gates still standing in Taipei, the North Gate, completed in 1884, is the only one that has kept its original Qing-era appearance."], "keys": [{"en": "Built in 1884", "zh": "建於 1884 年"}, {"en": "the only one of", "zh": "……之中唯一的一個"}, {"en": "surviving", "zh": "現存的"}, {"en": "retains", "zh": "保留"}, {"en": "Qing dynasty", "zh": "清代"}], "point": "「建於……的」可用過去分詞片語 Built in… 置於句首修飾主詞，表被動，比 which was built in… 更精簡。「……中唯一的一座」用 the only one of + 複數名詞 + that…，關係子句的動詞須與 the only one 一致，故用單數 retains。surviving / remaining 皆可表「現存的」。台北府城其餘現存的城門後來曾經改建，只有北門維持原本的樣貌。", "topic": "Taipei history", "level": "C1"}, {"id": "T315", "zh": "研究團隊花了好幾年研發這種新藥，沒想到在最後階段的臨床試驗中，卻發現它的療效並不比現有的藥物好。", "en": "The research team spent years developing the new drug, only to discover in the final phase of clinical trials that it was no more effective than existing drugs.", "alt": ["The research team devoted several years to developing the new drug, but in the last stage of clinical trials they found, contrary to their expectations, that it worked no better than existing medicines."], "keys": [{"en": "spent years developing", "zh": "花了好幾年研發"}, {"en": "only to discover", "zh": "結果卻發現"}, {"en": "clinical trials", "zh": "臨床試驗"}, {"en": "no more effective than", "zh": "並不比……有效"}, {"en": "existing", "zh": "現有的"}], "point": "only to V 置於句尾，表示「（努力之後）結果卻……」的意外或令人失望的結果，正好對應「沒想到……卻……」。no more + adj. + than 表「並不比……更……」，強調新藥並沒有比較好，與現有藥物不相上下；work no better than 亦同。spend + 時間 + V-ing 表「花時間做某事」，devote + 時間 + to + V-ing 則較為正式。", "topic": "drug development", "level": "C1"}, {"id": "T316", "zh": "許多偏鄉長者連智慧型手機都不太會使用，更不用說透過網路預約掛號或申請政府補助了。", "en": "Many elderly people in remote areas can barely use a smartphone, let alone book medical appointments or apply for government subsidies online.", "alt": ["Many older residents of rural areas struggle even to use a smartphone, much less make doctor's appointments or apply for government benefits online."], "keys": [{"en": "remote areas", "zh": "偏鄉"}, {"en": "barely", "zh": "幾乎不；勉強"}, {"en": "let alone", "zh": "更不用說"}, {"en": "much less", "zh": "更不用說"}, {"en": "subsidies", "zh": "補助"}], "point": "let alone 表「更不用說」，用在否定或含否定意味的敘述之後，其後的結構須與前面對等（use… / book… / apply… 皆為原形動詞）；much less 用法相同。barely 本身帶有否定意味，表「幾乎不能、勉強」，因此後面可接 let alone。「預約掛號」可譯為 book / make a medical appointment。", "topic": "digital divide", "level": "C1"}, {"id": "T317", "zh": "我們其實不必帶那麼多現金出國的，因為當地幾乎每一家店都接受行動支付。", "en": "We needn't have taken so much cash abroad, as almost every shop there accepted mobile payments.", "alt": ["Bringing so much cash on the trip turned out to be unnecessary, since nearly every store there accepted mobile payment."], "keys": [{"en": "needn't have taken", "zh": "其實不必帶（卻帶了）"}, {"en": "abroad", "zh": "到國外"}, {"en": "accepted", "zh": "接受"}, {"en": "mobile payment", "zh": "行動支付"}, {"en": "turned out to be", "zh": "結果（證明）是"}], "point": "needn't have + p.p. 表「當時其實不必做某事，卻已經做了」，正好對應「其實不必……的」；若說 didn't need to take，只表示「沒有必要帶」，不一定表示實際上帶了。as / since 引導原因子句；turn out to be… 表「結果（證明）是……」。「行動支付」譯為 mobile payment。", "topic": "cashless travel", "level": "C1"}, {"id": "T318", "zh": "古典芭蕾強調輕盈與向上延伸的姿態，現代舞則往往刻意運用身體的重量，並與地面有更多的接觸。", "en": "Whereas classical ballet emphasizes lightness and upward extension, modern dance often makes deliberate use of the body's weight and involves more contact with the floor.", "alt": ["Classical ballet stresses lightness and an upward line, while modern dance often exploits the body's weight on purpose and makes greater use of the floor."], "keys": [{"en": "Whereas", "zh": "而；反之（表對比）"}, {"en": "emphasizes", "zh": "強調"}, {"en": "makes deliberate use of", "zh": "刻意運用"}, {"en": "on purpose", "zh": "刻意地；故意地"}, {"en": "contact with", "zh": "與……接觸"}], "point": "whereas 引導對比子句，用於比較兩件事物的差異，語氣比 while 更正式；中文「A……，B 則……」的對比句很適合用 whereas / while 翻譯。make use of 表「利用、運用」，在 use 前加形容詞 deliberate 即為「刻意運用」（＝ deliberately make use of）；on purpose 亦表「刻意地」。「與地面有更多的接觸」可譯為 involve more contact with the floor 或 make greater use of the floor。", "topic": "dance", "level": "C1"}, {"id": "T319", "zh": "位於北極圈內的斯瓦爾巴全球種子庫保存著來自世界各地的農作物種子；只要保存條件得當，許多種子可以存活數十年，甚至更久。", "en": "The Svalbard Global Seed Vault, located inside the Arctic Circle, holds crop seeds from all over the world; provided that they are stored under the right conditions, many seeds can remain viable for decades or even longer.", "alt": ["Located within the Arctic Circle, the Svalbard Global Seed Vault stores crop seeds from around the globe, and as long as storage conditions are suitable, many of these seeds can survive for several decades or more."], "keys": [{"en": "Arctic Circle", "zh": "北極圈"}, {"en": "crop seeds", "zh": "農作物種子"}, {"en": "provided that", "zh": "只要；在……條件下"}, {"en": "as long as", "zh": "只要"}, {"en": "viable", "zh": "（種子）仍能發芽的"}], "point": "provided (that) 與 as long as 皆可表「只要、在……的條件下」，provided that 較為正式。viable 指種子「仍有發芽能力的」，remain viable 即「保持存活」。located inside / within… 為過去分詞片語，補充說明地點；分號可連接兩個意義密切相關的獨立子句。", "topic": "seed banks", "level": "C1"}, {"id": "T320", "zh": "生成式人工智慧究竟會對就業市場造成多大的衝擊，目前仍眾說紛紜，但許多專家認為，懂得善用這類工具的人將更具優勢。", "en": "The extent to which generative AI will affect the job market remains a matter of debate, but many experts believe that those who know how to make good use of such tools will have an advantage.", "alt": ["Opinions vary widely on how much impact generative AI will have on the job market, but many experts believe that people who can use these tools effectively will be at an advantage."], "keys": [{"en": "the extent to which", "zh": "……的程度"}, {"en": "remains a matter of debate", "zh": "仍眾說紛紜；仍有爭議"}, {"en": "opinions vary", "zh": "眾說紛紜；看法不一"}, {"en": "make good use of", "zh": "善用"}, {"en": "at an advantage", "zh": "處於優勢"}], "point": "「……究竟會造成多大的衝擊」可用名詞片語 the extent to which + 子句 作主詞，也可用間接問句 how much impact… will have；remain a matter of debate 表「仍有爭議」，opinions vary (widely) 表「眾說紛紜」。those who… 表「……的人」；make good use of 表「善用」，have an advantage / be at an advantage 表「具有優勢」。", "topic": "AI and jobs", "level": "C1"}, {"id": "T321", "zh": "與一般人的認知相反，目前並沒有可靠的證據顯示經常扳手指關節會導致關節炎。", "en": "Contrary to popular belief, there is currently no reliable evidence that habitually cracking your knuckles causes arthritis.", "alt": ["Despite what many people believe, there is currently no solid evidence that frequent knuckle-cracking leads to arthritis."], "keys": [{"en": "Contrary to popular belief", "zh": "與一般人的認知相反"}, {"en": "reliable evidence", "zh": "可靠的證據"}, {"en": "cracking your knuckles", "zh": "扳手指關節"}, {"en": "arthritis", "zh": "關節炎"}, {"en": "leads to", "zh": "導致"}], "point": "contrary to popular belief 是報導與學術寫作中常見的開頭語，表「與一般認知相反」。evidence that + 子句 中的 that 子句為同位語，說明證據的內容，evidence 為不可數名詞，不加 s；動名詞片語 cracking your knuckles 作 that 子句的主詞，動詞用單數 causes。crack one's knuckles 表「扳手指關節（使其發出聲響）」。", "topic": "health myths", "level": "C1"}, {"id": "T322", "zh": "「你覺得我剛才的簡報怎麼樣？」「整體來說很有說服力，不過如果圖表能再簡化一些，聽眾也許會比較容易理解。」", "en": "\"What did you think of my presentation just now?\" \"On the whole, it was very persuasive, though if the charts were a little simpler, the audience might find them easier to follow.\"", "alt": ["\"How did you find my presentation?\" \"Overall, I thought it was really convincing. That said, simplifying the charts a bit might make them easier for the audience to understand.\""], "keys": [{"en": "On the whole", "zh": "整體來說"}, {"en": "persuasive", "zh": "有說服力的"}, {"en": "easier to follow", "zh": "比較容易理解"}, {"en": "That said", "zh": "話雖如此；不過"}, {"en": "simplifying", "zh": "簡化"}], "point": "給予意見時先肯定、再提出建議較為得體；if 子句用過去式（were）、主要子句用 might，是以假設語氣委婉地提出建議，聽起來不像直接批評。find + O + adj. 表「覺得某物……」，follow 在此表「聽懂、理解」。That said 意為「話雖如此」，常用來帶出保留意見。", "topic": "giving feedback", "level": "C1"}, {"id": "T323", "zh": "我們才剛在山頂上搭好帳篷，天氣就突然變壞，只好趕在天黑前撤下山。", "en": "Hardly had we pitched our tent on the summit when the weather suddenly took a turn for the worse, forcing us to hurry back down the mountain before dark.", "alt": ["We had barely set up our tent at the top of the mountain when the weather abruptly deteriorated, so we had no choice but to rush back down before nightfall."], "keys": [{"en": "Hardly had", "zh": "才剛……就……（句首倒裝）"}, {"en": "pitched our tent", "zh": "搭帳篷"}, {"en": "took a turn for the worse", "zh": "（情況）突然變壞"}, {"en": "had no choice but to", "zh": "只好"}, {"en": "before dark", "zh": "天黑前"}], "point": "「才剛……就……」可用 Hardly / Scarcely had + S + p.p.… when + S + 過去式；否定副詞 Hardly 置於句首時須倒裝，若不倒裝則寫成 We had barely / hardly… when…。take a turn for the worse 表「情況惡化」；句尾分詞構句 forcing us to… 表示前述情況所造成的結果。", "topic": "camping", "level": "C1"}, {"id": "T324", "zh": "直到自己當了父母，他才真正體會到父母當年為了養育孩子付出了多少心血。", "en": "Only after becoming a parent himself did he truly appreciate how much effort his own parents had put into raising a family.", "alt": ["It was not until he became a father himself that he fully realized how much devotion his parents had poured into bringing up their children."], "keys": [{"en": "Only after", "zh": "直到……之後才"}, {"en": "appreciate", "zh": "體會；充分理解"}, {"en": "put into", "zh": "投入"}, {"en": "raising", "zh": "養育"}, {"en": "bringing up", "zh": "撫養"}], "point": "Only + 副詞片語或子句（如 only after…）置於句首時，主要子句須倒裝（did he truly appreciate）；亦可用強調句 It was not until… that…。appreciate 在此表「充分體會、理解」，後接 how much… 引導的名詞子句；父母「當年」付出心血發生在他「體會」之前，故用過去完成式 had put。raise a family 與 bring up children 皆表「養育孩子」。", "topic": "parenthood", "level": "C1"}, {"id": "T325", "zh": "這些海洋生物的化石出現在離海岸數百公里的內陸，可見這一帶在遠古時代一定曾經是一片汪洋。", "en": "These marine fossils were found hundreds of kilometers inland, which means that this area must have been covered by the sea in prehistoric times.", "alt": ["The fact that these fossils of sea creatures lie hundreds of kilometers from the coast shows that the region must have been under the ocean in the distant past."], "keys": [{"en": "marine", "zh": "海洋的"}, {"en": "fossils", "zh": "化石"}, {"en": "inland", "zh": "在內陸"}, {"en": "must have been", "zh": "一定曾經是（對過去的肯定推測）"}, {"en": "prehistoric times", "zh": "遠古時代"}], "point": "must have + p.p. 表示對過去情況有把握的推測「當時一定……」；若是否定的推測，則用 can't / couldn't have + p.p.。「可見……」可用 which means that… 以非限定關係子句承接前句，或改用 The fact that… shows that…。inland 在此作副詞，表「在內陸」。", "topic": "fossils", "level": "C1"}, {"id": "T326", "zh": "專家建議，所有老舊校舍都應依照最新的耐震標準進行補強，以免地震來襲時危及師生的安全。", "en": "Experts recommend that all older school buildings be retrofitted to the latest seismic standards, lest students and teachers be put at risk when an earthquake strikes.", "alt": ["Experts advise that every aging school building should be strengthened in line with the most recent earthquake-resistance standards, so that the safety of teachers and students is not jeopardized when a quake hits."], "keys": [{"en": "recommend that", "zh": "建議……（that 子句用原形動詞）"}, {"en": "retrofitted", "zh": "補強（既有建築）"}, {"en": "seismic standards", "zh": "耐震標準"}, {"en": "lest", "zh": "以免"}, {"en": "put at risk", "zh": "危及（安全）；使……陷入危險"}], "point": "recommend、suggest、insist、require 等表「建議、要求」的動詞後接 that 子句時，子句動詞用原形（be retrofitted），此為表「意志」的假設語氣用法，英式英語亦常用 should + V（alt 即用 should be strengthened）。lest 為正式用語，意為「以免」，其後子句同樣用原形動詞（be put）或 should + V；lest 本身已含「以免」的否定意味，其後不可再加 not。retrofit 指「為既有建築或設備加裝、補強」，常與 seismic standards（耐震標準）搭配；in line with 意為「依照、符合」。", "topic": "school building safety", "level": "C2"}, {"id": "T327", "zh": "「你覺得這份企劃案還有哪些地方可以改進？」「這麼說吧，如果只說它『還有改進的空間』，那恐怕是太客氣了。」", "en": "\"Which parts of this proposal do you think could be improved?\" \"Let's just say that 'there's room for improvement' would be putting it mildly.\"", "alt": ["\"Where do you think this proposal could still be improved?\" \"Let's put it this way: to say that it leaves room for improvement would be something of an understatement.\""], "keys": [{"en": "Let's just say", "zh": "這麼說吧（委婉帶出不便明說的看法）"}, {"en": "room for improvement", "zh": "改進的空間"}, {"en": "putting it mildly", "zh": "（這樣說）太客氣了"}, {"en": "understatement", "zh": "輕描淡寫、過於保守的說法"}], "point": "回答者並未直接批評，而是指出「還有改進的空間」這種「含蓄陳述」(understatement) 太過輕描淡寫，藉此暗示企劃案問題很多，屬於言外之意的用法。Let's just say (that)… 用來委婉帶出不便明說的看法；to put it mildly 意為「說得客氣一點」，would be putting it mildly 以假設語氣表示「這樣說還太客氣了」。something of an understatement 中的 something of a… 表「有幾分是……」，使語氣更加含蓄。", "topic": "feedback on proposals", "level": "C2"}, {"id": "T328", "zh": "仲裁者必須保持超然、不偏袒任何一方，但這並不表示他可以對案情漠不關心。", "en": "An arbitrator must remain disinterested, favoring neither side, but that is not to say he or she can afford to be uninterested in the facts of the case.", "alt": ["An arbitrator has to stay impartial and take no one's side, which by no means implies that he or she may be indifferent to the details of the case."], "keys": [{"en": "disinterested", "zh": "超然中立的；無私心的"}, {"en": "favoring neither side", "zh": "不偏袒任何一方"}, {"en": "that is not to say", "zh": "這並不表示"}, {"en": "uninterested", "zh": "不感興趣的；漠不關心的"}, {"en": "impartial", "zh": "公正的；不偏頗的"}], "point": "disinterested 與 uninterested 是 C2 程度常見的近義混淆字：disinterested 指「與自身利害無關、立場超然的」，近似 impartial；uninterested 才是「不感興趣、漠不關心的」。雖然日常口語中有人把 disinterested 當作「不感興趣」使用，但正式寫作中仍宜嚴格區分。分詞片語 favoring neither side 補充說明 disinterested 的內涵；that is not to say… 意為「這並不表示……」，用來防止對方過度推論；can afford to be… 表「可以容許自己……」。", "topic": "law and impartiality", "level": "C2"}, {"id": "T329", "zh": "我無意對你的決定指手畫腳，但在還沒找到下一份工作之前就辭職，真的明智嗎？", "en": "Far be it from me to second-guess your decision, but is it really wise to quit before you have another job lined up?", "alt": ["I have no wish to tell you what to do, but do you really think it's sensible to resign before you've found your next job?"], "keys": [{"en": "Far be it from me", "zh": "我絕無意……"}, {"en": "second-guess", "zh": "對（他人的決定）指手畫腳；質疑"}, {"en": "lined up", "zh": "（工作等）已安排妥當的"}, {"en": "resign", "zh": "辭職"}], "point": "Far be it from me to V 是保留舊式假設語氣（be 用原形）的慣用句，意為「我絕無意……」，後面通常接 but：說話者表面上表示不願干涉，實際上仍提出自己的意見，語氣委婉而有所保留。second-guess 意為「質疑、批評（別人的決定）」，在此對應「指手畫腳」；have sth lined up 表「（工作、計畫等）已經安排妥當」。is it really wise to V…? 以反問句表達質疑，比直接說 You shouldn't… 更為得體。", "topic": "career decisions", "level": "C2"}, {"id": "T330", "zh": "現有的證據似乎顯示這兩者之間存在某種關聯，但若據此斷定其中一方是另一方的成因，恐怕言之過早。", "en": "The available evidence would seem to suggest some kind of link between the two, but it would be premature to conclude from this that one is the cause of the other.", "alt": ["Current evidence appears to point to some sort of association between the two; to infer from it that one causes the other, however, would be jumping the gun."], "keys": [{"en": "would seem to suggest", "zh": "似乎顯示"}, {"en": "link between", "zh": "……之間的關聯"}, {"en": "premature", "zh": "過早的；言之過早的"}, {"en": "conclude from this", "zh": "據此斷定"}, {"en": "jumping the gun", "zh": "操之過急；過早下定論"}], "point": "學術寫作常用「模糊限制語」(hedging) 讓論述保留餘地：would seem to suggest 比 suggests 更為保留，appear to 亦有類似效果；some kind of link 則刻意不說明關聯的性質。it would be premature to V 意為「……恐怕言之過早」，以 would 表委婉的判斷。此句的核心觀念是「相關不等於因果」(correlation does not imply causation)；alt 中的 jump the gun 原指賽跑時搶跑，引申為「操之過急、過早行動」。", "topic": "research and evidence", "level": "C2"}, {"id": "T331", "zh": "體長大多不到一公釐的水熊蟲，一旦進入休眠狀態，便能熬過極度的嚴寒、乾燥，甚至太空中的真空環境。", "en": "Tardigrades, most of which are less than a millimeter long, can survive extreme cold, desiccation and even the vacuum of space once they enter a dormant state.", "alt": ["Once they have entered a dormant state, tardigrades, most measuring under a millimeter in length, are able to endure intense cold, extreme dryness and even the vacuum of outer space."], "keys": [{"en": "tardigrades", "zh": "水熊蟲（緩步動物）"}, {"en": "most of which", "zh": "其中大多數"}, {"en": "desiccation", "zh": "極度乾燥；脫水"}, {"en": "vacuum of space", "zh": "太空中的真空"}, {"en": "dormant", "zh": "休眠的"}], "point": "「體長大多不到一公釐的」可譯為非限定關係子句 most of which are less than a millimeter long（which 指 tardigrades），或獨立分詞片語 most measuring under a millimeter in length。once 作連接詞，意為「一旦」。desiccation 為低頻但精確的學術用字，意為「完全乾燥、脫水」；dormant 意為「休眠的」；the vacuum of space 指「太空中的真空環境」。列舉三項以上時，最後一項前加 and，並可用 even 強調最令人意外的一項。", "topic": "microscopic animals", "level": "C2"}, {"id": "T332", "zh": "十四世紀中葉的黑死病奪走了歐洲約三分之一到一半的人口；其破壞力之大，導致勞動力嚴重短缺，倖存的農民因而得以要求更高的工資。", "en": "So devastating was the Black Death of the mid-fourteenth century, which wiped out an estimated one-third to one-half of Europe's population, that it left behind a severe labor shortage, enabling the surviving peasants to demand higher wages.", "alt": ["The Black Death, which killed roughly a third to a half of Europe's population in the mid-1300s, was so destructive that it left a severe shortage of workers, and the peasants who survived were consequently able to press for higher wages."], "keys": [{"en": "So devastating was", "zh": "其破壞力之大"}, {"en": "wiped out", "zh": "奪走；消滅"}, {"en": "an estimated", "zh": "估計約有"}, {"en": "labor shortage", "zh": "勞動力短缺"}, {"en": "press for", "zh": "力爭；極力要求"}], "point": "「其……之大，以致……」可用 so + adj. + that 結構；將 So devastating 移至句首時，主詞與 be 動詞須倒裝（So devastating was the Black Death… that…），語氣更為正式有力。關係子句 which wiped out… 補充說明死亡規模；an estimated + 數量 表「估計約……」，適用於史學上沒有確切數字的情況。分詞片語 enabling… 表示由此帶來的結果；alt 中的 press for 意為「力爭、極力要求」。", "topic": "medieval history", "level": "C2"}, {"id": "T333", "zh": "「印象派」這個名稱原本是一位藝評家用來嘲諷莫內等畫家的字眼；諷刺的是，這群畫家後來竟欣然接受了它。", "en": "The name \"Impressionist\" was originally a term of derision, used by an art critic to mock Monet and his fellow painters; ironically, the painters themselves later embraced it.", "alt": ["The label \"Impressionist\" started out as a jibe that an art critic aimed at Monet and his circle; ironically enough, the group went on to adopt it willingly."], "keys": [{"en": "term of derision", "zh": "嘲諷的字眼"}, {"en": "mock", "zh": "嘲笑；嘲諷"}, {"en": "ironically", "zh": "諷刺的是"}, {"en": "embraced", "zh": "欣然接受"}, {"en": "jibe", "zh": "嘲弄的話"}], "point": "term of derision 意為「嘲諷用語」，derision 為 deride（嘲笑）的名詞；過去分詞片語 used by an art critic to mock… 補充說明這個用語的來源。ironically 置於分號之後，點出前後兩件事的反差；embrace 在此不是「擁抱」，而是「欣然接受（想法、名稱等）」；alt 中的 go on to V 表「後來進而……」。史實上，這個名稱源自莫內的畫作《印象・日出》：1874 年藝評家勒華（Louis Leroy）借此畫名譏諷參展的畫家，後來這群畫家便以此自稱。", "topic": "art history", "level": "C2"}, {"id": "T334", "zh": "當一項資源人人都能取用，卻沒有人需要為它負責時，它往往會遭到過度開發，直到耗竭為止；這就是所謂的「公地悲劇」。", "en": "When a resource is open to all but no one is held accountable for it, it tends to be overexploited until it is depleted; this is what is known as \"the tragedy of the commons.\"", "alt": ["A resource that anyone may use but nobody is responsible for is liable to be overused until it is exhausted, a phenomenon referred to as the tragedy of the commons."], "keys": [{"en": "open to all", "zh": "人人都能取用"}, {"en": "held accountable for", "zh": "須為……負責"}, {"en": "overexploited", "zh": "過度開發的"}, {"en": "depleted", "zh": "耗竭的"}, {"en": "tragedy of the commons", "zh": "公地悲劇"}], "point": "open to all 意為「對所有人開放」；be held accountable for 表「被要求為……負責」，比 be responsible for 更強調追究責任。overexploit 指「過度開發、濫用（資源）」；deplete 指「耗盡（資源、存量）」，常與 resources、reserves 搭配。this is what is known as… 對應「這就是所謂的……」，為前述現象命名；alt 中的 be liable to V 表「容易……」，多用於不好的結果，句末名詞片語 a phenomenon referred to as… 則是對全句的同位補充。", "topic": "shared resources", "level": "C2"}, {"id": "T335", "zh": "有些電子產品在設計時就刻意讓使用者難以自行維修，於是，一台原本仍堪用的機器，往往只因一個小零件故障就被整台淘汰。", "en": "Some electronic devices are deliberately designed to be difficult for users to repair themselves, with the result that a machine that is otherwise perfectly serviceable is often thrown away in its entirety simply because of one small faulty component.", "alt": ["Certain electronic products are intentionally made hard for owners to fix on their own, so an otherwise usable machine frequently ends up being scrapped altogether over a single minor broken part."], "keys": [{"en": "deliberately", "zh": "刻意地"}, {"en": "with the result that", "zh": "結果；以致於"}, {"en": "serviceable", "zh": "堪用的；仍可使用的"}, {"en": "in its entirety", "zh": "整個地；全部"}, {"en": "faulty component", "zh": "故障的零件"}], "point": "be designed to be difficult for sb to V 意為「被設計成讓某人難以……」，deliberately 強調「刻意」。with the result that 引導結果子句，語氣比 so 正式。serviceable 在此意為「仍可使用的、堪用的」，與 otherwise（在其他方面）連用，表「除了這一點之外都還好好的」；in its entirety 意為「整個地、全部」，faulty component 即「故障的零件」。alt 中的 over 表「因為……（這件事）」，scrap 意為「報廢、丟棄」。", "topic": "right to repair", "level": "C2"}, {"id": "T336", "zh": "加薪帶來的喜悅往往轉瞬即逝，因為人們很快就會習慣新的生活水準，轉而渴望更多。", "en": "The joy of a pay raise is often fleeting, as people soon grow accustomed to their new standard of living and begin to hanker after more.", "alt": ["The happiness that comes with a raise tends to be short-lived, because people quickly get used to their improved standard of living and start craving even more."], "keys": [{"en": "fleeting", "zh": "轉瞬即逝的"}, {"en": "grow accustomed to", "zh": "逐漸習慣"}, {"en": "standard of living", "zh": "生活水準"}, {"en": "hanker after", "zh": "渴望；嚮往"}, {"en": "short-lived", "zh": "短暫的"}], "point": "fleeting 意為「轉瞬即逝的」，與 short-lived 同義而較具文學色彩；grow accustomed to + N 表「逐漸習慣……」（to 為介系詞，後接名詞或動名詞）。hanker after/for 為較少見的片語動詞，意為「渴望、念念不忘」。as 在此作連接詞，意為「因為」。心理學上把人們很快適應新處境、快樂感隨之回落的現象稱為「享樂適應」(hedonic adaptation)。", "topic": "happiness", "level": "C2"}, {"id": "T337", "zh": "「明天的面試準備得怎麼樣了？」「能做的我都做了，剩下的就只能聽天由命了。」", "en": "\"How are your preparations for tomorrow's interview coming along?\" \"I've done everything I can. The rest is in the lap of the gods.\"", "alt": ["\"Are you all set for tomorrow's interview?\" \"I've done all I possibly can; the rest is out of my hands.\""], "keys": [{"en": "coming along", "zh": "（事情）進展"}, {"en": "done everything I can", "zh": "能做的都做了"}, {"en": "in the lap of the gods", "zh": "聽天由命；非人力所能左右"}, {"en": "out of my hands", "zh": "不在我的掌控之中"}], "point": "How is sth coming along? 用來詢問事情的進展，語氣自然；be all set for… 意為「已經為……準備就緒」。everything I can 之後省略了 do（I've done everything I can [do]），是英語避免重複的省略用法。in the lap of the gods 意為「全憑天意、非人力所能左右」，out of one's hands 意為「已不在某人掌控之中」，兩者皆可對應「聽天由命」。", "topic": "job interviews", "level": "C2"}, {"id": "T338", "zh": "澳洲醫師馬歇爾深信胃潰瘍多半不是壓力所致，而是細菌造成的，甚至不惜在 1984 年親自喝下含有幽門螺旋桿菌的培養液；這個一度被視為離經叛道的理論，後來為他和同事贏得了諾貝爾獎。", "en": "Convinced that most stomach ulcers were caused not by stress but by bacteria, the Australian physician Barry Marshall went so far as to drink a culture of Helicobacter pylori himself in 1984; his once-heretical theory later earned him and a colleague a Nobel Prize.", "alt": ["Because he was so sure that bacteria, rather than stress, were behind most stomach ulcers, the Australian doctor Barry Marshall even swallowed a culture of Helicobacter pylori in 1984; his theory, once regarded as heresy, eventually won him and his colleague the Nobel Prize."], "keys": [{"en": "Convinced that", "zh": "深信……（過去分詞片語）"}, {"en": "not by stress but by bacteria", "zh": "不是壓力所致，而是細菌造成的"}, {"en": "went so far as to", "zh": "甚至不惜……"}, {"en": "culture", "zh": "（細菌的）培養液；培養物"}, {"en": "once-heretical", "zh": "一度被視為離經叛道的"}], "point": "「深信……」可用過去分詞片語 Convinced that… 置於句首，其邏輯主詞須與主要子句的主詞（Barry Marshall）一致；「不是 A，而是 B」用 not by A but by B，兩個 by 片語須對等。go so far as to V 意為「甚至做到……的地步、不惜……」。culture 在此不是「文化」，而是「（細菌的）培養物、培養液」。once 與形容詞以連字號結合（once-heretical），意為「一度……的」；heretical 原指「異端的」，引申為「離經叛道的」。史實上，馬歇爾與病理學家華倫（Robin Warren）主張幽門螺旋桿菌是胃炎與消化性潰瘍的主因，卻長期不被醫學界接受；馬歇爾於 1984 年親自喝下菌液後出現胃炎症狀，兩人後來於 2005 年共同獲得諾貝爾生理醫學獎。", "topic": "history of medicine", "level": "C2"}, {"id": "T339", "zh": "卡夫卡曾留下字條，要求好友在他死後把他的手稿全部燒掉；幸好這位朋友沒有照辦，否則《審判》等作品恐怕永遠無法問世。", "en": "Kafka left notes asking a close friend to burn all his manuscripts after his death; fortunately, the friend did not comply, or works such as The Trial might never have seen the light of day.", "alt": ["Kafka left instructions for a close friend to burn all of his manuscripts once he had died. Luckily, the friend ignored them; otherwise, works like The Trial would probably never have been published."], "keys": [{"en": "manuscripts", "zh": "手稿"}, {"en": "comply", "zh": "照辦；遵從"}, {"en": "might never have", "zh": "恐怕永遠不會……（與過去事實相反）"}, {"en": "seen the light of day", "zh": "問世；公諸於世"}, {"en": "otherwise", "zh": "否則"}], "point": "「沒有照辦」可譯為 did not comply（comply 為不及物動詞，若接受詞須用 comply with）。「否則」可用 or 或 otherwise 連接，其後用 might/would never have + p.p.，表示與過去事實相反的推測。see the light of day 意為「問世、公諸於世」。史實上，卡夫卡的好友布羅德（Max Brod）違背其遺願，整理出版了《審判》、《城堡》等作品。", "topic": "literature", "level": "C2"}, {"id": "T340", "zh": "好的小說不會把一切都交代得一清二楚，而是留給讀者足夠的想像空間，讓他們自己去體會、去下結論。", "en": "A good novel refrains from spelling everything out; rather, it leaves readers enough room to use their imagination, work things out for themselves and draw their own conclusions.", "alt": ["Good fiction does not make everything explicit; instead, it gives readers ample scope for imagination, allowing them to read between the lines and reach their own conclusions."], "keys": [{"en": "refrains from", "zh": "避免；克制不做"}, {"en": "spelling everything out", "zh": "把一切交代得一清二楚"}, {"en": "rather", "zh": "而是；反倒是"}, {"en": "draw their own conclusions", "zh": "自己下結論"}, {"en": "ample scope for", "zh": "充分的……空間"}], "point": "spell sth out 意為「把……詳細說清楚」；refrain from + V-ing 意為「克制、避免做……」，比單純的 does not 更具「刻意不做」的意味。「不是 A，而是 B」除了 not A but B，也可用分號加 rather 帶出後句，語氣較正式。draw a conclusion 為固定搭配，亦可說 reach / come to a conclusion；alt 中的 scope for 意為「……的空間、餘地」，read between the lines 意為「體會字裡行間的意思」。", "topic": "fiction writing", "level": "C2"}, {"id": "T341", "zh": "「那家新開的餐廳怎麼樣？」「上菜速度真是『驚人』──我們才等了一個半小時，主菜就上桌了。」", "en": "\"How was that new restaurant?\" \"Oh, the service was impressively fast. Our main course arrived after a mere hour and a half.\"", "alt": ["\"What did you make of the new restaurant?\" \"The service was lightning fast. We only had to wait an hour and a half for our main course.\""], "keys": [{"en": "impressively fast", "zh": "快得驚人"}, {"en": "a mere", "zh": "僅僅"}, {"en": "main course", "zh": "主菜"}, {"en": "What did you make of", "zh": "……怎麼樣（詢問對方的看法）"}, {"en": "lightning fast", "zh": "快如閃電"}], "point": "回答者使用「反語」(verbal irony)：字面上稱讚上菜很快，實際上是抱怨等得太久。中文以引號『驚人』標示反語，英文則藉 impressively fast、lightning fast 等誇張的讚美，搭配 a mere、only 等強調「為數很少」的字眼，與「一個半小時」形成強烈反差，讓聽者察覺說話者的真意。What did you make of…? 意為「你對……有什麼看法？」。", "topic": "dining out", "level": "C2"}, {"id": "T342", "zh": "1952 年冬天，一場嚴重的霧霾籠罩倫敦數日，奪走了數千條人命；這場災難直接促成英國在 1956 年通過《清淨空氣法》。", "en": "In the winter of 1952, a severe smog shrouded London for several days and claimed thousands of lives; the disaster provided the direct impetus for the Clean Air Act, which Britain passed in 1956.", "alt": ["During the winter of 1952, London was engulfed for days by a deadly smog that killed thousands of people, a catastrophe that was instrumental in prompting Britain to pass the Clean Air Act in 1956."], "keys": [{"en": "shrouded", "zh": "籠罩"}, {"en": "claimed thousands of lives", "zh": "奪走數千條人命"}, {"en": "impetus", "zh": "推動力；促成因素"}, {"en": "instrumental in", "zh": "對……起關鍵作用"}, {"en": "Clean Air Act", "zh": "《清淨空氣法》"}], "point": "claim lives 意為「奪走性命」，主詞常為災難、疾病或事故；shroud 與 engulf 皆可表「籠罩、吞沒」，前者多用於霧、黑暗等。「直接促成」可譯為 provide the direct impetus for（為……提供直接的推動力）或 be instrumental in V-ing（在……上起關鍵作用）。此事件史稱「倫敦大霧霾」(the Great Smog of London)，是推動現代空氣污染防治立法的重要轉捩點。", "topic": "air pollution history", "level": "C2"}, {"id": "T343", "zh": "資安專家常說，一套系統的安全程度取決於它最薄弱的一環，而這一環往往不是軟體，而是使用軟體的人。", "en": "Security experts often say that a system is only as secure as its weakest link, and more often than not, that link is not the software but the people who use it.", "alt": ["As cybersecurity specialists like to point out, a system's security hinges on its weakest point, which is frequently the human user rather than the software itself."], "keys": [{"en": "only as secure as", "zh": "安全程度取決於……"}, {"en": "weakest link", "zh": "最薄弱的一環"}, {"en": "more often than not", "zh": "往往；多半"}, {"en": "hinges on", "zh": "取決於"}], "point": "be only as + adj. + as… 由諺語 A chain is only as strong as its weakest link 變化而來，意為「……的程度取決於……」；weakest link 即「最薄弱的一環」。more often than not 意為「往往、多半」，語氣比 often 更強；hinge on 意為「取決於」，與 depend on 同義但較生動。「不是 A，而是 B」用 not A but B，A、B 須為對等的名詞片語。", "topic": "cybersecurity", "level": "C2"}, {"id": "T344", "zh": "人們回顧過去時，往往會不自覺地美化當年的生活，彷彿那時候的一切都比現在美好。", "en": "When people look back on the past, they tend, quite unwittingly, to view it through rose-colored glasses, as though everything had been better in those days.", "alt": ["Looking back, people often unconsciously romanticize the lives they once led, as if everything had been better back then than it is now."], "keys": [{"en": "look back on", "zh": "回顧"}, {"en": "unwittingly", "zh": "不自覺地；無意中"}, {"en": "rose-colored glasses", "zh": "美化的眼光（玫瑰色眼鏡）"}, {"en": "romanticize", "zh": "美化；理想化"}, {"en": "as though", "zh": "彷彿"}], "point": "view/see sth through rose-colored glasses 意為「以過度美化的眼光看待」（英式英語多作 rose-tinted spectacles）；romanticize 亦可表「把……理想化、美化」。as though/as if 後接過去完成式（had been），表示與過去事實未必相符的情況。unwittingly 意為「不知不覺地」，與 unconsciously 同義而較為書面；插入語 quite unwittingly 置於 tend 與 to 之間，使語氣更為細膩。", "topic": "nostalgia", "level": "C2"}, {"id": "T345", "zh": "將外來物種引進新的生態系，有時會帶來意想不到的後果；澳洲當年為了對付甘蔗田裡的害蟲而引進的海蟾蜍，就是一個惡名昭彰的例子。", "en": "Introducing a non-native species into a new ecosystem can have unforeseen consequences; the cane toad, brought to Australia to combat pests in sugarcane fields, is a notorious case in point.", "alt": ["Bringing alien species into an unfamiliar ecosystem sometimes backfires in ways no one anticipated; the cane toad, which Australia imported to deal with beetles plaguing its sugarcane crops, is an infamous example."], "keys": [{"en": "non-native species", "zh": "外來物種"}, {"en": "unforeseen consequences", "zh": "意想不到的後果"}, {"en": "combat", "zh": "對付；防治"}, {"en": "notorious", "zh": "惡名昭彰的"}, {"en": "case in point", "zh": "恰當的例子；明證"}], "point": "unforeseen consequences 為常見搭配，意為「未預料到的後果」；過去分詞片語 brought to Australia to… 補充說明海蟾蜍的來歷，相當於 which was brought…。a case in point 意為「正好說明前述論點的恰當例子」；notorious 與 infamous 皆為「惡名昭彰的」，backfire 意為「產生反效果」。史實上，澳洲於 1935 年引進海蟾蜍以防治甘蔗甲蟲，但牠們未能有效控制蟲害，反而大量繁殖，成為危害當地生態的入侵物種。", "topic": "invasive species", "level": "C2"}, {"id": "T346", "zh": "1947 年，工程師在一台電腦的繼電器裡發現一隻飛蛾，便把牠黏貼在工作日誌上，並註明這是「首次發現真正的蟲」；這句玩笑之所以好笑，是因為當時 bug 一詞早已被用來指稱機器的故障。", "en": "In 1947, engineers found a moth trapped in one of a computer's relays and taped it into their logbook with the note \"First actual case of bug being found\"; what makes the joke work is that by then \"bug\" had long been used to refer to a mechanical fault.", "alt": ["When engineers discovered a moth caught in a relay of their computer in 1947, they stuck it in their logbook and labeled it the \"first actual case of bug being found.\" The joke is funny only because the word \"bug\" had already been used for decades to describe a technical glitch."], "keys": [{"en": "relays", "zh": "繼電器"}, {"en": "taped it into", "zh": "把……黏貼在（本子）上"}, {"en": "logbook", "zh": "工作日誌"}, {"en": "what makes the joke work", "zh": "這句玩笑之所以好笑（的原因）"}, {"en": "had long been used", "zh": "早已被用來"}], "point": "with the note… 中的 with 表示「附有」，對應「並註明」。「之所以……，是因為……」可用 what makes… is that…，這種以 what 子句作主詞的準分裂句，可把重點放在 is that 之後的原因上；alt 則用 only because 強調「唯有……才」。by then 意為「到那時為止」，與過去完成式 had long been used 連用，表示 1947 年之前早已存在的狀況；glitch 意為「（機器、系統的）小故障」。日誌上那句話的笑點正在於 actual（真正的）一字：平常說的 bug 只是比喻，這次卻是貨真價實的蟲。史實上，這隻飛蛾是在哈佛大學的 Mark II 電腦中發現的，那頁日誌現藏於美國史密森尼博物館；而早在 1870 年代，愛迪生就曾在信中以 bug 稱呼發明中的毛病。", "topic": "history of computing", "level": "C2"}, {"id": "T347", "zh": "「你這是在暗示我做得不夠好嗎？」「我可沒這麼說，那是你自己推論出來的。」", "en": "\"Are you implying that I haven't done a good enough job?\" \"I said no such thing. That's something you've inferred on your own.\"", "alt": ["\"Are you suggesting my work isn't up to scratch?\" \"I never said that. That's purely your own inference.\""], "keys": [{"en": "implying", "zh": "暗示"}, {"en": "I said no such thing", "zh": "我可沒這麼說"}, {"en": "inferred", "zh": "推論；推斷"}, {"en": "up to scratch", "zh": "達到標準"}, {"en": "inference", "zh": "推論"}], "point": "imply 與 infer 常被混用：imply 是說話者「暗示」，infer 是聽者從話語中「推論、推斷」；本題一問一答分別用這兩個字，恰好呈現兩者的分別（名詞為 implication 與 inference）。I said no such thing 比 I didn't say that 更為斬釘截鐵；up to scratch 為慣用語，意為「達到要求的水準」。", "topic": "workplace misunderstandings", "level": "C2"}, {"id": "T348", "zh": "直到近年，科學家才逐漸了解，生活在我們腸道中數以兆計的微生物，可能對免疫系統甚至情緒都有深遠的影響。", "en": "Only in recent years have scientists come to appreciate that the trillions of microbes living in our gut may exert a profound influence on our immune system and even our mood.", "alt": ["It is only recently that scientists have begun to realize that the trillions of microorganisms inhabiting our intestines may profoundly affect our immune system, and even our emotions."], "keys": [{"en": "Only in recent years have", "zh": "直到近年……才"}, {"en": "come to appreciate", "zh": "逐漸了解"}, {"en": "trillions of", "zh": "數以兆計的"}, {"en": "exert a profound influence on", "zh": "對……有深遠的影響"}, {"en": "gut", "zh": "腸道"}], "point": "Only + 副詞片語置於句首時，主要子句須倒裝（have scientists come…）；也可改用強調句 It is only recently that…。come to V 表「逐漸……」，appreciate 在此意為「認識到、充分理解」，而非「感激」。exert an influence on 為正式搭配，意為「產生影響」；may 表示目前仍屬推測，對應原文的「可能」，是科學寫作中常見的保留語氣。", "topic": "gut microbiome", "level": "C2"}, {"id": "T349", "zh": "這項政策的出發點固然良善，但執行上漏洞百出，結果反而適得其反。", "en": "The policy was, to be sure, well-intentioned, but its implementation was so riddled with flaws that it proved counterproductive.", "alt": ["Admittedly, the policy was born of good intentions, but its execution was so full of holes that it ended up doing more harm than good."], "keys": [{"en": "to be sure", "zh": "固然；誠然"}, {"en": "well-intentioned", "zh": "出發點良善的"}, {"en": "riddled with flaws", "zh": "漏洞百出"}, {"en": "counterproductive", "zh": "適得其反的"}, {"en": "more harm than good", "zh": "適得其反（弊大於利）"}], "point": "to be sure 與 admittedly 皆用來先承認一項事實，再以 but 帶出轉折，相當於「固然……，但……」。be riddled with 意為「充斥著（缺點、錯誤等）」，與 flaws（缺陷）搭配即為「漏洞百出」，alt 中的 full of holes 亦同義；loophole 則專指法規中可被人鑽的漏洞，用來形容「執行上」的疏失並不貼切。so… that… 表結果。prove + adj. 意為「結果證明是……」，counterproductive 意為「產生反效果的」；do more harm than good 意為「弊大於利、反而有害」；be born of 意為「源自……」。", "topic": "public policy", "level": "C2"}, {"id": "T350", "zh": "她本來可以接受那份待遇更好的工作，卻選擇不去，因為她放心不下年邁的父母。", "en": "She could have taken the better-paid job but chose not to, as she could not bear to leave her elderly parents to fend for themselves.", "alt": ["She could have accepted the job with the higher salary, but she decided against it because she couldn't stop worrying about her aging parents."], "keys": [{"en": "could have taken", "zh": "本來可以接受"}, {"en": "better-paid", "zh": "待遇較好的"}, {"en": "chose not to", "zh": "選擇不（這麼做）"}, {"en": "fend for themselves", "zh": "自己照顧自己"}, {"en": "decided against it", "zh": "決定不這麼做"}], "point": "could have + p.p. 表示「過去本來可以做，實際上卻沒有做」。chose not to 之後省略了 take it，僅以不定詞符號 to 代替前面的動詞片語，是英語避免重複的省略用法。can't bear to V 意為「不忍心……」；leave sb to fend for themselves 意為「留下某人獨自照料自己」，恰可傳達「放心不下」的心情。decide against sth 意為「決定不做某事」。", "topic": "family and career", "level": "C2"}, {"id": "T351", "zh": "伽利略在 1633 年被迫公開放棄地動說；據說他事後曾低聲說了一句「但它仍在轉動」，不過這則軼事多半是後人杜撰的。", "en": "In 1633 Galileo was forced to recant heliocentrism publicly; he is said to have muttered afterwards, \"And yet it moves,\" although the anecdote is in all likelihood apocryphal.", "alt": ["In 1633 Galileo was made to renounce publicly the idea that the Earth moves, and legend has it that he then whispered, \"But it does move\" — a story that was most probably made up by later writers."], "keys": [{"en": "recant", "zh": "公開放棄、撤回（主張）"}, {"en": "heliocentrism", "zh": "地動說；日心說"}, {"en": "is said to have muttered", "zh": "據說曾低聲說"}, {"en": "in all likelihood", "zh": "多半；十之八九"}, {"en": "apocryphal", "zh": "（軼事）杜撰的；真實性可疑的"}], "point": "recant 指「公開撤回原先的主張或信仰」，常用於在壓力下被迫認錯的情境，比 give up 精確得多。「據說他曾……」用 S + be said + to have p.p.，完成式不定詞表示所說的事發生在過去。apocryphal 專指「廣為流傳卻未必屬實的軼事」，正好對應「後人杜撰」；in all likelihood 意為「十之八九、多半」，是正式的推測用語。alt 中 legend has it that… 為「相傳……」的慣用說法。", "topic": "history of science", "level": "C2"}, {"id": "T352", "zh": "一種方言的消失往往悄無聲息：沒有人宣告它的死亡，只是某天我們忽然發現，再也沒有人用它哄孩子入睡了。", "en": "A dialect usually slips away without a sound: no one announces its passing; it simply dawns on us one day that nobody lulls a child to sleep in it anymore.", "alt": ["The disappearance of a dialect tends to go unnoticed. Nobody proclaims its death; one day we simply realize, with a start, that no one uses it to lull children to sleep any longer."], "keys": [{"en": "slips away", "zh": "悄悄消逝"}, {"en": "its passing", "zh": "它的逝去（死亡的委婉說法）"}, {"en": "dawns on us", "zh": "我們忽然意識到"}, {"en": "lull children to sleep", "zh": "哄孩子入睡"}, {"en": "go unnoticed", "zh": "不被察覺；悄無聲息"}], "point": "「悄無聲息地消失」可用 slip away（悄悄消逝）或 go unnoticed；passing 為 death 的委婉說法。「某天忽然發現」用 it dawns on sb that…（某人恍然意識到），比 realize 更能表現後知後覺的語感。lull sb to sleep 指以輕柔的聲音或動作「哄某人入睡」；in it 的 it 指方言，表「用這種方言」。冒號引出對前句的說明，分號則連接兩個關係緊密的獨立子句。", "topic": "endangered dialects", "level": "C2"}, {"id": "T353", "zh": "一旦某項指標成了人人追逐的目標，它便不再能準確反映原本所要衡量的事物；這就是所謂的「古德哈特定律」。", "en": "Once a metric becomes a target that everyone pursues, it ceases to be an accurate reflection of what it was meant to measure — a phenomenon known as Goodhart's law.", "alt": ["As soon as an indicator turns into a goal that everyone chases, it no longer faithfully reflects the thing it was originally designed to gauge; this is what is known as Goodhart's law."], "keys": [{"en": "metric", "zh": "指標"}, {"en": "ceases to be", "zh": "不再是"}, {"en": "what it was meant to measure", "zh": "原本所要衡量的事物"}, {"en": "known as", "zh": "所謂的；被稱為"}, {"en": "gauge", "zh": "衡量；評估"}], "point": "ceases to be 比 is no longer 更正式；what it was meant to measure 為名詞子句（what = the thing that），be meant to V 表「原本用意是……」。句尾以破折號加 a phenomenon known as…，用同位語總結前面整件事，是書面英文常見的寫法。metric 與 indicator 皆可指「指標」；gauge 為「衡量」的正式動詞。古德哈特定律以英國經濟學家古德哈特（Charles Goodhart）命名。", "topic": "economics", "level": "C2"}, {"id": "T354", "zh": "安慰劑效應提醒我們，病人對治療所抱持的期待，本身就可能在某種程度上左右療效。", "en": "The placebo effect reminds us that patients' expectations of a treatment may, in and of themselves, influence its effectiveness to some degree.", "alt": ["The placebo effect serves as a reminder that what patients expect from a treatment can in itself affect, to a certain extent, how well it works."], "keys": [{"en": "placebo effect", "zh": "安慰劑效應"}, {"en": "in and of themselves", "zh": "本身（就）"}, {"en": "to some degree", "zh": "在某種程度上"}, {"en": "serves as a reminder", "zh": "提醒（我們）"}, {"en": "effectiveness", "zh": "療效；效果"}], "point": "in and of itself / themselves 意為「就其本身而言」，強調「光是這一點就……」，須與所指名詞的單複數一致（expectations → themselves）。to some degree、to a certain extent 是學術英文常見的「限定語」（hedge），使主張不致過於絕對，對應「在某種程度上」。serve as a reminder that… 為 remind us that… 的正式說法；「療效」可譯為 effectiveness，或用名詞子句 how well it works。", "topic": "medicine", "level": "C2"}, {"id": "T355", "zh": "演算法只推送我們愛看的內容，久而久之，我們便在不知不覺中被困在自己的同溫層裡，再也聽不到相左的意見。", "en": "Because algorithms feed us only what we like to see, over time we become imperceptibly trapped in our own echo chambers, cut off from dissenting views.", "alt": ["With algorithms serving up nothing but the content we enjoy, we gradually and unwittingly end up sealed inside our own filter bubbles, where opposing opinions never reach us."], "keys": [{"en": "feed us", "zh": "推送給我們"}, {"en": "imperceptibly", "zh": "不知不覺地（細微到難以察覺）"}, {"en": "echo chambers", "zh": "同溫層"}, {"en": "dissenting views", "zh": "相左的意見"}, {"en": "unwittingly", "zh": "不知不覺地；在不自知的情況下"}], "point": "「同溫層」英文常說 echo chamber 或 filter bubble。「不知不覺地」可用 imperceptibly（變化細微到難以察覺）或 unwittingly（當事人並未意識到），兩者著眼點略有不同。句尾 cut off from dissenting views 為省略 being 的分詞片語，補充說明結果；alt 中 with + O + V-ing 為表原因或伴隨狀況的獨立構句。dissenting 意為「持不同意見的」。", "topic": "algorithms and media", "level": "C2"}, {"id": "T356", "zh": "「你覺得他那本新小說寫得怎麼樣？」「嗯……封面倒是設計得相當用心。」", "en": "\"What did you think of his new novel?\" \"Hmm... the cover, at any rate, was designed with real care.\"", "alt": ["\"How did you find his new novel?\" \"Well... I'll say this for it: a lot of thought clearly went into the cover.\""], "keys": [{"en": "How did you find", "zh": "你覺得……怎麼樣（find 意為「覺得」）"}, {"en": "at any rate", "zh": "至少；無論如何（表讓步）"}, {"en": "with real care", "zh": "相當用心地"}, {"en": "I'll say this for it", "zh": "別的不說，至少這一點值得肯定"}, {"en": "went into", "zh": "（心思）投入於"}], "point": "這是「明褒實貶」（damning with faint praise）的例子：對方問的是小說內容，回答者卻只稱讚封面，言外之意是內容乏善可陳。「倒是」帶有讓步語氣，可用 at any rate、at least 或 I'll say this for it 表達「別的不說，至少……」。How did you find…? 是詢問感想的道地說法，find 在此意為「覺得」，與 What did you think of…? 意思相同。a lot of thought went into sth 意為「在某事上花了很多心思」。", "topic": "book reviews", "level": "C2"}, {"id": "T357", "zh": "「這份報告下週一前趕得出來嗎？」「也不是不可能，只是品質方面我可不敢打包票。」", "en": "\"Can you get this report done by Monday?\" \"It's not impossible, but I wouldn't want to vouch for the quality.\"", "alt": ["\"Will the report be ready by next Monday?\" \"It's not out of the question, but I couldn't guarantee its quality, I'm afraid.\""], "keys": [{"en": "by Monday", "zh": "在（下）週一前"}, {"en": "not impossible", "zh": "不是不可能"}, {"en": "vouch for", "zh": "擔保；打包票"}, {"en": "not out of the question", "zh": "並非不可能"}], "point": "not impossible 以否定詞加否定意義的形容詞構成「反敘法」（litotes），語氣比 possible 保留得多，暗示「有困難」；not out of the question 意思相近。「打包票」可譯為 vouch for 或 guarantee；I wouldn't want to… / I couldn't… 以假設語氣的助動詞使回答更委婉，I'm afraid 進一步緩和語氣。「趕得出來」可用 get sth done by + 時間。", "topic": "deadlines", "level": "C2"}, {"id": "T358", "zh": "老舊街區經過翻新後，房租隨之水漲船高，原本住在那裡的居民反而被迫遷離；這種現象就是所謂的「仕紳化」。", "en": "Once a run-down neighborhood has been renovated, rents climb accordingly, and, ironically, the very people who used to live there are priced out; this is what is meant by \"gentrification.\"", "alt": ["When an old neighborhood is given a makeover, rents rise in turn, and rather than benefiting, its original residents are forced out — the phenomenon known as gentrification."], "keys": [{"en": "run-down", "zh": "老舊破敗的；年久失修的"}, {"en": "the very people", "zh": "（反而）正是原本……的那些人"}, {"en": "priced out", "zh": "因價格過高而被迫離開"}, {"en": "given a makeover", "zh": "翻新；改頭換面"}, {"en": "gentrification", "zh": "仕紳化"}], "point": "be priced out (of…) 指「因房租、房價等上漲而負擔不起，被迫退出」，精準傳達「被迫遷離」的原因。the very + N 強調「正是那些……」，凸顯諷刺意味；「反而」可用 ironically 或 rather than benefiting 表達與預期相反。run-down 意為「年久失修的」；「水漲船高」此處意譯為 climb accordingly / rise in turn 即可。gentrification 在台灣多譯作「仕紳化」或「士紳化」。", "topic": "urban change", "level": "C2"}, {"id": "T359", "zh": "約翰‧凱吉的《4分33秒》要求演奏者從頭到尾不演奏任何一個音符；作曲家想藉此讓聽眾明白，絕對的寂靜根本不存在。", "en": "John Cage's 4′33″ requires the performer not to play a single note from beginning to end; through it, the composer sought to make the audience realize that there is no such thing as absolute silence.", "alt": ["In John Cage's 4′33″, the performer is instructed to play not one note throughout; the composer's aim was to show listeners that absolute silence simply does not exist."], "keys": [{"en": "not to play a single note", "zh": "不演奏任何一個音符"}, {"en": "from beginning to end", "zh": "從頭到尾"}, {"en": "sought to", "zh": "試圖；想要（seek to 的過去式）"}, {"en": "there is no such thing as", "zh": "根本沒有……這回事"}, {"en": "absolute silence", "zh": "絕對的寂靜"}], "point": "require sb (not) to V 表「要求某人（不）做……」；not a single + N 強調「連一個都沒有」。there is no such thing as… 是「根本不存在……」的慣用句型，語氣比 does not exist 更強烈。seek to V（過去式 sought）為 try to 的正式說法；through it 中的 it 指這件作品，表「藉此」。作品名稱 4′33″ 讀作 four minutes thirty-three seconds，也常簡稱 four thirty-three。", "topic": "modern music", "level": "C2"}, {"id": "T360", "zh": "韋格納在 1912 年提出大陸漂移說時，許多地質學家對此不屑一顧；直到他去世數十年後，板塊構造學說逐漸確立，他的見解才終於得到平反。", "en": "When Wegener proposed his theory of continental drift in 1912, many geologists dismissed it out of hand; it was not until decades after his death, when plate tectonics gained acceptance, that his ideas were finally vindicated.", "alt": ["Wegener's theory of continental drift, put forward in 1912, was brushed aside by many geologists, and only decades after his death, with the rise of plate tectonics, were his insights at last vindicated."], "keys": [{"en": "continental drift", "zh": "大陸漂移說"}, {"en": "dismissed it out of hand", "zh": "對此不屑一顧；斷然否定"}, {"en": "it was not until", "zh": "直到……才"}, {"en": "plate tectonics", "zh": "板塊構造學說"}, {"en": "vindicated", "zh": "得到平反；被證明是正確的"}], "point": "dismiss sth out of hand 意為「不假思索地否定、不屑一顧」；brush aside 亦有「漠視、置之不理」之意。vindicate 指「事後證明某人或其主張是正確的，還其公道」，是「平反」的貼切譯法。「直到……才」可用強調句 it was not until… that…，或將 only + 時間副詞片語置於句首並倒裝（only decades after his death… were his insights vindicated）。", "topic": "geology", "level": "C2"}, {"id": "T361", "zh": "1987 年簽訂的《蒙特婁議定書》逐步淘汰了會破壞臭氧層的化學物質，至今仍常被譽為國際環境合作最成功的範例之一。", "en": "The Montreal Protocol, signed in 1987, phased out chemicals that deplete the ozone layer, and it is still widely hailed as one of the most successful examples of international environmental cooperation.", "alt": ["Signed in 1987, the Montreal Protocol gradually eliminated ozone-depleting chemicals and continues to be lauded as one of the greatest success stories of international cooperation on the environment."], "keys": [{"en": "phased out", "zh": "逐步淘汰"}, {"en": "deplete", "zh": "耗損；使大量減少"}, {"en": "hailed as", "zh": "被譽為"}, {"en": "ozone-depleting", "zh": "破壞臭氧層的"}, {"en": "lauded as", "zh": "被讚揚為"}], "point": "phase out 為「逐步淘汰」的固定說法；deplete 意為「耗盡、使大量減少」，ozone-depleting 為複合形容詞。「被譽為」可用 be hailed as 或 be lauded as，褒揚意味比 be called 強得多。過去分詞片語 signed in 1987 可作插入語，也可移到句首。one of the most + adj. + 複數名詞表「最……之一」；success story 指「成功的範例」。", "topic": "ozone layer", "level": "C2"}, {"id": "T362", "zh": "許多看似自信滿滿的專業人士，私底下其實常懷疑自己的成就不過是僥倖，深怕有朝一日會被人識破。", "en": "Many professionals who appear supremely self-assured often secretly suspect that their success is nothing but a fluke, and live in dread of being found out one day.", "alt": ["Plenty of seemingly confident professionals privately harbor doubts that their accomplishments are anything more than luck, fearing that sooner or later they will be exposed as frauds."], "keys": [{"en": "self-assured", "zh": "自信滿滿的"}, {"en": "a fluke", "zh": "僥倖"}, {"en": "live in dread of", "zh": "深怕；一直害怕"}, {"en": "found out", "zh": "被識破"}, {"en": "harbor doubts", "zh": "心存懷疑"}], "point": "fluke 指「僥倖、意外的好運」；be found out 意為「（秘密或偽裝）被人識破」；live in dread of + V-ing 表「長期活在對……的恐懼中」。alt 中 doubt that… anything more than… 以帶否定語意的 doubt 搭配 any，語氣精鍊；be exposed as a fraud 意為「被揭穿是冒牌貨」。這種心理現象常稱為「冒牌者症候群」（impostor syndrome）。", "topic": "workplace psychology", "level": "C2"}, {"id": "T363", "zh": "有人把久坐形容為「新型態的吸菸」；這種說法或許有些言過其實，但長時間不活動對健康的危害確實不容小覷。", "en": "Prolonged sitting has been dubbed \"the new smoking\"; the comparison may be something of an overstatement, but the health risks of long periods of inactivity are certainly not to be underestimated.", "alt": ["Some people have called sitting for long periods \"the new smoking.\" While that may be overstating the case, the dangers that prolonged inactivity poses to our health should by no means be dismissed."], "keys": [{"en": "dubbed", "zh": "被稱為；被冠上……的稱號"}, {"en": "something of an overstatement", "zh": "有點言過其實"}, {"en": "not to be underestimated", "zh": "不容小覷"}, {"en": "overstating the case", "zh": "言過其實；誇大其詞"}, {"en": "inactivity", "zh": "缺乏活動"}], "point": "dub 意為「給……取綽號、冠上稱號」；something of a + N 表「有幾分……、可說是……」，是委婉保留的說法；overstate the case 為「誇大其詞」的慣用語。「不容小覷」可譯為 are not to be underestimated（be + to V 可表「應該」，此處為被動否定 be not to be p.p.，意為「不應被……」）或 should by no means be dismissed。may…, but… 先讓步再轉折，是議論文中常見的平衡論述方式。", "topic": "sedentary lifestyles", "level": "C2"}, {"id": "T364", "zh": "說到底，我們害怕的往往不是改變本身，而是改變所帶來的種種未知。", "en": "At the end of the day, what we fear is often not change per se, but the many unknowns that come with it.", "alt": ["When all is said and done, it is usually not so much change itself that frightens us as all the uncertainty it brings."], "keys": [{"en": "At the end of the day", "zh": "說到底"}, {"en": "per se", "zh": "本身；就其本身而言"}, {"en": "unknowns", "zh": "未知的事物"}, {"en": "come with it", "zh": "隨之而來"}, {"en": "when all is said and done", "zh": "說到底；歸根究柢"}], "point": "per se（拉丁文，意為「本身」）常置於名詞之後，表「就其本身而言」；unknown 作可數名詞時指「未知的事物」。「不是 A，而是 B」可用 not A but B；alt 則以 not so much A as B（與其說是 A，不如說是 B）結合強調句 it is… that…。at the end of the day 與 when all is said and done 都是「說到底」的慣用語；come with 表「伴隨而來」。", "topic": "everyday reflections", "level": "C2"}, {"id": "T365", "zh": "社會心理學中的「旁觀者效應」指出，在場的人越多，每個人出手相助的可能性反而越低，因為大家都以為別人會挺身而出。", "en": "The bystander effect, a phenomenon identified by social psychologists, shows that, paradoxically, the more people are present, the less likely each individual is to help, as everyone assumes that someone else will step in.", "alt": ["What social psychologists term the bystander effect suggests that the larger the number of onlookers, the smaller the chance that any one of them will lend a hand, because each person takes it for granted that somebody else will intervene."], "keys": [{"en": "bystander effect", "zh": "旁觀者效應"}, {"en": "shows that", "zh": "指出；顯示"}, {"en": "the less likely", "zh": "越不可能"}, {"en": "step in", "zh": "出面；挺身而出"}, {"en": "takes it for granted", "zh": "想當然耳地認為"}], "point": "「越……越……」用 the + 比較級…, the + 比較級…；第二部分 the less likely each individual is to help 由 be likely to V 變化而來，形容詞 likely 須隨 the less 移到子句前面。show that… 意為「顯示、指出」，描述研究結果或現象時常用 show 或 suggest（alt），hold that… 則多用於理論、學說的「主張」；step in / intervene 指「出面干預」；take it for granted that… 表「想當然耳地認為」，it 為虛受詞。paradoxically 傳達中文「反而」所含的違反直覺之意。", "topic": "social psychology", "level": "C2"}, {"id": "T366", "zh": "摩爾定律並非自然法則，而是一項觀察；它之所以能維持數十年，某種程度上是因為整個半導體產業都把它當成必須達成的目標。", "en": "Moore's law is not a law of nature but an observation; the reason it held true for decades is, in part, that the entire semiconductor industry treated it as a target to be met.", "alt": ["Far from being a law of nature, Moore's law is merely an observation, and it owes its decades-long run partly to the fact that the whole chip industry regarded it as a goal it had to achieve."], "keys": [{"en": "law of nature", "zh": "自然法則"}, {"en": "held true", "zh": "成立；維持有效"}, {"en": "in part", "zh": "某種程度上；部分"}, {"en": "a target to be met", "zh": "必須達成的目標"}, {"en": "owes its", "zh": "（某事）歸功於"}], "point": "「之所以……是因為……」可用 the reason (why) S + V is that…，避免 the reason… is because… 的冗贅用法；hold true 意為「（定律、說法）成立」。a target to be met 中的不定詞被動式表「應被達成的」，meet a target 為「達成目標」的固定搭配。owe sth to… 表「某事歸功於……」；Far from being… 表「非但不是……」。這種因眾人相信而使預測成真的現象，常稱為「自我實現的預言」（self-fulfilling prophecy）。", "topic": "semiconductors", "level": "C2"}, {"id": "T367", "zh": "絲路其實不是單一的一條路，而是一張橫跨歐亞大陸的貿易網；沿著它流通的，除了絲綢與香料之外，還有宗教、技術，甚至疾病。", "en": "The Silk Road was in fact no single road at all, but a web of trade routes spanning Eurasia; along its routes flowed not only silk and spices but also religions, technologies and even diseases.", "alt": ["Rather than one road, the Silk Road was a network of trade routes stretching across Europe and Asia, carrying not just silk and spices but also religions, technologies, and even disease."], "keys": [{"en": "no single road at all", "zh": "根本不是單一的一條路"}, {"en": "a web of", "zh": "一張……的網"}, {"en": "spanning Eurasia", "zh": "橫跨歐亞大陸"}, {"en": "along its routes flowed", "zh": "沿著它的路線流通的（倒裝句）"}, {"en": "stretching across", "zh": "橫跨；綿延"}], "point": "「不是 A，而是 B」用 no… at all, but…，加強否定語氣。web 與 network 都可表「網」；現在分詞片語 spanning Eurasia 修飾 routes，span 意為「橫跨」。along its routes flowed… 是地方副詞片語置於句首、主詞與動詞倒裝的句型，主詞很長時可避免頭重腳輕，也更具文采。not only A but also B 須連接對等的名詞。", "topic": "trade history", "level": "C2"}, {"id": "T368", "zh": "在普魯斯特的小說中，一塊浸過茶的瑪德蓮蛋糕，竟喚起了敘事者塵封已久的童年記憶。", "en": "In Proust's novel, it is, of all things, a madeleine dipped in tea that awakens the narrator's long-buried childhood memories.", "alt": ["In Proust's novel, a humble madeleine soaked in tea unexpectedly brings back memories of childhood that the narrator has long since forgotten."], "keys": [{"en": "of all things", "zh": "偏偏是；竟然是"}, {"en": "dipped in tea", "zh": "浸過茶的"}, {"en": "awakens", "zh": "喚起"}, {"en": "long-buried", "zh": "塵封已久的"}, {"en": "long since", "zh": "早已"}], "point": "of all things 插入句中，表「偏偏是、竟然是（出人意料的事物）」，與強調句 it is… that… 結合，凸顯「一塊小蛋糕竟有如此力量」的意外感，對應「竟」。過去分詞片語 dipped in tea 修飾 madeleine；long-buried 為複合形容詞，字面意為「埋藏已久的」，貼合「塵封已久」；long since 意為「早已」。這段情節出自《追憶似水年華》第一卷。", "topic": "literature", "level": "C2"}, {"id": "T369", "zh": "所謂的「蝴蝶效應」，並不是說一隻蝴蝶真的能引發一場龍捲風，而是指在某些系統中，初始條件的些微差異，可能導致天差地遠的結果。", "en": "The so-called butterfly effect does not mean that a butterfly can literally set off a tornado; rather, it describes how, in certain systems, minute differences in initial conditions can lead to vastly different outcomes.", "alt": ["The butterfly effect is not a claim that a single butterfly could actually trigger a tornado, but the idea that in some systems, tiny variations in starting conditions may produce wildly divergent results."], "keys": [{"en": "so-called", "zh": "所謂的"}, {"en": "literally", "zh": "真的；照字面意義地"}, {"en": "set off", "zh": "引發"}, {"en": "minute", "zh": "極微小的"}, {"en": "initial conditions", "zh": "初始條件"}], "point": "so-called 表「所謂的」，但有時帶有懷疑或不以為然的語氣，若要完全中性，可用 what is known as…；literally 強調「照字面意義、真的」；set off 與 trigger 皆意為「引發」。minute 作形容詞時讀作 /maɪˈnjuːt/，意為「極微小的」，與名詞「分鐘」的發音不同。「天差地遠」可譯為 vastly different 或 wildly divergent。rather 置於分號之後，表「更確切地說、而是」，承接前句的否定。", "topic": "chaos theory", "level": "C2"}, {"id": "T370", "zh": "明知這項計畫注定失敗，主管卻因為捨不得先前投入的大筆資金而遲遲不肯喊停；這正是典型的「沉沒成本謬誤」。", "en": "Despite knowing full well that the project was doomed, the manager kept refusing to pull the plug, unwilling to write off the huge sums already invested in it — a textbook example of the sunk cost fallacy.", "alt": ["Fully aware that the project was bound to fail, the manager nevertheless hesitated to call a halt, reluctant to let go of the large amount of money already poured into it; this is a classic instance of the sunk cost fallacy."], "keys": [{"en": "knowing full well", "zh": "明知"}, {"en": "doomed", "zh": "注定失敗的"}, {"en": "pull the plug", "zh": "喊停；終止（計畫）"}, {"en": "write off", "zh": "認賠；一筆勾銷"}, {"en": "a textbook example of", "zh": "典型的……例子"}], "point": "Despite knowing full well… 表「儘管明知……」，full well 加強語氣。pull the plug (on sth) 原指拔掉插頭，引申為「終止計畫」；write off 指「認列損失、不再指望收回」。unwilling to… 為置於逗號後的形容詞片語，說明主詞的心態。a textbook example of… 意為「教科書般典型的……例子」。sunk cost fallacy 指因不願放棄已投入的成本，而持續投入更多資源的非理性決策。", "topic": "business decisions", "level": "C2"}, {"id": "T371", "zh": "光害不僅讓都市居民幾乎看不見銀河，也會干擾候鳥遷徙，還會使剛孵化的小海龜受岸上燈光吸引，爬往與大海相反的方向。", "en": "Light pollution not only leaves city dwellers all but unable to see the Milky Way but also disrupts bird migration and lures newly hatched sea turtles toward the lights on shore, so that they crawl away from the sea instead of into it.", "alt": ["Besides making the Milky Way virtually invisible to city residents, light pollution interferes with the migration of birds and draws turtle hatchlings toward the lights on land, sending them crawling in the wrong direction, away from the ocean."], "keys": [{"en": "light pollution", "zh": "光害"}, {"en": "all but", "zh": "幾乎（完全）"}, {"en": "the Milky Way", "zh": "銀河"}, {"en": "lures", "zh": "引誘；吸引"}, {"en": "hatchlings", "zh": "剛孵化的幼體"}], "point": "all but + adj. / V 意為「幾乎」（all but unable = 幾乎無法），須與 anything but（絕不）區分；leave sb + adj. 表「使某人處於某種狀態」。lure 指「引誘、誘使」；hatchling 為「剛孵化的幼體」。not only… but also… 後接三個並列的動詞片語時，須保持結構一致（leaves… / disrupts… / lures…）。so that… 表結果；crawl away from the sea instead of into it 中 into it 承前省略了 crawl。", "topic": "light pollution", "level": "C2"}, {"id": "T372", "zh": "「原來聚餐改到明天了？你大可早點告訴我的，我今天還特地推掉了別的約。」「真抱歉，我以為群組裡的訊息你已經看到了。」", "en": "\"So the dinner's been moved to tomorrow? You might have told me sooner — I even turned down another invitation to keep today free.\" \"I'm so sorry. I assumed you'd already seen the message in the group chat.\"", "alt": ["\"The dinner's tomorrow now? You could at least have let me know earlier! I went out of my way to cancel other plans for today.\" \"Sorry about that — I thought you'd seen the message in the group.\""], "keys": [{"en": "might have told me", "zh": "（你）大可早點告訴我（表責備）"}, {"en": "could at least have", "zh": "至少可以……（卻沒有）"}, {"en": "went out of my way", "zh": "特地"}, {"en": "assumed", "zh": "（原本）以為"}, {"en": "group chat", "zh": "群組"}], "point": "might have / could have + p.p. 除表推測外，也可表達對過去「本可做卻沒做」之事的責備，相當於「你大可……的」；加上 at least 語氣更強。go out of one's way to V 意為「特地、刻意費心做某事」；turn down an invitation 表「推掉邀約」。So the dinner's been moved…? 以直述句加問號表驚訝與確認，對應「原來……？」；I assumed… 表「我原以為（其實不然）」。", "topic": "social plans", "level": "C2"}, {"id": "T373", "zh": "「你覺得他真的會為了升遷而把同事的功勞據為己有嗎？」「以他的為人，我看他做得出來。」", "en": "\"Do you really think he'd take credit for a colleague's work just to get promoted?\" \"Knowing him, I wouldn't put it past him.\"", "alt": ["\"Would he honestly claim a co-worker's achievements as his own to win a promotion?\" \"Given the kind of person he is, I wouldn't be surprised if he did.\""], "keys": [{"en": "take credit for", "zh": "把……的功勞歸於自己"}, {"en": "Knowing him", "zh": "以他的為人（依我對他的了解）"}, {"en": "wouldn't put it past him", "zh": "（我認為）他做得出這種事"}, {"en": "as his own", "zh": "據為己有"}, {"en": "wouldn't be surprised if he did", "zh": "他真這麼做我也不意外"}], "point": "I wouldn't put it past sb (to V) 意為「我認為某人做得出這種（不好的）事」，帶有負面評價，是道地的口語慣用語，回答中省略了 to take credit…。Knowing him 為分詞構句，相當於 Because I know him，即「以他的為人」。take credit for sth 表「把……的功勞歸於自己」，claim sth as one's own 亦表「據為己有」。I wouldn't be surprised if he did 中的 did 代替 claimed…，屬「代換」（substitution）用法，以避免重複。", "topic": "office politics", "level": "C2"}, {"id": "T374", "zh": "攝影術在十九世紀問世時，曾有人斷言繪畫將從此沒落；事實證明，攝影反而促使畫家另闢蹊徑，間接催生出更多元的藝術風格。", "en": "When photography appeared in the nineteenth century, some declared that painting was finished; as it turned out, photography, if anything, pushed painters to strike out in new directions, indirectly fostering a far wider range of artistic styles.", "alt": ["Some predicted that the advent of photography in the nineteenth century would spell the end of painting, but in fact it spurred painters to forge new paths, and in so doing indirectly gave rise to more diverse styles of art."], "keys": [{"en": "as it turned out", "zh": "事實證明；結果"}, {"en": "if anything", "zh": "反而；甚至可以說"}, {"en": "strike out in new directions", "zh": "另闢蹊徑"}, {"en": "the advent of", "zh": "（重要事物的）問世"}, {"en": "spell the end of", "zh": "預示……的終結"}], "point": "if anything 用於修正前述看法，表「（不但沒有……）反而」，精準傳達「反而」；as it turned out 意為「結果、事實證明」。strike out in new directions 與 forge new paths 皆可譯「另闢蹊徑」。spell the end of sth 意為「預示……的終結」，spell 此處作「意味著、招致」解；the advent of 為「（重要事物的）出現、到來」的正式說法；give rise to 表「催生、導致」；in so doing 意為「在此過程中、藉此」。", "topic": "art history", "level": "C2"}, {"id": "T375", "zh": "多讀書固然是好事，但若只是囫圇吞棗、不加思考，讀得再多，恐怕也只是過眼雲煙。", "en": "Reading widely is all well and good, but if you merely devour books without stopping to think, no amount of reading is likely to leave a lasting impression.", "alt": ["There is certainly nothing wrong with reading a lot, but if you swallow books whole without reflecting on them, however much you read, it may all prove as fleeting as passing clouds."], "keys": [{"en": "all well and good", "zh": "固然很好（但……）"}, {"en": "devour", "zh": "狼吞虎嚥地讀"}, {"en": "no amount of", "zh": "再多的……也不"}, {"en": "lasting impression", "zh": "持久的印象（不留下持久的印象，即「過眼雲煙」）"}, {"en": "swallow books whole", "zh": "囫圇吞棗地讀書"}], "point": "… is all well and good, but… 是「……固然好，但……」的慣用句型，先肯定再提出保留。devour books 本指「如饑似渴地大量閱讀」，本身未必是貶義，此處加上 merely 與 without stopping to think 才表達「囫圇吞棗」；swallow sth whole 字面意為「整個吞下」，引申為「不加思索地全盤接受」，用於讀書也能傳達同樣的意思；no amount of + N 意為「再多的……也不」，對應「讀得再多」。「過眼雲煙」可意譯為 leave no lasting impression，或保留比喻 as fleeting as passing clouds。is likely to 與 may 表推測，對應「恐怕」；however much you read 為讓步副詞子句。", "topic": "reading habits", "level": "C2"}];
